import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader


class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, index):

        name = self.pairs[index]

        # Load .npy files
        lq = np.load(
            os.path.join(self.lq_dir, name + ".npy")
        ).astype(np.float32)

        gt = np.load(
            os.path.join(self.gt_dir, name + ".npy")
        ).astype(np.float32)

        # Keep values in a stable range
        lq = np.clip(lq, 0.0, 1.0)
        gt = np.clip(gt, 0.0, 1.0)

        # Convert grayscale H,W → C,H,W
        lq = torch.from_numpy(lq).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return {
            "lq": lq,
            "gt": gt,
            "name": name
        }


# Paths
gt_dir = "/content/train_dataset/train/GT"
lq_dir = "/content/train_dataset/train/NoisyLR"

# Create datasets
train_dataset = NPYSuperResolutionDataset(
    train_pairs,
    gt_dir,
    lq_dir
)

val_dataset = NPYSuperResolutionDataset(
    val_pairs,
    gt_dir,
    lq_dir
)

print("Training dataset :", len(train_dataset))
print("Validation dataset:", len(val_dataset))

train_loader = DataLoader(
    train_dataset,
    batch_size=4,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=4,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("✅ DataLoaders created")

batch = next(iter(train_loader))

print("LQ shape :", batch["lq"].shape)
print("GT shape :", batch["gt"].shape)
print("Names    :", batch["name"][:4])

