import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, index):

        name = self.pairs[index]

        lq = np.load(
            os.path.join(self.lq_dir, name + ".npy")
        ).astype(np.float32)

        gt = np.load(
            os.path.join(self.gt_dir, name + ".npy")
        ).astype(np.float32)

        # Keep values stable
        lq = np.clip(lq, 0.0, 1.0)
        gt = np.clip(gt, 0.0, 1.0)

        # H,W → C,H,W
        lq = torch.from_numpy(lq).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return lq, gt


gt_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"
lq_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"

train_dataset = NPYSuperResolutionDataset(
    train_pairs, gt_dir, lq_dir
)

val_dataset = NPYSuperResolutionDataset(
    val_pairs, gt_dir, lq_dir
)

# Safe starting batch size for T4 ~15 GB
batch_size = 4

train_loader = DataLoader(
    train_dataset,
    batch_size=batch_size,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=batch_size,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

