import time
import torch

model.train()

epoch = 1
running_loss = 0.0
start_time = time.time()

for batch_idx, (lr, gt) in enumerate(train_loader):

    lr = lr.to(device, non_blocking=True)
    gt = gt.to(device, non_blocking=True)

    optimizer.zero_grad(set_to_none=True)

    output = model(lr)

    loss = criterion(output, gt)

    loss.backward()
    optimizer.step()

    running_loss += loss.item()

    if (batch_idx + 1) % 50 == 0:
        avg_loss = running_loss / (batch_idx + 1)

        print(
            f"Epoch {epoch} | "
            f"Batch {batch_idx + 1}/{len(train_loader)} | "
            f"Loss: {loss.item():.6f} | "
            f"Avg Loss: {avg_loss:.6f}"
        )

epoch_loss = running_loss / len(train_loader)

print("\n================================")
print("Epoch 1 completed")
print("Average training loss:", epoch_loss)
print("Time:", round((time.time() - start_time) / 60, 2), "minutes")
print("================================")

class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, index):

        name = self.pairs[index]

        lq = np.load(
            os.path.join(self.lq_dir, name + ".npy")
        ).astype(np.float32)

        gt = np.load(
            os.path.join(self.gt_dir, name + ".npy")
        ).astype(np.float32)

        # IMPORTANT:
        # Do NOT clip NoisyLR.
        # Challenge data can contain values outside [0,1].

        # GT is clean and already in [0,1]
        gt = np.clip(gt, 0.0, 1.0)

        # H,W -> C,H,W
        lq = torch.from_numpy(lq).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return lq, gt


train_dataset = NPYSuperResolutionDataset(
    train_pairs, gt_dir, lq_dir
)

val_dataset = NPYSuperResolutionDataset(
    val_pairs, gt_dir, lq_dir
)

train_loader = DataLoader(
    train_dataset,
    batch_size=4,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=4,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

