import torch
import os
import time

# ============================================
# RESUME TRAINING FROM EPOCH 2
# ============================================

checkpoint_dir = "/content/drive/MyDrive/SwinIR_Project/checkpoints"

total_epochs = 20
start_epoch = 2

print("=" * 70)
print("RESUMING SWINIR TRAINING")
print("=" * 70)
print("Starting Epoch :", start_epoch)
print("Final Epoch    :", total_epochs)
print("Remaining      :", total_epochs - start_epoch + 1, "epochs")
print("Device         :", device)
print("=" * 70)

for epoch in range(start_epoch, total_epochs + 1):

    epoch_start_time = time.time()

    # ========================================
    # TRAINING
    # ========================================

    model.train()

    running_train_loss = 0.0

    for batch_idx, (lr, hr) in enumerate(train_loader):

        lr = lr.to(device)
        hr = hr.to(device)

        optimizer.zero_grad()

        output = model(lr)

        loss = criterion(output, hr)

        loss.backward()

        optimizer.step()

        running_train_loss += loss.item()

    average_train_loss = (
        running_train_loss / len(train_loader)
    )

    # ========================================
    # VALIDATION
    # ========================================

    model.eval()

    running_val_loss = 0.0

    validation_start_time = time.time()

    with torch.no_grad():

        for lr, hr in val_loader:

            lr = lr.to(device)
            hr = hr.to(device)

            output = model(lr)

            val_loss = criterion(output, hr)

            running_val_loss += val_loss.item()

    average_val_loss = (
        running_val_loss / len(val_loader)
    )

    validation_time = (
        time.time() - validation_start_time
    ) / 60

    epoch_time = (
        time.time() - epoch_start_time
    ) / 60

    # ========================================
    # DISPLAY RESULTS
    # ========================================

    print("\n")
    print("=" * 70)
    print(f"================ EPOCH {epoch} =================")
    print("=" * 70)

    print(f"Training Loss     : {average_train_loss:.8f}")
    print(f"Validation Loss   : {average_val_loss:.8f}")
    print(f"Epoch Time        : {epoch_time:.2f} minutes")
    print(f"Validation Time   : {validation_time:.2f} minutes")

    # ========================================
    # SAVE CHECKPOINT
    # ========================================

    checkpoint_path = os.path.join(
        checkpoint_dir,
        f"swinir_epoch_{epoch}.pth"
    )

    torch.save({
        "epoch": epoch,
        "model_state_dict": model.state_dict(),
        "optimizer_state_dict": optimizer.state_dict(),
        "train_loss": average_train_loss,
        "val_loss": average_val_loss
    }, checkpoint_path)

    print(f"Checkpoint saved:")
    print(checkpoint_path)

    print("=" * 70)

print("\n")
print("=" * 70)
print("6🎉 SWINIR TRAINING COMPLETED")
print("=" * 70)
print("Final Epoch:", total_epochs)
print("=" * 70)

