import os
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader


# ============================================
# DATASET CLASS
# ============================================

class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, index):

        name = self.pairs[index]

        # Load NoisyLR
        lq = np.load(
            os.path.join(self.lq_dir, name + ".npy")
        ).astype(np.float32)

        # Load Ground Truth
        gt = np.load(
            os.path.join(self.gt_dir, name + ".npy")
        ).astype(np.float32)

        # IMPORTANT:
        # Do NOT clip NoisyLR
        # GT is clipped to [0,1]
        gt = np.clip(gt, 0.0, 1.0)

        # H,W -> C,H,W
        lq = torch.from_numpy(lq).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return lq, gt


# ============================================
# DATASET PATHS
# ============================================

gt_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"
lq_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"

train_pairs = split_data["train"]
val_pairs = split_data["val"]


# ============================================
# CREATE DATASETS
# ============================================

train_dataset = NPYSuperResolutionDataset(
    train_pairs,
    gt_dir,
    lq_dir
)

val_dataset = NPYSuperResolutionDataset(
    val_pairs,
    gt_dir,
    lq_dir
)


# ============================================
# CREATE DATALOADERS
# ============================================

batch_size = 4

train_loader = DataLoader(
    train_dataset,
    batch_size=batch_size,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=batch_size,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)


# ============================================
# CHECK
# ============================================

print("=" * 50)
print("✅ DATA LOADERS READY")
print("=" * 50)

print("Training samples   :", len(train_dataset))
print("Validation samples :", len(val_dataset))
print("Training batches   :", len(train_loader))
print("Validation batches :", len(val_loader))
print("Batch size         :", batch_size)
print("=" * 50)

import os
import time
import torch

# ============================================
# RESUME SWINIR TRAINING
# ============================================

checkpoint_dir = "/content/drive/MyDrive/SwinIR_Project/checkpoints"

start_epoch = 10
total_epochs = 20

print("=" * 70)
print("🚀 RESUMING SWINIR TRAINING")
print("=" * 70)
print("Starting Epoch :", start_epoch)
print("Final Epoch    :", total_epochs)
print("Remaining      :", total_epochs - start_epoch + 1, "epochs")
print("Device         :", device)
print("GPU            :", torch.cuda.get_device_name(0))
print("=" * 70)


for epoch in range(start_epoch, total_epochs + 1):

    epoch_start_time = time.time()

    # ========================================
    # TRAINING
    # ========================================

    model.train()

    running_train_loss = 0.0

    for batch_idx, (lr, gt) in enumerate(train_loader):

        lr = lr.to(device, non_blocking=True)
        gt = gt.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)

        output = model(lr)

        loss = criterion(output, gt)

        loss.backward()

        optimizer.step()

        running_train_loss += loss.item()

        # Progress every 50 batches
        if (batch_idx + 1) % 50 == 0:
            current_avg = running_train_loss / (batch_idx + 1)

            print(
                f"Epoch {epoch}/20 | "
                f"Batch {batch_idx + 1}/{len(train_loader)} | "
                f"Loss: {loss.item():.6f} | "
                f"Avg: {current_avg:.6f}"
            )

    average_train_loss = (
        running_train_loss / len(train_loader)
    )

    # ========================================
    # VALIDATION
    # ========================================

    model.eval()

    running_val_loss = 0.0

    validation_start_time = time.time()

    with torch.no_grad():

        for batch_idx, (lr, gt) in enumerate(val_loader):

            lr = lr.to(device, non_blocking=True)
            gt = gt.to(device, non_blocking=True)

            output = model(lr)

            val_loss = criterion(output, gt)

            running_val_loss += val_loss.item()

    average_val_loss = (
        running_val_loss / len(val_loader)
    )

    validation_time = (
        time.time() - validation_start_time
    ) / 60

    epoch_time = (
        time.time() - epoch_start_time
    ) / 60

    # ========================================
    # DISPLAY RESULTS
    # ========================================

    print("\n")
    print("=" * 70)
    print(f"================ EPOCH {epoch}/20 =================")
    print("=" * 70)

    print(f"Training Loss     : {average_train_loss:.8f}")
    print(f"Validation Loss   : {average_val_loss:.8f}")
    print(f"Epoch Time        : {epoch_time:.2f} minutes")
    print(f"Validation Time   : {validation_time:.2f} minutes")

    # ========================================
    # SAVE CHECKPOINT
    # ========================================

    checkpoint_path = os.path.join(
        checkpoint_dir,
        f"swinir_epoch_{epoch}.pth"
    )

    torch.save({
        "epoch": epoch,
        "model_state_dict": model.state_dict(),
        "optimizer_state_dict": optimizer.state_dict(),
        "train_loss": average_train_loss,
        "val_loss": average_val_loss
    }, checkpoint_path)

    print("\n✅ Checkpoint saved:")
    print(checkpoint_path)

    print("=" * 70)


print("\n")
print("=" * 70)
print("🎉 SWINIR TRAINING COMPLETED")
print("=" * 70)
print("Final Epoch:", total_epochs)
print("=" * 70)

