# SWINIR TRAINING: RESUME FROM EPOCH 15 → EPOCH 20
# ============================================================

import os
import time
import torch

# Make sure model is on GPU
model = model.to(device)

# Total epochs
num_epochs = 20

# Start from Epoch 15
start_epoch = 15

# Checkpoint directory
checkpoint_dir = "/content/drive/MyDrive/SwinIR_Project"
os.makedirs(checkpoint_dir, exist_ok=True)

print("=" * 65)
print("🚀 RESUMING SWINIR TRAINING")
print("=" * 65)
print("Device        :", device)
print("Starting Epoch:", start_epoch)
print("Final Epoch   :", num_epochs)
print("Remaining     :", num_epochs - start_epoch + 1)
print("=" * 65)

for epoch in range(start_epoch, num_epochs + 1):

    epoch_start_time = time.time()

    # ========================================================
    # TRAINING
    # ========================================================
    model.train()

    running_train_loss = 0.0

    for lr_imgs, hr_imgs in train_loader:

        lr_imgs = lr_imgs.to(device, non_blocking=True)
        hr_imgs = hr_imgs.to(device, non_blocking=True)

        optimizer.zero_grad()

        # Forward pass
        sr_imgs = model(lr_imgs)

        # Loss
        loss = criterion(sr_imgs, hr_imgs)

        # Backpropagation
        loss.backward()

        # Update weights
        optimizer.step()

        running_train_loss += loss.item()

    avg_train_loss = running_train_loss / len(train_loader)

    # ========================================================
    # VALIDATION
    # ========================================================
    model.eval()

    running_val_loss = 0.0

    with torch.no_grad():

        for lr_imgs, hr_imgs in val_loader:

            lr_imgs = lr_imgs.to(device, non_blocking=True)
            hr_imgs = hr_imgs.to(device, non_blocking=True)

            sr_imgs = model(lr_imgs)

            val_loss = criterion(sr_imgs, hr_imgs)

            running_val_loss += val_loss.item()

    avg_val_loss = running_val_loss / len(val_loader)

    # ========================================================
    # TIME
    # ========================================================
    epoch_time = (time.time() - epoch_start_time) / 60

    # ========================================================
    # SAVE CHECKPOINT
    # ========================================================
    checkpoint_path = os.path.join(
        checkpoint_dir,
        f"swinir_epoch_{epoch}.pth"
    )

    torch.save({
        "epoch": epoch,
        "model_state_dict": model.state_dict(),
        "optimizer_state_dict": optimizer.state_dict(),
        "train_loss": avg_train_loss,
        "val_loss": avg_val_loss
    }, checkpoint_path)

    # ========================================================
    # DISPLAY RESULTS
    # ========================================================
    print("\n" + "=" * 65)
    print(f"✅ EPOCH {epoch}/20 COMPLETED")
    print("=" * 65)
    print(f"Training Loss : {avg_train_loss:.6f}")
    print(f"Validation Loss: {avg_val_loss:.6f}")
    print(f"Time          : {epoch_time:.2f} minutes")
    print(f"Checkpoint    : {checkpoint_path}")
    print("=" * 65)

print("\n🎉🎉🎉 TRAINING COMPLETED: EPOCH 20 🎉🎉🎉")
print("Final checkpoint:")
print("/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth")

