import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

# Dataset paths
GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"
LQ_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"

# Split file
SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

# ------------------------------------------------------------
# Dataset class
# ------------------------------------------------------------

class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, idx):

        name = self.pairs[idx]

        lq_path = os.path.join(self.lq_dir, name + ".npy")
        gt_path = os.path.join(self.gt_dir, name + ".npy")

        lq = np.load(lq_path).astype(np.float32)
        gt = np.load(gt_path).astype(np.float32)

        lq = np.clip(lq, 0, 1)
        gt = np.clip(gt, 0, 1)

        # H,W -> C,H,W
        if lq.ndim == 2:
            lq = np.expand_dims(lq, axis=0)

        if gt.ndim == 2:
            gt = np.expand_dims(gt, axis=0)

        lq = torch.from_numpy(lq)
        gt = torch.from_numpy(gt)

        return lq, gt


# ------------------------------------------------------------
# Load train/validation split
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

train_pairs = split["train"]
val_pairs = split["val"]

print("Train samples :", len(train_pairs))
print("Val samples   :", len(val_pairs))


# ------------------------------------------------------------
# Create datasets
# ------------------------------------------------------------

train_dataset = NPYSuperResolutionDataset(
    train_pairs,
    GT_DIR,
    LQ_DIR
)

val_dataset = NPYSuperResolutionDataset(
    val_pairs,
    GT_DIR,
    LQ_DIR
)


# ------------------------------------------------------------
# Create DataLoaders
# ------------------------------------------------------------

train_loader = DataLoader(
    train_dataset,
    batch_size=4,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=4,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("=" * 60)
print("✅ DATALOADERS CREATED SUCCESSFULLY")
print("=" * 60)
print("Train batches :", len(train_loader))
print("Val batches   :", len(val_loader))
print("Batch size    :", 4)

