import torch
import os
import time

checkpoint_path = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_14.pth"

# ------------------------------------------------------------
# LOAD EPOCH 14 CHECKPOINT
# ------------------------------------------------------------
print("=" * 60)
print("LOADING EPOCH-14 CHECKPOINT")
print("=" * 60)

checkpoint = torch.load(
    checkpoint_path,
    map_location=device
)

model.load_state_dict(checkpoint["model_state_dict"])
optimizer.load_state_dict(checkpoint["optimizer_state_dict"])

completed_epoch = checkpoint["epoch"]
previous_train_loss = checkpoint.get("train_loss", None)
previous_val_loss = checkpoint.get("val_loss", None)

print("✅ Checkpoint loaded successfully")
print("Completed Epoch :", completed_epoch)
print("Previous Train Loss :", previous_train_loss)
print("Previous Val Loss   :", previous_val_loss)

# ------------------------------------------------------------
# TRAINING SETTINGS
# ------------------------------------------------------------
total_epochs = 20
start_epoch = completed_epoch + 1

print("\n" + "=" * 60)
print("STARTING TRAINING")
print("=" * 60)
print("Starting Epoch :", start_epoch)
print("Final Epoch    :", total_epochs)
print("Remaining      :", total_epochs - completed_epoch)
print("Device         :", device)
print("=" * 60)

# ------------------------------------------------------------
# TRAIN EPOCHS 15 → 20
# ------------------------------------------------------------
for epoch in range(start_epoch, total_epochs + 1):

    epoch_start = time.time()

    # ========================================================
    # TRAIN
    # ========================================================
    model.train()

    running_train_loss = 0.0

    for batch_idx, (lq, gt) in enumerate(train_loader):

        lq = lq.to(device, non_blocking=True)
        gt = gt.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)

        output = model(lq)

        loss = criterion(output, gt)

        loss.backward()

        optimizer.step()

        running_train_loss += loss.item()

        if (batch_idx + 1) % 100 == 0:
            print(
                f"Epoch {epoch}/{total_epochs} | "
                f"Batch {batch_idx + 1}/{len(train_loader)} | "
                f"Loss: {loss.item():.6f}"
            )

    avg_train_loss = running_train_loss / len(train_loader)

    # ========================================================
    # VALIDATION
    # ========================================================
    model.eval()

    running_val_loss = 0.0

    with torch.no_grad():

        for lq, gt in val_loader:

            lq = lq.to(device, non_blocking=True)
            gt = gt.to(device, non_blocking=True)

            output = model(lq)

            val_loss = criterion(output, gt)

            running_val_loss += val_loss.item()

    avg_val_loss = running_val_loss / len(val_loader)

    epoch_time = (time.time() - epoch_start) / 60

    # ========================================================
    # SAVE CHECKPOINT
    # ========================================================
    save_path = (
        f"/content/drive/MyDrive/SwinIR_Project/"
        f"swinir_epoch_{epoch}.pth"
    )

    torch.save(
        {
            "epoch": epoch,
            "model_state_dict": model.state_dict(),
            "optimizer_state_dict": optimizer.state_dict(),
            "train_loss": avg_train_loss,
            "val_loss": avg_val_loss,
        },
        save_path
    )

    # ========================================================
    # PRINT RESULTS
    # ========================================================
    print("\n" + "=" * 60)
    print(f"✅ EPOCH {epoch} COMPLETED")
    print("=" * 60)
    print(f"Training Loss : {avg_train_loss:.6f}")
    print(f"Validation Loss : {avg_val_loss:.6f}")
    print(f"Time : {epoch_time:.2f} minutes")
    print(f"Checkpoint : {save_path}")
    print("=" * 60)

