# SWINIR - OOM SAFE FINAL TRAINING
# Epoch 15 -> 20
# Batch size = 1
# Gradient accumulation = 4
# Mixed Precision = FP16
# ============================================================

import torch
import time
import gc
from torch.utils.data import DataLoader

# ------------------------------------------------------------
# CLEAR GPU MEMORY
# ------------------------------------------------------------
gc.collect()
torch.cuda.empty_cache()

print("=" * 60)
print("GPU MEMORY BEFORE TRAINING")
print("=" * 60)

free_mem, total_mem = torch.cuda.mem_get_info()
print(f"Free GPU memory : {free_mem / 1024**3:.2f} GB")
print(f"Total GPU memory: {total_mem / 1024**3:.2f} GB")

# ------------------------------------------------------------
# RECREATE LOADERS WITH BATCH SIZE 1
# ------------------------------------------------------------
train_loader = DataLoader(
    train_dataset,
    batch_size=1,
    shuffle=True,
    num_workers=0,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=1,
    shuffle=False,
    num_workers=0,
    pin_memory=True
)

print("\nTrain samples :", len(train_dataset))
print("Val samples   :", len(val_dataset))
print("Train batches :", len(train_loader))
print("Val batches   :", len(val_loader))
print("Batch size    : 1")
print("Accumulation  : 4")

# ------------------------------------------------------------
# MODEL + LOSS
# ------------------------------------------------------------
model = model.to(device)
criterion = torch.nn.L1Loss()

# ------------------------------------------------------------
# LOAD EPOCH 14 AGAIN
# ------------------------------------------------------------
checkpoint_path = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_14.pth"

checkpoint = torch.load(
    checkpoint_path,
    map_location=device
)

model.load_state_dict(checkpoint["model_state_dict"])
optimizer.load_state_dict(checkpoint["optimizer_state_dict"])

completed_epoch = checkpoint["epoch"]

print("\n" + "=" * 60)
print("✅ EPOCH-14 CHECKPOINT LOADED")
print("=" * 60)
print("Completed Epoch :", completed_epoch)

# ------------------------------------------------------------
# MIXED PRECISION
# ------------------------------------------------------------
scaler = torch.cuda.amp.GradScaler()

TOTAL_EPOCHS = 20
START_EPOCH = completed_epoch + 1
ACCUMULATION_STEPS = 4

print("\n" + "=" * 60)
print("STARTING OOM-SAFE TRAINING")
print("=" * 60)
print("Starting Epoch :", START_EPOCH)
print("Final Epoch    :", TOTAL_EPOCHS)
print("Batch size     : 1")
print("Effective batch: 4")
print("AMP            : FP16")
print("Device         :", device)
print("=" * 60)

# ------------------------------------------------------------
# TRAINING
# ------------------------------------------------------------
for epoch in range(START_EPOCH, TOTAL_EPOCHS + 1):

    epoch_start = time.time()

    model.train()

    train_loss_total = 0.0

    optimizer.zero_grad(set_to_none=True)

    for batch_idx, (lq, gt) in enumerate(train_loader):

        lq = lq.to(device, non_blocking=True)
        gt = gt.to(device, non_blocking=True)

        # Mixed precision forward
        with torch.cuda.amp.autocast():

            output = model(lq)

            loss = criterion(output, gt)

            # Divide for gradient accumulation
            loss_scaled = loss / ACCUMULATION_STEPS

        scaler.scale(loss_scaled).backward()

        # Optimizer step every 4 samples
        if (
            (batch_idx + 1) % ACCUMULATION_STEPS == 0
            or (batch_idx + 1) == len(train_loader)
        ):

            scaler.step(optimizer)
            scaler.update()

            optimizer.zero_grad(set_to_none=True)

        train_loss_total += loss.item()

        # Free temporary tensors
        del output, loss, loss_scaled, lq, gt

        if (batch_idx + 1) % 100 == 0:

            print(
                f"Epoch {epoch}/20 | "
                f"Batch {batch_idx + 1}/{len(train_loader)} | "
                f"Loss: {train_loss_total / (batch_idx + 1):.6f}"
            )

    avg_train_loss = train_loss_total / len(train_loader)

    # --------------------------------------------------------
    # VALIDATION
    # --------------------------------------------------------
    model.eval()

    val_loss_total = 0.0

    with torch.no_grad():

        for batch_idx, (lq, gt) in enumerate(val_loader):

            lq = lq.to(device, non_blocking=True)
            gt = gt.to(device, non_blocking=True)

            with torch.cuda.amp.autocast():

                output = model(lq)

                val_loss = criterion(output, gt)

            val_loss_total += val_loss.item()

            del output, val_loss, lq, gt

    avg_val_loss = val_loss_total / len(val_loader)

    # --------------------------------------------------------
    # SAVE CHECKPOINT
    # --------------------------------------------------------
    save_path = (
        f"/content/drive/MyDrive/SwinIR_Project/"
        f"swinir_epoch_{epoch}.pth"
    )

    torch.save(
        {
            "epoch": epoch,
            "model_state_dict": model.state_dict(),
            "optimizer_state_dict": optimizer.state_dict(),
            "train_loss": avg_train_loss,
            "val_loss": avg_val_loss,
        },
        save_path
    )

    elapsed = (time.time() - epoch_start) / 60

    # Clear memory
    gc.collect()
    torch.cuda.empty_cache()

    print("\n" + "=" * 60)
    print(f"✅ EPOCH {epoch}/20 COMPLETED")
    print("=" * 60)
    print(f"Train Loss : {avg_train_loss:.6f}")
    print(f"Val Loss   : {avg_val_loss:.6f}")
    print(f"Time       : {elapsed:.2f} minutes")
    print(f"Saved      : {save_path}")
    print("=" * 60)

print("\n" + "=" * 60)
print("🎉 SWINIR TRAINING COMPLETED")
print("=" * 60)
print("Final checkpoint:")
print("/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth")
print("=" * 60)

