# ============================================================
# SwinIR Dataset Diagnostic - SAFE READ-ONLY CHECK
# ============================================================

import os
import json
from pathlib import Path
from collections import Counter

# ------------------------------------------------------------
# 1. Paths
# ------------------------------------------------------------
PROJECT_DIR = Path("/content/drive/MyDrive/SwinIR_Project")
DATASET_DIR = Path("/content/drive/MyDrive/SwinIR_Data_Complete")
SPLIT_FILE = PROJECT_DIR / "train_val_split.json"

TRAIN_DIR = DATASET_DIR / "train"
VAL_DIR   = DATASET_DIR / "val"

print("=" * 70)
print("SWINIR DATASET DIAGNOSTIC")
print("=" * 70)

print("\nProject folder :", PROJECT_DIR)
print("Dataset folder :", DATASET_DIR)
print("Split file     :", SPLIT_FILE)

# ------------------------------------------------------------
# 2. Basic path checks
# ------------------------------------------------------------
print("\n" + "=" * 70)
print("PATH CHECK")
print("=" * 70)

for name, path in [
    ("Project folder", PROJECT_DIR),
    ("Dataset folder", DATASET_DIR),
    ("Split file", SPLIT_FILE),
    ("Train folder", TRAIN_DIR),
    ("Validation folder", VAL_DIR),
]:
    print(f"{name:20s}: {'EXISTS' if path.exists() else 'MISSING'}")
    print(f"  {path}")

# ------------------------------------------------------------
# 3. Load split JSON
# ------------------------------------------------------------
print("\n" + "=" * 70)
print("LOADING TRAIN/VALIDATION SPLIT")
print("=" * 70)

if not SPLIT_FILE.exists():
    print("ERROR: train_val_split.json does not exist.")
    print("STOPPING DIAGNOSTIC SAFELY.")
else:
    try:
        with open(SPLIT_FILE, "r") as f:
            split_data = json.load(f)

        print("Split JSON loaded successfully.")
        print("JSON type:", type(split_data).__name__)

        if isinstance(split_data, dict):
            print("Top-level keys:", list(split_data.keys()))

    except Exception as e:
        print("ERROR while reading split JSON:")
        print(type(e).__name__, e)
        split_data = None

# ------------------------------------------------------------
# 4. Helper functions
# ------------------------------------------------------------
def find_split_lists(data):
    """
    Try to locate train/validation lists regardless of
    whether the JSON uses train/val or train/validation.
    """
    if not isinstance(data, dict):
        return None, None

    train = None
    val = None

    for key in data.keys():
        key_lower = str(key).lower()

        if key_lower in ["train", "training", "train_list"]:
            train = data[key]

        if key_lower in ["val", "valid", "validation",
                         "validation_list", "val_list"]:
            val = data[key]

    return train, val


def extract_path_pairs(item):
    """
    Extract possible LQ/GT paths from one dataset entry.

    Supports several common JSON formats:
      {"lq": "...", "gt": "..."}
      {"LQ": "...", "GT": "..."}
      {"lq_path": "...", "gt_path": "..."}
      {"LQ_path": "...", "GT_path": "..."}
      {"input": "...", "target": "..."}
    """

    if isinstance(item, str):
        # If JSON contains only one filename/path, we cannot
        # determine its paired GT path from this entry alone.
        return item, None

    if not isinstance(item, dict):
        return None, None

    def get_value(possible_keys):
        for key in possible_keys:
            if key in item:
                return item[key]
        return None

    lq = get_value([
        "lq", "LQ",
        "lq_path", "LQ_path",
        "lq_file", "LQ_file",
        "input", "input_path",
        "noisy", "noisy_path",
        "noisy_lr", "NoisyLR",
        "filename_lq"
    ])

    gt = get_value([
        "gt", "GT",
        "gt_path", "GT_path",
        "gt_file", "GT_file",
        "target", "target_path",
        "clean", "clean_path",
        "hr", "HR",
        "filename_gt"
    ])

    return lq, gt


def make_absolute(path_value, base_dir):
    """
    Convert JSON path into an absolute path.

    Handles:
      - absolute paths
      - relative paths
      - filenames
    """
    if path_value is None:
        return None

    path_value = str(path_value)

    p = Path(path_value)

    if p.is_absolute():
        return p

    # Try relative to dataset directory
    return DATASET_DIR / p


# ------------------------------------------------------------
# 5. Inspect split structure
# ------------------------------------------------------------
if split_data is not None:

    train_list, val_list = find_split_lists(split_data)

    print("\n" + "=" * 70)
    print("SPLIT CONTENT")
    print("=" * 70)

    if train_list is not None:
        print("Training entries found:", len(train_list))
    else:
        print("Training list: NOT FOUND")

    if val_list is not None:
        print("Validation entries found:", len(val_list))
    else:
        print("Validation list: NOT FOUND")

    # --------------------------------------------------------
    # 6. Check every referenced file
    # --------------------------------------------------------
    missing_lq = []
    missing_gt = []
    valid_pairs = []
    invalid_pairs = []
    unresolved_entries = []

    all_entries = []

    if train_list is not None:
        for i, item in enumerate(train_list):
            all_entries.append(("TRAIN", i, item))

    if val_list is not None:
        for i, item in enumerate(val_list):
            all_entries.append(("VALIDATION", i, item))

    print("\nTotal split entries:", len(all_entries))

    for split_name, index, item in all_entries:

        lq_value, gt_value = extract_path_pairs(item)

        lq_path = make_absolute(lq_value, DATASET_DIR)
        gt_path = make_absolute(gt_value, DATASET_DIR)

        # If we could not understand the JSON structure
        if lq_path is None or gt_path is None:
            unresolved_entries.append({
                "split": split_name,
                "index": index,
                "entry": item
            })
            continue

        lq_exists = lq_path.exists()
        gt_exists = gt_path.exists()

        if not lq_exists:
            missing_lq.append({
                "split": split_name,
                "index": index,
                "path": str(lq_path),
                "gt_path": str(gt_path)
            })

        if not gt_exists:
            missing_gt.append({
                "split": split_name,
                "index": index,
                "path": str(gt_path),
                "lq_path": str(lq_path)
            })

        if lq_exists and gt_exists:
            valid_pairs.append({
                "split": split_name,
                "index": index,
                "lq": str(lq_path),
                "gt": str(gt_path)
            })
        else:
            invalid_pairs.append({
                "split": split_name,
                "index": index,
                "lq": str(lq_path),
                "gt": str(gt_path),
                "lq_exists": lq_exists,
                "gt_exists": gt_exists
            })

    # --------------------------------------------------------
    # 7. Summary
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("DATASET SUMMARY")
    print("=" * 70)

    print("Total split entries :", len(all_entries))
    print("Valid LQ-GT pairs   :", len(valid_pairs))
    print("Invalid pairs       :", len(invalid_pairs))
    print("Missing LQ files    :", len(missing_lq))
    print("Missing GT files    :", len(missing_gt))
    print("Unresolved entries  :", len(unresolved_entries))

    # --------------------------------------------------------
    # 8. Split-wise summary
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("TRAIN / VALIDATION SUMMARY")
    print("=" * 70)

    for split_name in ["TRAIN", "VALIDATION"]:

        total = sum(1 for x in all_entries if x[0] == split_name)

        valid = sum(
            1 for x in valid_pairs
            if x["split"] == split_name
        )

        invalid = sum(
            1 for x in invalid_pairs
            if x["split"] == split_name
        )

        mlq = sum(
            1 for x in missing_lq
            if x["split"] == split_name
        )

        mgt = sum(
            1 for x in missing_gt
            if x["split"] == split_name
        )

        print(f"\n{split_name}")
        print("  Total entries :", total)
        print("  Valid pairs   :", valid)
        print("  Invalid pairs :", invalid)
        print("  Missing LQ    :", mlq)
        print("  Missing GT    :", mgt)

    # --------------------------------------------------------
    # 9. Exact missing LQ files
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("EXACT MISSING LQ FILES")
    print("=" * 70)

    if len(missing_lq) == 0:
        print("NONE")
    else:
        for i, item in enumerate(missing_lq, 1):
            print(f"\n[{i}] Split : {item['split']}")
            print("    Index :", item["index"])
            print("    LQ    :", item["path"])
            print("    GT    :", item["gt_path"])

    # --------------------------------------------------------
    # 10. Exact missing GT files
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("EXACT MISSING GT FILES")
    print("=" * 70)

    if len(missing_gt) == 0:
        print("NONE")
    else:
        for i, item in enumerate(missing_gt, 1):
            print(f"\n[{i}] Split : {item['split']}")
            print("    Index :", item["index"])
            print("    GT    :", item["path"])
            print("    LQ    :", item["lq_path"])

    # --------------------------------------------------------
    # 11. Unresolved JSON entries
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("UNRESOLVED JSON ENTRIES")
    print("=" * 70)

    if len(unresolved_entries) == 0:
        print("NONE")
    else:
        print("These entries use a JSON format that this diagnostic")
        print("could not automatically interpret.")

        for item in unresolved_entries[:20]:
            print("\nSplit :", item["split"])
            print("Index :", item["index"])
            print("Entry :", item["entry"])

        if len(unresolved_entries) > 20:
            print(
                f"\n...and {len(unresolved_entries)-20} more unresolved entries."
            )

    # --------------------------------------------------------
    # 12. Actual files physically present in dataset folders
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("PHYSICAL DATASET FILE COUNTS")
    print("=" * 70)

    for folder in [
        DATASET_DIR / "train" / "NoisyLR",
        DATASET_DIR / "train" / "GT",
        DATASET_DIR / "val" / "NoisyLR",
        DATASET_DIR / "val" / "GT",
    ]:

        if folder.exists():
            files = [
                p for p in folder.rglob("*")
                if p.is_file()
            ]

            print(f"{folder}")
            print(f"  Files found: {len(files)}")
        else:
            print(f"{folder}")
            print("  FOLDER MISSING")

    # --------------------------------------------------------
    # 13. Final decision
    # --------------------------------------------------------
    print("\n" + "=" * 70)
    print("FINAL DIAGNOSTIC RESULT")
    print("=" * 70)

    if len(unresolved_entries) > 0:
        print("⚠️ The split JSON structure needs to be inspected.")
        print("DO NOT modify the dataset yet.")

    elif len(invalid_pairs) == 0:
        print("✅ ALL DATASET PAIRS ARE VALID.")
        print("No missing LQ/GT files were found in the split.")

    else:
        print("⚠️ MISSING DATASET FILES WERE FOUND.")
        print("The Epoch-14 checkpoint is NOT affected.")
        print("DO NOT delete or modify the checkpoint.")
        print("We will repair the dataset index safely after reviewing")
        print("this output.")

print("\n" + "=" * 70)
print("DIAGNOSTIC COMPLETE — NOTHING WAS DELETED OR MODIFIED")
print("=" * 70)

