# ============================================================
# SWINIR - VERIFY ACTUAL DATASET + JSON SAMPLE MATCHING
# ============================================================

import os
import json
import numpy as np

DATASET_ROOT = "/content/train_data"
SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

TRAIN_LQ = os.path.join(DATASET_ROOT, "train", "NoisyLR")
TRAIN_GT = os.path.join(DATASET_ROOT, "train", "GT")

print("=" * 70)
print("SWINIR DATASET + SPLIT VERIFICATION")
print("=" * 70)

# ------------------------------------------------------------
# 1. Check folders
# ------------------------------------------------------------

print("\nPATH CHECK")
print("-" * 70)

for name, path in [
    ("Dataset root", DATASET_ROOT),
    ("NoisyLR", TRAIN_LQ),
    ("GT", TRAIN_GT),
    ("Split JSON", SPLIT_FILE)
]:
    print(f"{name:15s} : {'EXISTS' if os.path.exists(path) else 'MISSING'}")
    print(f"                 {path}")

# ------------------------------------------------------------
# 2. Count files
# ------------------------------------------------------------

lq_files = {
    os.path.splitext(f)[0]
    for f in os.listdir(TRAIN_LQ)
    if f.endswith(".npy")
}

gt_files = {
    os.path.splitext(f)[0]
    for f in os.listdir(TRAIN_GT)
    if f.endswith(".npy")
}

print("\n" + "=" * 70)
print("PHYSICAL DATASET")
print("=" * 70)

print("NoisyLR files:", len(lq_files))
print("GT files     :", len(gt_files))

print("LQ == GT sets:", lq_files == gt_files)

if lq_files != gt_files:
    print("⚠️ LQ-only files:", sorted(lq_files - gt_files)[:20])
    print("⚠️ GT-only files:", sorted(gt_files - lq_files)[:20])

# ------------------------------------------------------------
# 3. Load JSON
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("LOADING SPLIT JSON")
print("=" * 70)

with open(SPLIT_FILE, "r") as f:
    split_data = json.load(f)

train_entries = split_data["train"]
val_entries = split_data["val"]

print("Train entries:", len(train_entries))
print("Val entries  :", len(val_entries))

# ------------------------------------------------------------
# 4. Extract IDs
# ------------------------------------------------------------

def extract_id(x):

    if isinstance(x, str):
        return os.path.splitext(os.path.basename(x))[0]

    if isinstance(x, dict):

        possible_keys = [
            "id",
            "name",
            "filename",
            "file",
            "path",
            "image",
            "index"
        ]

        for key in possible_keys:
            if key in x:
                value = x[key]

                if isinstance(value, str):
                    return os.path.splitext(
                        os.path.basename(value)
                    )[0]

                return str(value)

    if isinstance(x, (int, float)):
        return str(int(x)).zfill(6)

    return None


train_ids = [extract_id(x) for x in train_entries]
val_ids = [extract_id(x) for x in val_entries]

print("\n" + "=" * 70)
print("JSON ID CHECK")
print("=" * 70)

print("First 10 train IDs:")
print(train_ids[:10])

print("\nFirst 10 validation IDs:")
print(val_ids[:10])

print("\nUnresolved train IDs:",
      sum(x is None for x in train_ids))

print("Unresolved val IDs:",
      sum(x is None for x in val_ids))

# ------------------------------------------------------------
# 5. Compare JSON IDs with physical files
# ------------------------------------------------------------

train_set = {x for x in train_ids if x is not None}
val_set = {x for x in val_ids if x is not None}

physical_set = lq_files & gt_files

train_valid = train_set & physical_set
val_valid = val_set & physical_set

print("\n" + "=" * 70)
print("MATCHING RESULTS")
print("=" * 70)

print("Physical paired samples :", len(physical_set))
print("Train JSON IDs          :", len(train_set))
print("Validation JSON IDs     :", len(val_set))

print("Valid train IDs         :", len(train_valid))
print("Valid validation IDs    :", len(val_valid))

print("Missing train IDs       :", len(train_set - physical_set))
print("Missing validation IDs  :", len(val_set - physical_set))

# ------------------------------------------------------------
# 6. Check overlap
# ------------------------------------------------------------

overlap = train_set & val_set

print("\n" + "=" * 70)
print("TRAIN / VALIDATION OVERLAP")
print("=" * 70)

print("Overlapping IDs:", len(overlap))

if overlap:
    print("⚠️ First overlapping IDs:")
    print(sorted(overlap)[:20])
else:
    print("✅ No train/validation overlap")

# ------------------------------------------------------------
# 7. Check total coverage
# ------------------------------------------------------------

json_all = train_set | val_set

print("\n" + "=" * 70)
print("TOTAL COVERAGE")
print("=" * 70)

print("JSON unique IDs       :", len(json_all))
print("Physical paired IDs   :", len(physical_set))
print("JSON IDs not physical :", len(json_all - physical_set))
print("Physical IDs not JSON :", len(physical_set - json_all))

if json_all == physical_set:
    print("\n✅ PERFECT MATCH!")
    print("The JSON split covers exactly the physical dataset.")
else:
    print("\n⚠️ JSON and physical dataset do not perfectly match.")

print("\n" + "=" * 70)
print("VERIFICATION COMPLETE")
print("=" * 70)

print("""
NOTHING WAS MODIFIED.
NO FILES WERE DELETED.
CHECKPOINT WAS NOT TOUCHED.
""")

# ============================================================
# SWINIR - CREATE & VERIFY CORRECT DATALOADERS
# ============================================================

import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

DATASET_ROOT = "/content/train_data"
SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

TRAIN_LQ = os.path.join(DATASET_ROOT, "train", "NoisyLR")
TRAIN_GT = os.path.join(DATASET_ROOT, "train", "GT")

BATCH_SIZE = 4

# ------------------------------------------------------------
# LOAD SPLIT
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split_data = json.load(f)

train_ids = split_data["train"]
val_ids = split_data["val"]

# Convert IDs to strings
train_ids = [
    os.path.splitext(os.path.basename(str(x)))[0]
    for x in train_ids
]

val_ids = [
    os.path.splitext(os.path.basename(str(x)))[0]
    for x in val_ids
]

# ------------------------------------------------------------
# DATASET CLASS
# ------------------------------------------------------------

class SwinIRDataset(Dataset):

    def __init__(self, ids, lq_dir, gt_dir):

        self.ids = ids
        self.lq_dir = lq_dir
        self.gt_dir = gt_dir

    def __len__(self):
        return len(self.ids)

    def __getitem__(self, idx):

        sample_id = self.ids[idx]

        lq_path = os.path.join(
            self.lq_dir,
            sample_id + ".npy"
        )

        gt_path = os.path.join(
            self.gt_dir,
            sample_id + ".npy"
        )

        lq = np.load(lq_path)
        gt = np.load(gt_path)

        # Convert numpy -> torch
        lq = torch.from_numpy(lq).float()
        gt = torch.from_numpy(gt).float()

        # Handle HWC -> CHW if required
        if lq.ndim == 3 and lq.shape[-1] in [1, 3]:
            lq = lq.permute(2, 0, 1)

        if gt.ndim == 3 and gt.shape[-1] in [1, 3]:
            gt = gt.permute(2, 0, 1)

        return lq, gt

# ------------------------------------------------------------
# CREATE DATASETS
# ------------------------------------------------------------

train_dataset = SwinIRDataset(
    train_ids,
    TRAIN_LQ,
    TRAIN_GT
)

val_dataset = SwinIRDataset(
    val_ids,
    TRAIN_LQ,
    TRAIN_GT
)

# ------------------------------------------------------------
# CREATE DATALOADERS
# ------------------------------------------------------------

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=0,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=0,
    pin_memory=True
)

# ------------------------------------------------------------
# BASIC CHECK
# ------------------------------------------------------------

print("=" * 70)
print("SWINIR DATALOADER VERIFICATION")
print("=" * 70)

print("Dataset root :", DATASET_ROOT)

print("Train samples:", len(train_dataset))
print("Val samples  :", len(val_dataset))

print("Train batches:", len(train_loader))
print("Val batches  :", len(val_loader))

# ------------------------------------------------------------
# LOAD ONE TRAIN SAMPLE
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("CHECKING FIRST TRAIN SAMPLE")
print("=" * 70)

lq_sample, gt_sample = train_dataset[0]

print("Sample ID    :", train_ids[0])
print("LQ shape     :", lq_sample.shape)
print("GT shape     :", gt_sample.shape)
print("LQ dtype     :", lq_sample.dtype)
print("GT dtype     :", gt_sample.dtype)

# ------------------------------------------------------------
# LOAD ONE BATCH
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("CHECKING ONE COMPLETE BATCH")
print("=" * 70)

lq_batch, gt_batch = next(iter(train_loader))

print("LQ batch shape:", lq_batch.shape)
print("GT batch shape:", gt_batch.shape)

print("LQ min:", lq_batch.min().item())
print("LQ max:", lq_batch.max().item())

print("GT min:", gt_batch.min().item())
print("GT max:", gt_batch.max().item())

# ------------------------------------------------------------
# VALIDATION BATCH
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("CHECKING VALIDATION BATCH")
print("=" * 70)

val_lq_batch, val_gt_batch = next(iter(val_loader))

print("Val LQ batch shape:", val_lq_batch.shape)
print("Val GT batch shape:", val_gt_batch.shape)

print("\n" + "=" * 70)
print("✅ DATALOADER VERIFICATION COMPLETE")
print("=" * 70)

print("""
Dataset is being read from the correct Colab location.

NOTHING WAS DELETED.
train_val_split.json was NOT modified.
Epoch-14 checkpoint was NOT modified.

DO NOT START TRAINING YET.
Send me this complete output.
""")

