# SWINIR - EPOCH 14 CHECKPOINT + MODEL COMPATIBILITY
# ============================================================

import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

from network_swinir import SwinIR

# ------------------------------------------------------------
# DEVICE
# ------------------------------------------------------------

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("=" * 70)
print("SWINIR EPOCH-14 RESUME PREPARATION")
print("=" * 70)

print("Device:", device)

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

DATASET_ROOT = "/content/train_data"
SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"
CHECKPOINT = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_14.pth"

TRAIN_LQ = os.path.join(
    DATASET_ROOT, "train", "NoisyLR"
)

TRAIN_GT = os.path.join(
    DATASET_ROOT, "train", "GT"
)

# ------------------------------------------------------------
# LOAD SPLIT
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split_data = json.load(f)

train_ids = [
    os.path.splitext(os.path.basename(str(x)))[0]
    for x in split_data["train"]
]

val_ids = [
    os.path.splitext(os.path.basename(str(x)))[0]
    for x in split_data["val"]
]

print("\nTrain samples:", len(train_ids))
print("Val samples  :", len(val_ids))

# ------------------------------------------------------------
# DATASET
# ------------------------------------------------------------

class SwinIRDataset(Dataset):

    def __init__(self, ids, lq_dir, gt_dir):
        self.ids = ids
        self.lq_dir = lq_dir
        self.gt_dir = gt_dir

    def __len__(self):
        return len(self.ids)

    def __getitem__(self, idx):

        sample_id = self.ids[idx]

        lq_path = os.path.join(
            self.lq_dir,
            sample_id + ".npy"
        )

        gt_path = os.path.join(
            self.gt_dir,
            sample_id + ".npy"
        )

        lq = np.load(lq_path)
        gt = np.load(gt_path)

        lq = torch.from_numpy(lq).float()
        gt = torch.from_numpy(gt).float()

        # Grayscale: H,W -> 1,H,W
        if lq.ndim == 2:
            lq = lq.unsqueeze(0)

        if gt.ndim == 2:
            gt = gt.unsqueeze(0)

        return lq, gt


train_dataset = SwinIRDataset(
    train_ids,
    TRAIN_LQ,
    TRAIN_GT
)

val_dataset = SwinIRDataset(
    val_ids,
    TRAIN_LQ,
    TRAIN_GT
)

# ------------------------------------------------------------
# DATALOADERS
# ------------------------------------------------------------

BATCH_SIZE = 4

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=0,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=0,
    pin_memory=True
)

print("\nTrain batches:", len(train_loader))
print("Val batches  :", len(val_loader))

# ------------------------------------------------------------
# CREATE EXACT SWINIR ARCHITECTURE
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("CREATING SWINIR MODEL")
print("=" * 70)

model = SwinIR(
    img_size=64,
    patch_size=1,
    in_chans=1,
    embed_dim=96,
    depths=[6, 6, 6, 6],
    num_heads=[6, 6, 6, 6],
    window_size=7,
    mlp_ratio=4.0,
    qkv_bias=True,
    qk_scale=None,
    drop_rate=0.0,
    attn_drop_rate=0.0,
    drop_path_rate=0.1,
    norm_layer=torch.nn.LayerNorm,
    ape=False,
    patch_norm=True,
    use_checkpoint=False,
    upscale=2,
    img_range=1.0,
    upsampler="",
    resi_connection="1conv"
)

model = model.to(device)

print("Model created.")
print("Input channels : 1")
print("Upscale        : 2")
print("Device         :", device)

# ------------------------------------------------------------
# OPTIMIZER
# ------------------------------------------------------------

optimizer = torch.optim.Adam(
    model.parameters(),
    lr=1e-4
)

# ------------------------------------------------------------
# LOAD EPOCH-14 CHECKPOINT
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("LOADING EPOCH-14 CHECKPOINT")
print("=" * 70)

checkpoint = torch.load(
    CHECKPOINT,
    map_location=device
)

model.load_state_dict(
    checkpoint["model_state_dict"]
)

optimizer.load_state_dict(
    checkpoint["optimizer_state_dict"]
)

completed_epoch = checkpoint["epoch"]

print("Checkpoint loaded successfully.")
print("Completed epoch :", completed_epoch)
print("Starting epoch  :", completed_epoch + 1)
print("Train loss      :", checkpoint["train_loss"])
print("Val loss        :", checkpoint["val_loss"])

# ------------------------------------------------------------
# FORWARD PASS TEST
# ------------------------------------------------------------

print("\n" + "=" * 70)
print("TESTING MODEL FORWARD PASS")
print("=" * 70)

model.eval()

with torch.no_grad():

    lq_batch, gt_batch = next(iter(train_loader))

    lq_batch = lq_batch.to(device)
    gt_batch = gt_batch.to(device)

    print("Input shape :", lq_batch.shape)
    print("GT shape    :", gt_batch.shape)

    output = model(lq_batch)

    print("Output shape:", output.shape)

# ------------------------------------------------------------
# VERIFY EXPECTED SHAPES
# ------------------------------------------------------------

expected_input = (BATCH_SIZE, 1, 128, 128)
expected_output = (BATCH_SIZE, 1, 256, 256)

print("\n" + "=" * 70)
print("SHAPE VERIFICATION")
