print("Actual input   :", tuple(lq_batch.shape))

print("Expected output:", expected_output)
print("Actual output  :", tuple(output.shape))

if tuple(lq_batch.shape) == expected_input:
    print("✅ INPUT SHAPE CORRECT")
else:
    print("❌ INPUT SHAPE PROBLEM")

if tuple(output.shape) == expected_output:
    print("✅ OUTPUT SHAPE CORRECT")
else:
    print("❌ OUTPUT SHAPE PROBLEM")

print("\n" + "=" * 70)
print("EPOCH-14 RESUME PREPARATION COMPLETE")
