import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

DATA_ROOT = "/content/train_data/train"
SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

print("=" * 60)
print("CREATING CORRECT SWINIR DATALOADERS")
print("=" * 60)

# Load saved split
with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

print("Train entries :", len(split["train"]))
print("Val entries   :", len(split["val"]))


class SwinIRDataset(Dataset):

    def __init__(self, entries):
        self.entries = entries

    def __len__(self):
        return len(self.entries)

    def __getitem__(self, idx):

        item = self.entries[idx]

        # Saved split contains the paired file information
        if isinstance(item, dict):
            noisy_file = (
                item.get("noisy")
                or item.get("NoisyLR")
                or item.get("lq")
            )

            gt_file = (
                item.get("gt")
                or item.get("GT")
                or item.get("hq")
            )
        else:
            raise ValueError(
                f"Unexpected split format at index {idx}: {item}"
            )

        # If paths are relative, resolve them against DATA_ROOT
        if not os.path.isabs(noisy_file):
            noisy_file = os.path.join(DATA_ROOT, noisy_file)

        if not os.path.isabs(gt_file):
            gt_file = os.path.join(DATA_ROOT, gt_file)

        if not os.path.exists(noisy_file):
            raise FileNotFoundError(
                f"NoisyLR file not found: {noisy_file}"
            )

        if not os.path.exists(gt_file):
            raise FileNotFoundError(
                f"GT file not found: {gt_file}"
            )

        noisy = np.load(noisy_file).astype(np.float32)
        gt = np.load(gt_file).astype(np.float32)

        noisy = torch.from_numpy(noisy).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return noisy, gt


# Create datasets
train_dataset = SwinIRDataset(split["train"])
val_dataset = SwinIRDataset(split["val"])

# Create loaders
train_loader = DataLoader(
    train_dataset,
    batch_size=4,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=4,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("\n" + "=" * 60)
print("✅ DATALOADERS CREATED")
print("=" * 60)

print("Train samples :", len(train_dataset))
print("Val samples   :", len(val_dataset))
print("Train batches :", len(train_loader))
print("Val batches   :", len(val_loader))

