import os
import numpy as np
import torch
import time

test_dir = "/content/SwinIR_Final_Test/NoisyLR"
restored_dir = "/content/SwinIR_Final_Test/Restored_All"

os.makedirs(restored_dir, exist_ok=True)

test_files = sorted([
    f for f in os.listdir(test_dir)
    if f.endswith(".npy")
])

print("=" * 70)
print("SWINIR FINAL TESTING — 400 IMAGES")
print("=" * 70)
print("Test images :", len(test_files))
print("Output dir  :", restored_dir)
print("Device      :", device)
print("=" * 70)

test_model.eval()

start_time = time.time()

with torch.no_grad():

    for i, filename in enumerate(test_files, 1):

        input_path = os.path.join(test_dir, filename)

        # Load input
        img = np.load(input_path).astype(np.float32)

        # Convert to [1, 1, H, W]
        if img.ndim == 2:
            tensor = torch.from_numpy(img).unsqueeze(0).unsqueeze(0)
        elif img.ndim == 3:
            tensor = torch.from_numpy(img).unsqueeze(0)
        else:
            raise ValueError(
                f"Unexpected shape {img.shape} for {filename}"
            )

        tensor = tensor.to(device)

        # Inference
        output = test_model(tensor)

        # Convert back to NumPy
        restored = output.squeeze().cpu().numpy().astype(np.float32)

        # Save
        output_name = filename.replace(
            ".npy",
            "_restored.npy"
        )

        output_path = os.path.join(
            restored_dir,
            output_name
        )

        np.save(output_path, restored)

        # Progress
        if i == 1 or i % 25 == 0 or i == len(test_files):

            elapsed = time.time() - start_time
            avg_time = elapsed / i
            remaining = avg_time * (len(test_files) - i)

            print(
                f"[{i:03d}/{len(test_files)}] "
                f"{filename} → "
                f"{restored.shape} | "
                f"Elapsed: {elapsed/60:.2f} min | "
                f"ETA: {remaining/60:.2f} min"
            )

elapsed_total = time.time() - start_time

# Count outputs
output_files = sorted([
    f for f in os.listdir(restored_dir)
    if f.endswith("_restored.npy")
])

print("\n" + "=" * 70)
print("🎉 FINAL TESTING COMPLETED")
print("=" * 70)
print("Input images  :", len(test_files))
print("Output images :", len(output_files))
print("Total time    :", round(elapsed_total / 60, 2), "minutes")
print("Output folder :", restored_dir)
print("=" * 70)

import os
import numpy as np

output_dir = "/content/SwinIR_Final_Test/Restored_All"

files = sorted([
    f for f in os.listdir(output_dir)
    if f.endswith("_restored.npy")
])

print("=" * 70)
print("VERIFYING ALL 400 SWINIR OUTPUTS")
print("=" * 70)

valid_count = 0
invalid_count = 0
wrong_shape = []
nan_files = []
inf_files = []

for filename in files:

    path = os.path.join(output_dir, filename)
    img = np.load(path)

    valid = True

    if img.shape != (256, 256):
        wrong_shape.append((filename, img.shape))
        valid = False

    if np.isnan(img).any():
        nan_files.append(filename)
        valid = False

    if np.isinf(img).any():
        inf_files.append(filename)
        valid = False

    if valid:
        valid_count += 1
    else:
        invalid_count += 1

print("\nTotal output files :", len(files))
print("Valid outputs      :", valid_count)
print("Invalid outputs    :", invalid_count)

print("\nWrong shapes :", len(wrong_shape))
print("NaN files    :", len(nan_files))
print("Inf files    :", len(inf_files))

if invalid_count == 0:
    print("\n" + "=" * 70)
    print("🎉 ALL 400 OUTPUTS ARE VALID")
    print("=" * 70)
else:
    print("\n⚠️ Some outputs need inspection.")

print("\nSample output statistics:")

for filename in files[:5]:

    img = np.load(
        os.path.join(output_dir, filename)
    )

    print(
        filename,
        "| Shape:", img.shape,
        "| Min:", float(img.min()),
        "| Max:", float(img.max())
    )

