# Reuse already loaded test_model if available.
# Otherwise create and load it.
if "test_model" not in globals():

    from network_swinir import SwinIR

    test_model = SwinIR(
        img_size=128,
        patch_size=1,
        in_chans=1,
        embed_dim=96,
        depths=[6, 6, 6, 6],
        num_heads=[6, 6, 6, 6],
        window_size=8,
        mlp_ratio=4,
        upscale=2,
        img_range=1.0,
        upsampler="pixelshuffle",
        resi_connection="1conv"
    ).to(device)

    checkpoint = torch.load(
        CHECKPOINT_PATH,
        map_location="cpu"
    )

    test_model.load_state_dict(
        checkpoint["model_state_dict"],
        strict=True
    )

test_model.eval()

print("Model loaded successfully")
print("Device :", device)

# ============================================================
# TEST IMAGE LIST
# ============================================================

test_files = sorted([
    f for f in os.listdir(TEST_DIR)
    if f.endswith(".npy")
])

print("Test images available :", len(test_files))

# ============================================================
# RESTORATION FUNCTION
# ============================================================

def restore_image(filename):

    if not filename:
        return None, None, "Please select a test image."

    input_path = os.path.join(TEST_DIR, filename)

    # Load input
    input_img = np.load(input_path).astype(np.float32)

    # Prepare tensor
    if input_img.ndim == 2:
        tensor = torch.from_numpy(input_img).unsqueeze(0).unsqueeze(0)
    else:
        tensor = torch.from_numpy(input_img).unsqueeze(0)

    tensor = tensor.to(device)

    # Inference
    with torch.no_grad():
        output = test_model(tensor)

    restored = output.squeeze().cpu().numpy()

    # Clip only for display
    input_display = np.clip(input_img, 0, 1)
    restored_display = np.clip(restored, 0, 1)

    # Save restored output
    output_filename = filename.replace(
        ".npy",
        "_demo_restored.npy"
    )

    output_path = os.path.join(
        DEMO_OUTPUT_DIR,
        output_filename
    )

    np.save(output_path, restored)

    # Return images + information
    info = (
        f"Input: {input_img.shape[0]} × {input_img.shape[1]}\n"
        f"Output: {restored.shape[0]} × {restored.shape[1]}\n"
        f"Model: SwinIR Epoch-20\n"
        f"Scale: 2×\n"
        f"Device: {device}\n"
        f"Saved: {output_filename}"
    )

    return input_display, restored_display, info


# ============================================================
# GRADIO INTERFACE
# ============================================================

demo = gr.Interface(
    fn=restore_image,

    inputs=gr.Dropdown(
        choices=test_files,
        label="Select Test Image",
        value=test_files[0] if test_files else None
    ),

    outputs=[
        gr.Image(
            type="numpy",
            label="Input — Noisy / Low Resolution"
        ),

        gr.Image(
            type="numpy",
            label="SwinIR Restored — 2× Resolution"
        ),

        gr.Textbox(
            label="Restoration Information"
        )
    ],

    title="🔬 Semiconductor Image Restoration using SwinIR",

    description=(
        "Select a degraded semiconductor image and restore it "
        "using the trained SwinIR Epoch-20 model. "
        "Input: 128×128 → Output: 256×256."
    ),

    submit_btn="🚀 Restore Image",
    clear_btn="Clear"
)

print("=" * 70)
print("✅ SWINIR DEMO CREATED")
print("=" * 70)

print("=" * 70)
print("🚀 LAUNCHING SWINIR DEMO")
print("=" * 70)

demo.launch(
    share=True,
    debug=True
)

