import os
import json
import numpy as np
import torch
from skimage.metrics import peak_signal_noise_ratio
from skimage.metrics import structural_similarity

# Paths
gt_dir = "/content/train_data/train/GT"
noisy_dir = "/content/train_data/train/NoisyLR"
split_path = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

# Load validation IDs
with open(split_path, "r") as f:
    split = json.load(f)

val_ids = split["val"]

print("Validation images:", len(val_ids))

# Make sure model is ready
model = model.to(device)
model.eval()

psnr_values = []
ssim_values = []

results = []

with torch.no_grad():

    for i, image_id in enumerate(val_ids):

        noisy_path = os.path.join(noisy_dir, image_id + ".npy")
        gt_path = os.path.join(gt_dir, image_id + ".npy")

        noisy = np.load(noisy_path).astype(np.float32)
        gt = np.load(gt_path).astype(np.float32)

        # Normalize
        if noisy.max() > 1:
            noisy = noisy / 255.0

        if gt.max() > 1:
            gt = gt / 255.0

        noisy = np.clip(noisy, 0, 1)
        gt = np.clip(gt, 0, 1)

        # Convert to tensor
        input_tensor = torch.from_numpy(noisy)

        # [H,W] -> [1,1,H,W]
        input_tensor = input_tensor.unsqueeze(0).unsqueeze(0)
        input_tensor = input_tensor.to(device)

        # Model inference
        output = model(input_tensor)

        output = output.squeeze().detach().cpu().numpy()
        output = np.clip(output, 0, 1)

        # If output shape differs, resize to GT
        if output.shape != gt.shape:
            from skimage.transform import resize

            output = resize(
                output,
                gt.shape,
                preserve_range=True,
                anti_aliasing=True
            )

        # PSNR
        psnr = peak_signal_noise_ratio(
            gt,
            output,
            data_range=1.0
        )

        # SSIM
        ssim = structural_similarity(
            gt,
            output,
            data_range=1.0
        )

        psnr_values.append(psnr)
        ssim_values.append(ssim)

        results.append({
            "id": image_id,
            "PSNR": psnr,
            "SSIM": ssim
        })

        if (i + 1) % 20 == 0:
            print(
                f"{i+1}/320 | "
                f"Average PSNR: {np.mean(psnr_values):.4f} | "
                f"Average SSIM: {np.mean(ssim_values):.4f}"
            )

print("\n" + "="*50)
print("FINAL EPOCH-20 VALIDATION RESULTS")
print("="*50)

print("Images evaluated :", len(results))
print("Average PSNR     :", np.mean(psnr_values))
print("Average SSIM     :", np.mean(ssim_values))
print("Minimum PSNR     :", np.min(psnr_values))
print("Maximum PSNR     :", np.max(psnr_values))
print("Minimum SSIM     :", np.min(ssim_values))
print("Maximum SSIM     :", np.max(ssim_values))

