import os
import json
import numpy as np
import torch
from skimage.metrics import peak_signal_noise_ratio
from skimage.metrics import structural_similarity

gt_dir = "/content/train_data/train/GT"
noisy_dir = "/content/train_data/train/NoisyLR"

with open(
    "/content/drive/MyDrive/SwinIR_Project/train_val_split.json",
    "r"
) as f:
    split = json.load(f)

val_ids = split["val"]

model = model.to(device)
model.eval()

psnr_values = []
ssim_values = []
results = []

print("Starting CORRECTED evaluation...")
print("Validation images:", len(val_ids))

with torch.no_grad():

    for i, image_id in enumerate(val_ids):

        noisy_path = os.path.join(
            noisy_dir,
            image_id + ".npy"
        )

        gt_path = os.path.join(
            gt_dir,
            image_id + ".npy"
        )

        noisy = np.load(noisy_path).astype(np.float32)
        gt = np.load(gt_path).astype(np.float32)

        # IMPORTANT:
        # Do NOT divide NoisyLR by 255.
        # Dataset is already approximately 0-1 scale.

        noisy_input = noisy
        gt_eval = gt

        # Clip only the noisy input to valid image range
        noisy_input = np.clip(noisy_input, 0.0, 1.0)

        # GT is already 0-1
        gt_eval = np.clip(gt_eval, 0.0, 1.0)

        # Convert input to tensor
        input_tensor = torch.from_numpy(
            noisy_input
        ).unsqueeze(0).unsqueeze(0).to(device)

        # SwinIR inference
        output = model(input_tensor)

        output = output.squeeze().detach().cpu().numpy()

        # Output should be 256x256
        if output.shape != gt_eval.shape:

            from skimage.transform import resize

            output = resize(
                output,
                gt_eval.shape,
                preserve_range=True,
                anti_aliasing=True
            )

        output = np.clip(output, 0.0, 1.0)

        # PSNR
        psnr = peak_signal_noise_ratio(
            gt_eval,
            output,
            data_range=1.0
        )

        # SSIM
        ssim = structural_similarity(
            gt_eval,
            output,
            data_range=1.0
        )

        psnr_values.append(psnr)
        ssim_values.append(ssim)

        results.append({
            "id": image_id,
            "PSNR": psnr,
            "SSIM": ssim
        })

        if (i + 1) % 20 == 0:

            print(
                f"{i+1}/320 | "
                f"PSNR: {np.mean(psnr_values):.4f} | "
                f"SSIM: {np.mean(ssim_values):.4f}"
            )


print("\n")
print("=" * 60)
print("CORRECTED EPOCH-20 VALIDATION RESULTS")
print("=" * 60)

print("Images evaluated :", len(results))
print("Average PSNR     :", np.mean(psnr_values))
print("Average SSIM     :", np.mean(ssim_values))
print("Minimum PSNR     :", np.min(psnr_values))
print("Maximum PSNR     :", np.max(psnr_values))
print("Minimum SSIM     :", np.min(ssim_values))
print("Maximum SSIM     :", np.max(ssim_values))

import lpips
import torch
import numpy as np
import os
import json

# LPIPS model
lpips_model = lpips.LPIPS(net='alex').to(device)
lpips_model.eval()

lpips_values = []

print("Starting LPIPS evaluation...")
print("Validation images:", len(val_ids))

with torch.no_grad():

    for i, image_id in enumerate(val_ids):

        noisy_path = os.path.join(
            noisy_dir,
            image_id + ".npy"
        )

        gt_path = os.path.join(
            gt_dir,
            image_id + ".npy"
        )

        noisy = np.load(noisy_path).astype(np.float32)
        gt = np.load(gt_path).astype(np.float32)

        # Keep dataset scale
        noisy = np.clip(noisy, 0.0, 1.0)
        gt = np.clip(gt, 0.0, 1.0)

        # Input
        input_tensor = (
            torch.from_numpy(noisy)
            .unsqueeze(0)
            .unsqueeze(0)
            .to(device)
        )

        # SwinIR
        restored = model(input_tensor)

        restored = restored.squeeze().cpu().numpy()
        restored = np.clip(restored, 0.0, 1.0)

        # Convert GT/restored to 256x256 if necessary
        if restored.shape != gt.shape:

            from skimage.transform import resize

            restored = resize(
                restored,
                gt.shape,
                preserve_range=True,
                anti_aliasing=True
            )

        # LPIPS expects 3-channel RGB in [-1,1]
        restored_tensor = torch.from_numpy(
            restored
        ).float().unsqueeze(0).unsqueeze(0)

        gt_tensor = torch.from_numpy(
            gt
        ).float().unsqueeze(0).unsqueeze(0)

        # Convert grayscale → 3 channels
        restored_tensor = restored_tensor.repeat(1, 3, 1, 1)
        gt_tensor = gt_tensor.repeat(1, 3, 1, 1)

        # [0,1] → [-1,1]
        restored_tensor = restored_tensor * 2 - 1
        gt_tensor = gt_tensor * 2 - 1

        restored_tensor = restored_tensor.to(device)
        gt_tensor = gt_tensor.to(device)

        # LPIPS
        score = lpips_model(
            restored_tensor,
            gt_tensor
        ).item()

        lpips_values.append(score)

        if (i + 1) % 20 == 0:
            print(
                f"{i+1}/320 | "
                f"Average LPIPS: {np.mean(lpips_values):.6f}"
            )

print("\n" + "="*60)
print("FINAL LPIPS RESULT")
print("="*60)

print("Images evaluated :", len(lpips_values))
print("Average LPIPS    :", np.mean(lpips_values))
print("Minimum LPIPS    :", np.min(lpips_values))
print("Maximum LPIPS    :", np.max(lpips_values))

