    gt = np.clip(gt, 0.0, 1.0)

    # Model input
    input_tensor = (
        torch.from_numpy(noisy)
        .unsqueeze(0)
        .unsqueeze(0)
        .to(device)
    )

    model.eval()

    with torch.no_grad():
        restored = model(input_tensor)

    restored = restored.squeeze().cpu().numpy()
    restored = np.clip(restored, 0.0, 1.0)

    # Display
    plt.figure(figsize=(15, 5))

    plt.subplot(1, 3, 1)
    plt.imshow(noisy, cmap="gray", vmin=0, vmax=1)
    plt.title("Noisy Input")
    plt.axis("off")

    plt.subplot(1, 3, 2)
    plt.imshow(restored, cmap="gray", vmin=0, vmax=1)
    plt.title("SwinIR Restored")
    plt.axis("off")

    plt.subplot(1, 3, 3)
    plt.imshow(gt, cmap="gray", vmin=0, vmax=1)
    plt.title("Ground Truth")
    plt.axis("off")

    plt.suptitle(
        f"Semiconductor Image Restoration — ID {image_id}"
    )

    plt.tight_layout()

    save_path = os.path.join(
        demo_dir,
        f"{image_id}_before_after.png"
    )

    plt.savefig(
        save_path,
        dpi=200,
        bbox_inches="tight"
    )

    plt.show()
    plt.close()

