import os
import numpy as np
import torch
from skimage.transform import resize

# --------------------------------------------------
# PATHS
# --------------------------------------------------

test_dir = "/content/Test_NoisyLR/NoisyLR"

output_dir = "/content/drive/MyDrive/SwinIR_Project/test_results"
os.makedirs(output_dir, exist_ok=True)

# --------------------------------------------------
# FIND REAL .NPY FILES
# --------------------------------------------------

test_files = sorted([
    f for f in os.listdir(test_dir)
    if f.endswith(".npy") and not f.startswith("._")
])

print("=" * 60)
print("FINAL TEST INFERENCE")
print("=" * 60)

print("Test images found:", len(test_files))
print("Output directory:", output_dir)

# --------------------------------------------------
# LOAD FINAL MODEL
# --------------------------------------------------

model = model.to(device)
model.eval()

print("\nModel:", type(model))
print("Device:", device)

# --------------------------------------------------
# PROCESS TEST IMAGES
# --------------------------------------------------

successful = 0
failed = 0

with torch.no_grad():

    for i, filename in enumerate(test_files):

        try:

            # ------------------------------------------
            # Load image
            # ------------------------------------------

            input_path = os.path.join(
                test_dir,
                filename
            )

            noisy = np.load(input_path).astype(np.float32)

            # ------------------------------------------
            # Correct dataset scaling
            # ------------------------------------------

            noisy = np.clip(noisy, 0.0, 1.0)

            # ------------------------------------------
            # Convert to tensor
            # ------------------------------------------

            input_tensor = (
                torch.from_numpy(noisy)
                .unsqueeze(0)
                .unsqueeze(0)
                .to(device)
            )

            # ------------------------------------------
            # SwinIR inference
            # ------------------------------------------

            restored = model(input_tensor)

            restored = (
                restored
                .squeeze()
                .detach()
                .cpu()
                .numpy()
            )

            # ------------------------------------------
            # Clip output
            # ------------------------------------------

            restored = np.clip(
                restored,
                0.0,
                1.0
            )

            # ------------------------------------------
            # Save restored image
            # ------------------------------------------

            image_id = os.path.splitext(filename)[0]

            output_path = os.path.join(
                output_dir,
                image_id + "_restored.npy"
            )

            np.save(
                output_path,
                restored.astype(np.float32)
            )

            successful += 1

            # ------------------------------------------
            # Progress
            # ------------------------------------------

            if (i + 1) % 25 == 0 or i == 0:

                print(
                    f"{i+1}/{len(test_files)} "
                    f"| Successful: {successful} "
                    f"| Failed: {failed}"
                )

        except Exception as e:

            failed += 1

            print(
                f"\n❌ Failed: {filename}"
            )
            print("Error:", str(e))


# --------------------------------------------------
# FINAL SUMMARY
# --------------------------------------------------

print("\n" + "=" * 60)
print("TEST INFERENCE COMPLETED")
print("=" * 60)

print("Total test images :", len(test_files))
print("Successfully done :", successful)
print("Failed            :", failed)

print("\nResults saved to:")
