import torch
import numpy as np
from PIL import Image
import gradio as gr

model.eval()
model.to(device)

def restore_image(input_image):

    if input_image is None:
        return None, None

    # Convert to grayscale
    img = Image.fromarray(input_image).convert("L")

    # Original input
    original = np.array(img).astype(np.float32) / 255.0

    # Resize to model input size
    model_input = Image.fromarray(
        np.uint8(np.clip(original, 0, 1) * 255)
    ).resize((128, 128), Image.Resampling.BICUBIC)

    model_input = np.array(model_input).astype(np.float32) / 255.0

    # Tensor: [batch, channel, height, width]
    tensor = torch.from_numpy(model_input)
    tensor = tensor.unsqueeze(0).unsqueeze(0)
    tensor = tensor.to(device)

    # Inference
    with torch.no_grad():
        output = model(tensor)

    # Convert output to numpy
    output = output.squeeze().detach().cpu().numpy()

    # Clamp
    output = np.clip(output, 0, 1)

    # Convert to image
    restored = np.uint8(output * 255)

    # Input display
    input_display = np.uint8(original * 255)

    input_display = Image.fromarray(input_display).resize(
        (restored.shape[1], restored.shape[0]),
        Image.Resampling.BICUBIC
    )

    restored_image = Image.fromarray(restored)

    return input_display, restored_image


print("✅ SwinIR inference function ready")
print("Device:", device)

demo = gr.Interface(
    fn=restore_image,

    inputs=gr.Image(
        type="numpy",
        image_mode="L",
        label="Upload Noisy / Degraded Image"
    ),

    outputs=[
        gr.Image(
            type="pil",
            label="Input Image"
        ),
        gr.Image(
            type="pil",
            label="SwinIR Restored Image"
        )
    ],

    title="Semiconductor Image Restoration using SwinIR",

    description=(
        "AI-based restoration of degraded images using "
        "a trained SwinIR image restoration model."
    )
)

print("✅ Demo interface created successfully")

demo.launch(share=True)

