import torch
import numpy as np

model.eval()

def calculate_psnr(pred, target, max_val=1.0):
    mse = torch.mean((pred - target) ** 2)
    if mse == 0:
        return float("inf")
    return 10 * torch.log10((max_val ** 2) / mse).item()

def calculate_ssim_simple(pred, target):
    # Global SSIM approximation for evaluation
    pred = pred.float()
    target = target.float()

    mu_x = pred.mean()
    mu_y = target.mean()

    sigma_x = ((pred - mu_x) ** 2).mean()
    sigma_y = ((target - mu_y) ** 2).mean()
    sigma_xy = ((pred - mu_x) * (target - mu_y)).mean()

    C1 = 0.01 ** 2
    C2 = 0.03 ** 2

    ssim = ((2 * mu_x * mu_y + C1) *
            (2 * sigma_xy + C2)) / \
           ((mu_x ** 2 + mu_y ** 2 + C1) *
            (sigma_x + sigma_y + C2))

    return ssim.item()

total_psnr = 0.0
total_ssim = 0.0
count = 0

with torch.no_grad():
    for batch in val_loader:

        if isinstance(batch, (list, tuple)):
            noisy, gt = batch[0].to(device), batch[1].to(device)

        elif isinstance(batch, dict):
            noisy = batch["noisy"].to(device)
            gt = batch["gt"].to(device)

        output = model(noisy)

        # Keep values in valid image range
        output = torch.clamp(output, 0, 1)
        gt = torch.clamp(gt, 0, 1)

        for i in range(output.shape[0]):
            total_psnr += calculate_psnr(output[i], gt[i])
            total_ssim += calculate_ssim_simple(output[i], gt[i])
            count += 1

avg_psnr = total_psnr / count
avg_ssim = total_ssim / count

print("\n========================================")
print("       EPOCH 20 IMAGE QUALITY")
print("========================================")
print(f"Images evaluated : {count}")
print(f"Average PSNR     : {avg_psnr:.4f} dB")
print(f"Average SSIM     : {avg_ssim:.6f}")
print("========================================")

