import os

search_paths = [
    "/content",
    "/content/drive/MyDrive/SwinIR_Project"
]

matches = []

for base in search_paths:
    if not os.path.exists(base):
        continue

    for root, dirs, files in os.walk(base):
        # Avoid huge irrelevant directories
        dirs[:] = [d for d in dirs if d not in [
            ".cache", ".config", "node_modules"
        ]]

        for file in files:
            if file.endswith(".py"):
                path = os.path.join(root, file)

                try:
                    with open(path, "r", errors="ignore") as f:
                        text = f.read()

                    if "class SwinIR" in text:
                        matches.append(path)

                except:
                    pass

print("SwinIR model files found:")
for path in matches:
    print(path)

