import os
import json
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

# ============================================
# ORIGINAL DATASET PATHS
# ============================================

gt_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"
lq_dir = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"

# ============================================
# LOAD ORIGINAL SPLIT
# ============================================

split_path = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

with open(split_path, "r") as f:
    split_data = json.load(f)

train_pairs = split_data["train"]
val_pairs = split_data["val"]

print("Training pairs   :", len(train_pairs))
print("Validation pairs :", len(val_pairs))


# ============================================
# DATASET
# ============================================

class NPYSuperResolutionDataset(Dataset):

    def __init__(self, pairs, gt_dir, lq_dir):
        self.pairs = pairs
        self.gt_dir = gt_dir
        self.lq_dir = lq_dir

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, index):

        name = self.pairs[index]

        lr = np.load(
            os.path.join(self.lq_dir, name + ".npy")
        ).astype(np.float32)

        gt = np.load(
            os.path.join(self.gt_dir, name + ".npy")
        ).astype(np.float32)

        # IMPORTANT:
        # Same preprocessing used during training
        gt = np.clip(gt, 0.0, 1.0)

        lr = torch.from_numpy(lr).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return lr, gt, name


# ============================================
# VALIDATION DATASET
# ============================================

val_dataset = NPYSuperResolutionDataset(
    val_pairs,
    gt_dir,
    lq_dir
)

val_loader = DataLoader(
    val_dataset,
    batch_size=4,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

print("\n======================================")
print("VALIDATION LOADER READY")
print("======================================")
print("Validation samples :", len(val_dataset))
print("Validation batches :", len(val_loader))
print("Batch size         :", val_loader.batch_size)

model.eval()

lr, gt, name = val_dataset[0]

lr = lr.unsqueeze(0).to(device)
gt = gt.unsqueeze(0).to(device)

with torch.no_grad():
    output = model(lr)

print("======================================")
print("SINGLE IMAGE TEST")
print("======================================")
print("Sample name :", name)
print("LR shape    :", tuple(lr.shape))
print("GT shape    :", tuple(gt.shape))
print("Output shape:", tuple(output.shape))

print("\nValue ranges")
print("LR     :", lr.min().item(), "to", lr.max().item())
print("GT     :", gt.min().item(), "to", gt.max().item())
print("Output :", output.min().item(), "to", output.max().item())

