import numpy as np
import cv2
import os

# Load SwinIR restored image
input_path = "/content/SwinIR_Demo/000000_demo_restored.npy"

restored = np.load(input_path).astype(np.float32)

# Normalize to 0-1
r_min = restored.min()
r_max = restored.max()

if r_max > r_min:
    img = (restored - r_min) / (r_max - r_min)
else:
    img = np.zeros_like(restored)

# Convert to 8-bit for image processing
img_8bit = np.clip(img * 255, 0, 255).astype(np.uint8)

# Detect semiconductor image edges
gx = cv2.Sobel(img_8bit, cv2.CV_32F, 1, 0, ksize=3)
gy = cv2.Sobel(img_8bit, cv2.CV_32F, 0, 1, ksize=3)

edge_strength = cv2.magnitude(gx, gy)

# Normalize edge map
edge_strength = cv2.normalize(
    edge_strength,
    None,
    0,
    1,
    cv2.NORM_MINMAX
)

# Smooth image to obtain local structure
smooth = cv2.GaussianBlur(img, (5, 5), 0)

# Detail component
detail = img - smooth

# Adaptive enhancement:
# stronger enhancement around detected edges
enhanced = img + (0.8 * edge_strength * detail)

# Keep valid range
enhanced = np.clip(enhanced, 0, 1)

# Save enhanced image
output_dir = "/content/SwinIR_Demo"
os.makedirs(output_dir, exist_ok=True)

enhanced_path = os.path.join(
    output_dir,
    "000000_innovative_enhanced.npy"
)

np.save(enhanced_path, enhanced.astype(np.float32))

# Save PNG for visualization
png_path = os.path.join(
    output_dir,
    "000000_innovative_enhanced.png"
)

cv2.imwrite(
    png_path,
    (enhanced * 255).astype(np.uint8)
)

print("✅ INNOVATION MODULE COMPLETED")
print("Input restored shape :", restored.shape)
print("Enhanced shape       :", enhanced.shape)
print("Enhanced NPY saved   :", enhanced_path)
print("Enhanced PNG saved   :", png_path)

