import numpy as np
import cv2
import matplotlib.pyplot as plt
import os

# --------------------------------------------------
# Paths
# --------------------------------------------------
input_path = "/content/SwinIR_Final_Test/NoisyLR/000000.npy"
restored_path = "/content/SwinIR_Demo/000000_demo_restored.npy"

# --------------------------------------------------
# Load official input and SwinIR output
# --------------------------------------------------
input_img = np.load(input_path).astype(np.float32)
restored_img = np.load(restored_path).astype(np.float32)

# --------------------------------------------------
# Normalize each image only for visualization/analysis
# --------------------------------------------------
def normalize_image(img):
    mn = img.min()
    mx = img.max()

    if mx > mn:
        return (img - mn) / (mx - mn)

    return np.zeros_like(img)

input_norm = normalize_image(input_img)
restored_norm = normalize_image(restored_img)

# --------------------------------------------------
# Resize input temporarily to restored resolution
# --------------------------------------------------
input_256 = cv2.resize(
    input_norm,
    (restored_norm.shape[1], restored_norm.shape[0]),
    interpolation=cv2.INTER_CUBIC
)

# --------------------------------------------------
# Calculate Sobel edge maps
# --------------------------------------------------
def edge_map(img):
    img8 = np.clip(img * 255, 0, 255).astype(np.uint8)

    gx = cv2.Sobel(img8, cv2.CV_32F, 1, 0, ksize=3)
    gy = cv2.Sobel(img8, cv2.CV_32F, 0, 1, ksize=3)

    magnitude = cv2.magnitude(gx, gy)

    # Normalize edge strength
    magnitude = cv2.normalize(
        magnitude,
        None,
        0,
        1,
        cv2.NORM_MINMAX
    )

    return magnitude

input_edges = edge_map(input_256)
restored_edges = edge_map(restored_norm)

# --------------------------------------------------
# Basic structure statistics
# --------------------------------------------------
input_edge_mean = float(input_edges.mean())
restored_edge_mean = float(restored_edges.mean())

input_edge_pixels = int(np.sum(input_edges > 0.20))
restored_edge_pixels = int(np.sum(restored_edges > 0.20))

print("==============================================")
print("STRUCTURE-PRESERVATION ANALYSIS")
print("==============================================")

print("\nInput:")
print("Original shape:", input_img.shape)
print("Temporary analysis shape:", input_256.shape)

print("\nSwinIR:")
print("Restored shape:", restored_img.shape)

print("\n--- Edge Statistics ---")
print("Input edge strength mean   :", input_edge_mean)
print("Restored edge strength mean:", restored_edge_mean)

print("\nEdge pixels above threshold:")
print("Input    :", input_edge_pixels)
print("Restored :", restored_edge_pixels)

# --------------------------------------------------
# Visualization
# --------------------------------------------------
plt.figure(figsize=(15, 5))

plt.subplot(1, 3, 1)
plt.imshow(input_256, cmap="gray")
plt.title("Official Degraded Input\n(temporarily resized)")
plt.axis("off")

plt.subplot(1, 3, 2)
plt.imshow(restored_norm, cmap="gray")
plt.title("SwinIR Restored\n256 × 256")
plt.axis("off")

plt.subplot(1, 3, 3)
plt.imshow(restored_edges, cmap="gray")
plt.title("SwinIR Structure / Edge Map")
plt.axis("off")

plt.suptitle(
    "Semiconductor Structure-Preservation Analysis",
    fontsize=16,
    fontweight="bold"
)

plt.tight_layout()

# Save analysis visualization separately
analysis_path = "/content/SwinIR_Demo/000000_Structure_Analysis.png"

plt.savefig(
    analysis_path,
    dpi=300,
    bbox_inches="tight"
)

plt.show()

print("\n✅ STEP 2 COMPLETED")
print("Analysis figure saved at:")
print(analysis_path)

print("\n⚠️ Official dataset was NOT modified.")

