import sys
import torch

sys.path.insert(0, "/content/SwinIR")

from models.network_swinir import SwinIR

checkpoint_path = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth"

print("=" * 70)
print("LOADING EPOCH-20 SWINIR MODEL")
print("=" * 70)

# ---------------------------------------------------------
# Device
# ---------------------------------------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)

# ---------------------------------------------------------
# Create the SAME architecture used in your project
# ---------------------------------------------------------
model = SwinIR(
    img_size=128,
    patch_size=1,
    in_chans=1,
    embed_dim=96,
    depths=[6, 6, 6, 6],
    num_heads=[6, 6, 6, 6],
    window_size=8,
    mlp_ratio=2.0,
    qkv_bias=True,
    qk_scale=None,
    drop_rate=0.0,
    attn_drop_rate=0.0,
    drop_path_rate=0.1,
    norm_layer=torch.nn.LayerNorm,
    ape=False,
    patch_norm=True,
    use_checkpoint=False,
    upscale=2,
    img_range=1.0,
    upsampler="pixelshuffle",
    resi_connection="1conv"
)

print("✅ SwinIR architecture created")

# ---------------------------------------------------------
# Load checkpoint
# ---------------------------------------------------------
checkpoint = torch.load(
    checkpoint_path,
    map_location="cpu"
)

print("✅ Checkpoint loaded")
print("Saved epoch:", checkpoint["epoch"])
print("Train loss :", checkpoint["train_loss"])
print("Val loss   :", checkpoint["val_loss"])

# ---------------------------------------------------------
# Load model weights
# ---------------------------------------------------------
try:

    result = model.load_state_dict(
        checkpoint["model_state_dict"],
        strict=True
    )

    print("\n" + "=" * 70)
    print("🎉 MODEL WEIGHTS LOADED SUCCESSFULLY")
    print("=" * 70)
    print("Missing keys   :", result.missing_keys)
    print("Unexpected keys:", result.unexpected_keys)

    model = model.to(device)
    model.eval()

    print("Model device:", next(model.parameters()).device)
    print("Model mode  : evaluation")

except Exception as e:

    print("\n" + "=" * 70)
    print("❌ MODEL LOADING FAILED")
    print("=" * 70)
    print(type(e).__name__)
    print(e)

