    img_size=128,
    patch_size=1,
    in_chans=1,
    embed_dim=96,
    depths=[6, 6, 6, 6],
    num_heads=[6, 6, 6, 6],
    window_size=8,
    mlp_ratio=2.0,
    qkv_bias=True,
    qk_scale=None,
    drop_rate=0.0,
    attn_drop_rate=0.0,
    drop_path_rate=0.1,
    norm_layer=torch.nn.LayerNorm,
    ape=False,
    patch_norm=True,
    use_checkpoint=False,
