import torch
import sys
import os

sys.path.insert(0, "/content/SwinIR")

from models.network_swinir import SwinIR

checkpoint_path = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth"

print("=" * 75)
print("AUTO-DETECTING SWINIR CHECKPOINT CONFIGURATION")
print("=" * 75)

# Load checkpoint
checkpoint = torch.load(checkpoint_path, map_location="cpu")
state = checkpoint["model_state_dict"]

print("Checkpoint epoch :", checkpoint["epoch"])
print("Train loss       :", checkpoint["train_loss"])
print("Validation loss  :", checkpoint["val_loss"])

# ---------------------------------------------------------
# Detect embed dimension
# ---------------------------------------------------------
embed_dim = state["conv_first.weight"].shape[0]

print("\nDetected embed_dim:", embed_dim)

# ---------------------------------------------------------
# Detect MLP hidden dimension
# ---------------------------------------------------------
fc1_key = None

for key in state.keys():
    if ".mlp.fc1.weight" in key:
        fc1_key = key
        break

if fc1_key is None:
    raise RuntimeError("Could not find MLP fc1 weight in checkpoint.")

fc1_shape = tuple(state[fc1_key].shape)

mlp_hidden = fc1_shape[0]
detected_mlp_ratio = mlp_hidden / embed_dim

print("MLP fc1 shape     :", fc1_shape)
print("MLP hidden dim    :", mlp_hidden)
print("Detected MLP ratio:", detected_mlp_ratio)

# ---------------------------------------------------------
# Detect number of heads
# ---------------------------------------------------------
head_key = None

for key in state.keys():
    if "relative_position_bias_table" in key:
        head_key = key
        break

if head_key:
    num_heads_detected = state[head_key].shape[1]
else:
    num_heads_detected = 6

print("Detected heads    :", num_heads_detected)

# ---------------------------------------------------------
# Detect window size
# ---------------------------------------------------------
if head_key:
    table_size = state[head_key].shape[0]

    window_size = int((table_size ** 0.5 + 1) / 2)

    print("Detected window   :", window_size)
else:
    window_size = 8

# ---------------------------------------------------------
# Create exact model using detected parameters
# ---------------------------------------------------------
print("\nCreating model...")

model = SwinIR(
    img_size=128,
    patch_size=1,
    in_chans=1,
    embed_dim=embed_dim,
    depths=[6, 6, 6, 6],
    num_heads=[num_heads_detected] * 4,
    window_size=window_size,
    mlp_ratio=detected_mlp_ratio,
    qkv_bias=True,
    qk_scale=None,
    drop_rate=0.0,
    attn_drop_rate=0.0,
    drop_path_rate=0.1,
    norm_layer=torch.nn.LayerNorm,
    ape=False,
    patch_norm=True,
    use_checkpoint=False,
    upscale=2,
    img_range=1.0,
    upsampler="pixelshuffle",
    resi_connection="1conv"
)

print("✅ Model created")

# ---------------------------------------------------------
# Load weights
# ---------------------------------------------------------
try:

    result = model.load_state_dict(
        state,
        strict=True
    )

    print("\n" + "=" * 75)
    print("🎉🎉 EPOCH-20 MODEL LOADED SUCCESSFULLY 🎉🎉")
    print("=" * 75)

    print("Missing keys   :", result.missing_keys)
    print("Unexpected keys:", result.unexpected_keys)

    device = torch.device(
        "cuda" if torch.cuda.is_available() else "cpu"
    )

    model = model.to(device)
    model.eval()

    print("Device          :", device)
    print("Model mode      : eval")
    print("Epoch           :", checkpoint["epoch"])
    print("Validation loss :", checkpoint["val_loss"])

except Exception as e:

    print("\n" + "=" * 75)
    print("❌ STILL NOT MATCHING")
    print("=" * 75)
    print(type(e).__name__)
    print(e)

print("=" * 75)

