# ============================================================

import os
import glob

DRIVE = "/content/drive/MyDrive"

print("=" * 70)
print("SEARCHING GOOGLE DRIVE FOR NoisyLR DATA")
print("=" * 70)

matches = []

for root, dirs, files in os.walk(DRIVE):

    # Ignore unnecessary folders
    dirs[:] = [
        d for d in dirs
        if d not in [
            ".trash",
            ".cache",
            "__pycache__"
        ]
    ]

    root_lower = root.lower()

    # Folder name contains noisy
    if "noisy" in os.path.basename(root).lower():

        npy_count = len(
            glob.glob(os.path.join(root, "*.npy"))
        )

        matches.append(
            ("FOLDER", root, npy_count)
        )

    # Files containing noisy in name
    for file in files:

        if "noisy" in file.lower():

            path = os.path.join(root, file)

            matches.append(
                ("FILE", path, os.path.getsize(path))
            )

print("\nRESULTS")
print("=" * 70)

if not matches:

    print("❌ No additional NoisyLR data found.")

else:

    for item_type, path, value in matches:

        if item_type == "FOLDER":

            print(
                f"📁 {value} NPY files -> {path}"
            )

        else:

            print(
                f"📦 FILE -> {path}"
            )

print("\nTotal matches:", len(matches))

