import os
import glob
import numpy as np
import torch
import torch.nn as nn

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

DATA_ROOT = "/content/drive/MyDrive/SwinIR_Data_Complete"

NOISY_DIR = os.path.join(
    DATA_ROOT, "train", "NoisyLR"
)

GT_DIR = os.path.join(
    DATA_ROOT, "train", "GT"
)

BASELINE_PATH = (
    "/content/drive/MyDrive/"
    "SwinIR_Project/"
    "SSP_SwinIR_Epoch20_Baseline.pth"
)

# ------------------------------------------------------------
# DEVICE
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("=" * 70)
print("EPOCH-20 BASELINE INFERENCE TEST")
print("=" * 70)

print("Device:", device)

if torch.cuda.is_available():
    print(
        "GPU:",
        torch.cuda.get_device_name(0)
    )

# ------------------------------------------------------------
# CHECK MODEL
# ------------------------------------------------------------

model = model.to(device)
model.eval()

print("\nModel ready.")
print(
    "Parameters:",
    sum(p.numel() for p in model.parameters())
)

# ------------------------------------------------------------
# GET ONE MATCHING FILE
# ------------------------------------------------------------

noisy_files = sorted(
    glob.glob(os.path.join(NOISY_DIR, "*.npy"))
)

gt_files = sorted(
    glob.glob(os.path.join(GT_DIR, "*.npy"))
)

noisy_ids = {
    os.path.splitext(os.path.basename(f))[0]
    for f in noisy_files
}

gt_ids = {
    os.path.splitext(os.path.basename(f))[0]
    for f in gt_files
}

sample_id = sorted(
    noisy_ids & gt_ids
)[0]

noisy_path = os.path.join(
    NOISY_DIR,
    sample_id + ".npy"
)

gt_path = os.path.join(
    GT_DIR,
    sample_id + ".npy"
)

# ------------------------------------------------------------
# LOAD
# ------------------------------------------------------------

noisy = np.load(noisy_path).astype(
    np.float32
)

gt = np.load(gt_path).astype(
    np.float32
)

print("\nSample:", sample_id)

print("NoisyLR:", noisy.shape)
print("GT     :", gt.shape)

# ------------------------------------------------------------
# CONVERT TO TENSOR
# 2D image -> [B,C,H,W]
# ------------------------------------------------------------

inp = torch.from_numpy(noisy)

if inp.ndim == 2:

    inp = inp.unsqueeze(0).unsqueeze(0)

elif inp.ndim == 3:

    inp = inp.unsqueeze(0)

else:

    raise ValueError(
        f"Unexpected input shape: {inp.shape}"
    )

inp = inp.to(device)

print("\nInput tensor:", tuple(inp.shape))

# ------------------------------------------------------------
# INFERENCE
# ------------------------------------------------------------

with torch.no_grad():

    output = model(inp)

print(
    "Output tensor:",
    tuple(output.shape)
)

# ------------------------------------------------------------
# OUTPUT CHECK
# ------------------------------------------------------------

output_np = (
    output.squeeze()
    .detach()
    .cpu()
    .numpy()
)

print("\nOutput image shape:", output_np.shape)

print(
    "Output range:",
    float(output_np.min()),
    "to",
    float(output_np.max())
)

print(
    "GT range:",
    float(gt.min()),
    "to",
    float(gt.max())
)

# ------------------------------------------------------------
# SIZE CHECK
# ------------------------------------------------------------

if output_np.shape == gt.shape:

    print("\n✅ OUTPUT SIZE MATCHES GT")

else:

    print("\n❌ SIZE MISMATCH")

    print(
        "Output:",
        output_np.shape
    )

    print(
        "GT:",
        gt.shape
    )

print("\n" + "=" * 70)
print("SINGLE IMAGE BASELINE TEST COMPLETE")
print("=" * 70)

