import torch
import torch.nn as nn
import torch.nn.functional as F
import math

DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

CHECKPOINT_PATH = (
    "/content/drive/MyDrive/"
    "SwinIR_Project/swinir_epoch_20.pth"
)

# ------------------------------------------------------------
# Window utilities
# ------------------------------------------------------------

def window_partition(x, window_size):
    B, H, W, C = x.shape

    x = x.view(
        B,
        H // window_size,
        window_size,
        W // window_size,
        window_size,
        C
    )

    windows = (
        x.permute(0, 1, 3, 2, 4, 5)
        .contiguous()
        .view(-1, window_size, window_size, C)
    )

    return windows


def window_reverse(windows, window_size, H, W):
    B = int(
        windows.shape[0] /
        ((H // window_size) * (W // window_size))
    )

    x = windows.view(
        B,
        H // window_size,
        W // window_size,
        window_size,
        window_size,
        -1
    )

    x = (
        x.permute(0, 1, 3, 2, 4, 5)
        .contiguous()
        .view(B, H, W, -1)
    )

    return x


# ------------------------------------------------------------
# MLP
# ------------------------------------------------------------

class Mlp(nn.Module):

    def __init__(
        self,
        in_features,
        hidden_features=None,
        out_features=None,
        act_layer=nn.GELU,
        drop=0.0
    ):

        super().__init__()

        out_features = out_features or in_features
        hidden_features = hidden_features or in_features

        self.fc1 = nn.Linear(
            in_features,
            hidden_features
        )

        self.act = act_layer()

        self.fc2 = nn.Linear(
            hidden_features,
            out_features
        )

        self.drop = nn.Dropout(drop)

    def forward(self, x):

        x = self.fc1(x)
        x = self.act(x)
        x = self.drop(x)

        x = self.fc2(x)
        x = self.drop(x)

        return x


# ------------------------------------------------------------
# Window Attention
# ------------------------------------------------------------

class WindowAttention(nn.Module):

    def __init__(
        self,
        dim,
        window_size,
        num_heads,
        qkv_bias=True
    ):

        super().__init__()

        self.dim = dim
        self.window_size = window_size
        self.num_heads = num_heads

        head_dim = dim // num_heads

        self.scale = head_dim ** -0.5

        self.qkv = nn.Linear(
            dim,
            dim * 3,
            bias=qkv_bias
        )

        self.proj = nn.Linear(
            dim,
            dim
        )

    def forward(self, x, mask=None):

        B_, N, C = x.shape

        qkv = (
            self.qkv(x)
            .reshape(
                B_,
                N,
                3,
                self.num_heads,
                C // self.num_heads
            )
            .permute(2, 0, 3, 1, 4)
        )

        q, k, v = qkv[0], qkv[1], qkv[2]

        q = q * self.scale

        attn = q @ k.transpose(-2, -1)

        if mask is not None:

            nW = mask.shape[0]

            attn = attn.view(
                B_ // nW,
                nW,
                self.num_heads,
                N,
                N
            )

            attn = attn + mask.unsqueeze(1).unsqueeze(0)

            attn = attn.view(
                -1,
                self.num_heads,
                N,
                N
            )

        attn = F.softmax(
            attn,
            dim=-1
        )

        x = (
            attn @ v
        ).transpose(
            1,
            2
        ).reshape(
            B_,
            N,
            C
        )

        x = self.proj(x)

        return x


# ------------------------------------------------------------
# Swin Transformer Block
# ------------------------------------------------------------

class SwinTransformerBlock(nn.Module):

    def __init__(
        self,
        dim,
        num_heads,
        window_size=8,
        shift_size=0,
        mlp_ratio=4.0
    ):

        super().__init__()

        self.dim = dim
        self.window_size = window_size
        self.shift_size = shift_size

        self.norm1 = nn.LayerNorm(dim)

        self.attn = WindowAttention(
            dim,
            window_size,
            num_heads
        )

        self.norm2 = nn.LayerNorm(dim)

        self.mlp = Mlp(
            dim,
            int(dim * mlp_ratio)
        )

    def forward(self, x, x_size):

        H, W = x_size

        B, L, C = x.shape

        shortcut = x

        x = self.norm1(x)

        x = x.view(
            B,
            H,
            W,
            C
        )

        if self.shift_size > 0:

            shifted_x = torch.roll(
                x,
                shifts=(
                    -self.shift_size,
                    -self.shift_size
                ),
                dims=(1, 2)
            )

        else:

            shifted_x = x

        x_windows = window_partition(
            shifted_x,
            self.window_size
        )

        x_windows = x_windows.view(
            -1,
            self.window_size *
            self.window_size,
            C
        )

        attn_windows = self.attn(
            x_windows
        )

        attn_windows = attn_windows.view(
            -1,
            self.window_size,
            self.window_size,
            C
        )

        shifted_x = window_reverse(
            attn_windows,
            self.window_size,
            H,
            W
        )

        if self.shift_size > 0:

            x = torch.roll(
                shifted_x,
                shifts=(
                    self.shift_size,
                    self.shift_size
                ),
                dims=(1, 2)
            )

        else:

            x = shifted_x

        x = x.view(
            B,
            H * W,
            C
        )

        x = shortcut + x

        x = x + self.mlp(
            self.norm2(x)
        )

        return x


# ------------------------------------------------------------
# RSTB
# ------------------------------------------------------------

class RSTB(nn.Module):

    def __init__(
        self,
        dim,
        depth,
        num_heads,
        window_size,
        mlp_ratio=4.0
    ):

        super().__init__()

        self.residual_group = nn.ModuleList([
            SwinTransformerBlock(
                dim=dim,
                num_heads=num_heads,
                window_size=window_size,
                shift_size=0 if i % 2 == 0 else window_size // 2,
                mlp_ratio=mlp_ratio
            )
            for i in range(depth)
        ])

        self.conv = nn.Conv2d(
            dim,
            dim,
            3,
            1,
            1
        )

    def forward(self, x, x_size):

        H, W = x_size

        residual = x

        for block in self.residual_group:
            x = block(x, x_size)

        B, L, C = x.shape

        x = x.transpose(
            1,
            2
        ).contiguous().view(
            B,
            C,
            H,
            W
        )

        x = self.conv(x)

        x = x.flatten(
            2
        ).transpose(
            1,
            2
        )

        return residual + x


# ------------------------------------------------------------
# Main SwinIR
# ------------------------------------------------------------

class SwinIR(nn.Module):

    def __init__(
        self,
        img_size=128,
        patch_size=1,
        in_chans=1,
        embed_dim=96,
        depths=(6,6,6,6),
        num_heads=(6,6,6,6),
        window_size=8,
        mlp_ratio=4.0,
        upscale=2
    ):

        super().__init__()

        self.window_size = window_size
        self.embed_dim = embed_dim

        self.conv_first = nn.Conv2d(
            in_chans,
            embed_dim,
            3,
            1,
            1
        )

        self.patch_embed = nn.Sequential(
            nn.Identity(),
            nn.LayerNorm(embed_dim)
        )

        self.layers = nn.ModuleList()

        for i in range(4):

            self.layers.append(
                RSTB(
                    dim=embed_dim,
                    depth=depths[i],
                    num_heads=num_heads[i],
                    window_size=window_size,
                    mlp_ratio=mlp_ratio
                )
            )

        self.norm = nn.LayerNorm(embed_dim)

        self.conv_after_body = nn.Conv2d(
            embed_dim,
            embed_dim,
            3,
            1,
            1
        )

        self.conv_before_upsample = nn.Sequential(
            nn.Conv2d(
                embed_dim,
                64,
                3,
                1,
                1
            )
        )

        self.upsample = nn.Sequential(
            nn.Conv2d(
                64,
                64 * upscale * upscale,
                3,
                1,
                1
            ),
            nn.PixelShuffle(upscale)
        )

        self.conv_last = nn.Conv2d(
            64,
            1,
            3,
            1,
            1
        )

    def forward(self, x):

        H, W = x.shape[-2:]

        x = self.conv_first(x)

        B, C, H, W = x.shape

        residual = x

        x = x.flatten(
            2
        ).transpose(
            1,
            2
        )

        for layer in self.layers:
            x = layer(
                x,
                (H, W)
            )

        x = self.norm(x)

        x = x.transpose(
            1,
            2
        ).contiguous().view(
            B,
            C,
            H,
            W
        )

        x = self.conv_after_body(x)

        x = x + residual

        x = self.conv_before_upsample(x)

        x = self.upsample(x)

        x = self.conv_last(x)

        return x


print("=" * 70)
print("MODEL CLASS CREATED")
print("=" * 70)

print("embed_dim :", 96)
print("depths    :", (6,6,6,6))
print("heads     :", (6,6,6,6))
print("window    :", 8)
print("upscale   :", 2)

