# ADAPTIVE DETAIL-AWARE REFINEMENT MODULE
# ============================================================

import torch
import torch.nn as nn
import torch.nn.functional as F

class AdaptiveDetailRefinement(nn.Module):

    def __init__(self):
        super().__init__()

        # Lightweight local feature extraction
        self.feature = nn.Sequential(
            nn.Conv2d(1, 16, 3, padding=1),
            nn.ReLU(inplace=True),

            nn.Conv2d(16, 16, 3, padding=1),
            nn.ReLU(inplace=True),

            nn.Conv2d(16, 1, 3, padding=1)
        )

        # Learnable residual strength
        self.alpha = nn.Parameter(
            torch.tensor(0.10)
        )

    def forward(self, x):

        # Local detail estimate
        blur = F.avg_pool2d(
            x,
            kernel_size=3,
            stride=1,
            padding=1
        )

        detail = x - blur

        # Learned refinement
        correction = self.feature(detail)

        # Residual refinement
        output = x + self.alpha * correction

        # Keep valid image range
        output = torch.clamp(
            output,
            0.0,
            1.0
        )

        return output


print("=" * 70)
print("ADAPTIVE DETAIL REFINEMENT MODULE")
print("=" * 70)

innovation = AdaptiveDetailRefinement()

print("✅ Innovation module created")
print("Parameters:",
      sum(p.numel() for p in innovation.parameters()))

print("Innovation:")
print("  • Local detail extraction")
print("  • Adaptive residual correction")
print("  • Lightweight refinement")
print("  • Output range protection")

