import os
import glob
import numpy as np
import torch
from PIL import Image
from tqdm.auto import tqdm

# ============================================================
# EPOCH-20 SWINIR — TEST INFERENCE
# ============================================================

TEST_DIR = "/content/test_data/NoisyLR"
OUTPUT_DIR = "/content/drive/MyDrive/SwinIR_Project/results_epoch20_swinir"

os.makedirs(OUTPUT_DIR, exist_ok=True)

files = sorted(glob.glob(os.path.join(TEST_DIR, "*.npy")))

print("=" * 70)
print("EPOCH-20 SWINIR TEST INFERENCE")
print("=" * 70)

print("Test images:", len(files))
print("Output directory:", OUTPUT_DIR)
print("Device:", device)

assert len(files) > 0, "❌ No test images found"

model.eval()

# ------------------------------------------------------------
# Process images individually for maximum compatibility
# ------------------------------------------------------------

successful = 0
failed = 0

with torch.no_grad():

    for f in tqdm(files, desc="SwinIR inference"):

        try:
            # Load input
            arr = np.load(f).astype(np.float32)

            # Normalize
            if arr.max() > 1.0:
                arr = arr / 255.0

            # Convert H,W -> 1,1,H,W
            if arr.ndim == 2:
                inp = torch.from_numpy(arr).unsqueeze(0).unsqueeze(0)

            elif arr.ndim == 3:
                # Handle possible channel-first/channel-last
                if arr.shape[0] == 1:
                    inp = torch.from_numpy(arr).unsqueeze(0)
                elif arr.shape[-1] == 1:
                    inp = torch.from_numpy(
                        np.transpose(arr, (2, 0, 1))
                    ).unsqueeze(0)
                else:
                    raise ValueError(f"Unexpected shape: {arr.shape}")

            else:
                raise ValueError(f"Unexpected shape: {arr.shape}")

            inp = inp.to(device)

            # SwinIR
            output = model(inp)

            # Remove batch/channel dimensions
            output = output.detach().float().cpu().numpy()

            if output.ndim == 4:
                output = output[0, 0]

            elif output.ndim == 3:
                output = output[0]

            # Protect output range
            output = np.clip(output, 0.0, 1.0).astype(np.float32)

            # Filename
            name = os.path.splitext(os.path.basename(f))[0]

            # Save numerical output
            np.save(
                os.path.join(
                    OUTPUT_DIR,
                    name + "_swinir.npy"
                ),
                output
            )

            # Save PNG
            png = (output * 255.0).round().astype(np.uint8)

            Image.fromarray(png).save(
                os.path.join(
                    OUTPUT_DIR,
                    name + "_swinir.png"
                )
            )

            successful += 1

        except Exception as e:
            failed += 1
            print(f"\n❌ Failed: {os.path.basename(f)}")
            print("   Error:", e)

print("\n" + "=" * 70)
print("INFERENCE COMPLETE")
print("=" * 70)

print("Successful:", successful)
print("Failed:", failed)

saved_npy = glob.glob(
    os.path.join(OUTPUT_DIR, "*_swinir.npy")
)

saved_png = glob.glob(
    os.path.join(OUTPUT_DIR, "*_swinir.png")
)

print("Saved NPY:", len(saved_npy))
print("Saved PNG:", len(saved_png))

print("\nOutput folder:")
print(OUTPUT_DIR)

