import os
import glob
import random
import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import Dataset, DataLoader
from tqdm.auto import tqdm

# ============================================================
# DATASET
# ============================================================

NOISY_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"
GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

names = sorted([
    os.path.splitext(f)[0]
    for f in os.listdir(NOISY_DIR)
    if f.endswith(".npy")
])

print("Pairs found:", len(names))

# Use smaller subset for quick innovation training
random.shuffle(names)
train_names = names[:1000]

print("Training pairs:", len(train_names))

class RefinementDataset(Dataset):

    def __init__(self, names):
        self.names = names

    def __len__(self):
        return len(self.names)

    def __getitem__(self, idx):

        name = self.names[idx]

        noisy = np.load(
            os.path.join(NOISY_DIR, name + ".npy")
        ).astype(np.float32)

        gt = np.load(
            os.path.join(GT_DIR, name + ".npy")
        ).astype(np.float32)

        if noisy.max() > 1:
            noisy = noisy / 255.0

        if gt.max() > 1:
            gt = gt / 255.0

        noisy = torch.from_numpy(noisy).unsqueeze(0)
        gt = torch.from_numpy(gt).unsqueeze(0)

        return noisy, gt

dataset = RefinementDataset(train_names)

loader = DataLoader(
    dataset,
    batch_size=4,
    shuffle=True,
    num_workers=2
)

# ============================================================
# FREEZE SWINIR
# ============================================================

model.eval()

for p in model.parameters():
    p.requires_grad = False

innovation.train()

optimizer = torch.optim.Adam(
    innovation.parameters(),
    lr=1e-4
)

loss_fn = nn.L1Loss()

# ============================================================
# TRAIN
# ============================================================

EPOCHS = 3

for epoch in range(EPOCHS):

    total_loss = 0

    pbar = tqdm(loader)

    for noisy, gt in pbar:

        noisy = noisy.to(device)
        gt = gt.to(device)

        with torch.no_grad():
            swinir_out = model(noisy)

        refined = innovation(swinir_out)

        loss = loss_fn(refined, gt)

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        total_loss += loss.item()

        pbar.set_description(
            f"Epoch {epoch+1} Loss {loss.item():.5f}"
        )

    avg = total_loss / len(loader)

    print(
        f"\nEpoch {epoch+1} Avg Loss: {avg:.6f}"
    )

# Save innovation checkpoint
save_path = "/content/drive/MyDrive/SwinIR_Project/innovation_refinement.pth"

torch.save(
    innovation.state_dict(),
    save_path
)

print("\nSaved:")
print(save_path)

