import os
import glob
import numpy as np
import torch
from tqdm.auto import tqdm
from PIL import Image

TEST_DIR = "/content/test_data/NoisyLR"

CORRECT_DIR = (
    "/content/drive/MyDrive/SwinIR_Project/"
    "results_epoch20_swinir_CORRECT"
)

os.makedirs(CORRECT_DIR, exist_ok=True)

test_files = sorted(glob.glob(os.path.join(TEST_DIR, "*.npy")))

print("=" * 80)
print("CORRECT EPOCH-20 SWINIR INFERENCE")
print("=" * 80)
print("Test images:", len(test_files))
print("Input scale: RAW .npy — NO /255")
print("Output:", CORRECT_DIR)

assert len(test_files) == 400, \
    f"Expected 400 test images, found {len(test_files)}"

model.eval()

successful = 0
failed = 0

with torch.no_grad():

    for f in tqdm(test_files, desc="SwinIR CORRECT inference"):

        try:
            arr = np.load(f).astype(np.float32)

            # ==================================================
            # CRITICAL:
            # DO NOT divide by 255.
            # Dataset is already approximately 0–1.
            # ==================================================

            x = torch.from_numpy(arr)

            if x.ndim == 2:
                x = x.unsqueeze(0).unsqueeze(0)
            elif x.ndim == 3:
                x = x.unsqueeze(0)

            x = x.to(device)

            out = model(x)

            out = out[0, 0].detach().cpu().numpy()

            # Numerical safety only
            out = np.nan_to_num(
                out,
                nan=0.0,
                posinf=1.0,
                neginf=0.0
            )

            # Valid image range
            out = np.clip(out, 0.0, 1.0)

            sample = os.path.splitext(
                os.path.basename(f)
            )[0]

            np.save(
                os.path.join(
                    CORRECT_DIR,
                    sample + "_swinir.npy"
                ),
                out.astype(np.float32)
            )

            Image.fromarray(
                (out * 255).round().astype(np.uint8)
            ).save(
                os.path.join(
                    CORRECT_DIR,
                    sample + "_swinir.png"
                )
            )

            successful += 1

        except Exception as e:
            failed += 1
            print("\nFAILED:", f)
            print(e)

print("\n" + "=" * 80)
print("CORRECT SWINIR INFERENCE COMPLETE")
print("=" * 80)

print("Successful:", successful)
print("Failed    :", failed)

print(
    "NPY:",
    len(glob.glob(os.path.join(CORRECT_DIR, "*_swinir.npy")))
)

print(
    "PNG:",
    len(glob.glob(os.path.join(CORRECT_DIR, "*_swinir.png")))
)

print("=" * 80)

import os
import glob
import json
import numpy as np
import torch
from tqdm.auto import tqdm

NOISY_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"
GT_DIR    = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

CACHE_DIR = "/content/refinement_swinir_train_cache"
os.makedirs(CACHE_DIR, exist_ok=True)

# ------------------------------------------------------------
# Get 2880 training names from split file if available
# ------------------------------------------------------------

split_file = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

with open(split_file, "r") as f:
    split = json.load(f)

print("=" * 80)
print("BUILDING CORRECT SWINIR TRAINING CACHE")
print("=" * 80)

print("Split file loaded.")

print("Split keys:", list(split.keys()))

# Handle common split-file formats
train_names = None

for key in ["train", "train_files", "train_ids", "training"]:
    if key in split:
        train_names = split[key]
        break

if train_names is None:
    raise ValueError(
        "Could not identify training list in train_val_split.json"
    )

# Convert paths/names to bare sample IDs
clean_names = []

for x in train_names:

    x = os.path.basename(str(x))
    x = os.path.splitext(x)[0]

    # Remove possible suffixes
    x = x.replace("_NoisyLR", "")
    x = x.replace("_GT", "")

    clean_names.append(x)

train_names = sorted(set(clean_names))

print("Training samples:", len(train_names))

assert len(train_names) >= 2800, \
    f"Expected about 2880 training samples, found {len(train_names)}"

model.eval()

for p in model.parameters():
    p.requires_grad = False

successful = 0

with torch.no_grad():

    for name in tqdm(
        train_names,
        desc="Generating correct SwinIR cache"
    ):

        save_path = os.path.join(
            CACHE_DIR,
            name + ".npy"
        )

        if os.path.exists(save_path):
            successful += 1
            continue

        noisy_path = os.path.join(
            NOISY_DIR,
            name + ".npy"
        )

        if not os.path.exists(noisy_path):
            print("Missing:", noisy_path)
            continue

        # CRITICAL:
        # RAW input. NO /255.
        noisy = np.load(noisy_path).astype(np.float32)

        x = torch.from_numpy(noisy)

        if x.ndim == 2:
            x = x.unsqueeze(0).unsqueeze(0)
        elif x.ndim == 3:
            x = x.unsqueeze(0)

        x = x.to(device)

        output = model(x)

        output = output[0, 0].cpu().numpy()

        output = np.nan_to_num(
            output,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        output = np.clip(output, 0.0, 1.0)

        np.save(
            save_path,
            output.astype(np.float32)
        )

        successful += 1

print("\n" + "=" * 80)
print("✅ SWINIR TRAINING CACHE COMPLETE")
print("=" * 80)

print("Cached:", successful)
print(
    "Files:",
    len(glob.glob(CACHE_DIR + "/*.npy"))
)

