import os
import glob
import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import Dataset, DataLoader
from tqdm.auto import tqdm

CACHE_DIR = "/content/refinement_swinir_train_cache"
GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

SAVE_PATH = (
    "/content/drive/MyDrive/SwinIR_Project/"
    "innovation_refinement_FINAL.pth"
)

# ------------------------------------------------------------
# CHECK CACHE
# ------------------------------------------------------------

cache_files = sorted(
    glob.glob(os.path.join(CACHE_DIR, "*.npy"))
)

print("=" * 80)
print("FINAL ADAPTIVE DETAIL REFINEMENT TRAINING")
print("=" * 80)

print("SwinIR cached outputs:", len(cache_files))

assert len(cache_files) == 2880, \
    f"Expected 2880 cache files, found {len(cache_files)}"


# ------------------------------------------------------------
# DATASET
# ------------------------------------------------------------

class RefinementDataset(Dataset):

    def __init__(self, cache_files):
        self.files = cache_files

    def __len__(self):
        return len(self.files)

    def __getitem__(self, idx):

        cache_file = self.files[idx]

        name = os.path.splitext(
            os.path.basename(cache_file)
        )[0]

        gt_file = os.path.join(
            GT_DIR,
            name + ".npy"
        )

        swinir = np.load(
            cache_file
        ).astype(np.float32)

        gt = np.load(
            gt_file
        ).astype(np.float32)

        # ----------------------------------------------------
        # IMPORTANT:
        # Everything is already 0–1.
        # NO /255.
        # ----------------------------------------------------

        swinir = np.clip(
            swinir,
            0.0,
            1.0
        )

        gt = np.clip(
            gt,
            0.0,
            1.0
        )

        swinir = torch.from_numpy(
            swinir
        ).unsqueeze(0)

        gt = torch.from_numpy(
            gt
        ).unsqueeze(0)

        return swinir, gt


dataset = RefinementDataset(cache_files)

loader = DataLoader(
    dataset,
    batch_size=8,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

print("Dataset:", len(dataset))
print("Batches :", len(loader))


# ------------------------------------------------------------
# CREATE FRESH REFINEMENT MODULE
# ------------------------------------------------------------

innovation_final = AdaptiveDetailRefinement().to(device)

parameter_count = sum(
    p.numel()
    for p in innovation_final.parameters()
)

print("Refinement parameters:", parameter_count)

assert parameter_count == 2626


# ------------------------------------------------------------
# TRAINING
# ------------------------------------------------------------

optimizer = torch.optim.Adam(
    innovation_final.parameters(),
    lr=1e-4
)

criterion = nn.L1Loss()

EPOCHS = 5

innovation_final.train()

for epoch in range(EPOCHS):

    running_loss = 0.0

    progress = tqdm(
        loader,
        desc=f"Refinement Epoch {epoch+1}/{EPOCHS}"
    )

    for swinir_output, gt in progress:

        swinir_output = swinir_output.to(
            device,
            non_blocking=True
        )

        gt = gt.to(
            device,
            non_blocking=True
        )

        # ----------------------------------------------------
        # Adaptive refinement
        # ----------------------------------------------------

        refined = innovation_final(
            swinir_output
        )

        refined = torch.clamp(
            refined,
            0.0,
            1.0
        )

        loss = criterion(
            refined,
            gt
        )

        optimizer.zero_grad(
            set_to_none=True
        )

        loss.backward()

        optimizer.step()

        running_loss += loss.item()

        progress.set_postfix(
            loss=f"{loss.item():.6f}"
        )

    average_loss = (
        running_loss / len(loader)
    )

    print(
        f"\nEpoch {epoch+1}/{EPOCHS}"
        f"  Average L1 Loss = "
        f"{average_loss:.6f}"
    )


# ------------------------------------------------------------
# SAVE FINAL MODEL
# ------------------------------------------------------------

torch.save(
    {
        "model_state_dict":
            innovation_final.state_dict(),

        "parameters":
            parameter_count,

        "epochs":
            EPOCHS,

        "description":
            "Adaptive Detail Refinement trained "
            "on correct 0-1 scale SwinIR Epoch-20 outputs"
    },
    SAVE_PATH
)

print("\n" + "=" * 80)
print("✅ FINAL REFINEMENT MODEL SAVED")
print("=" * 80)

print("Parameters :", parameter_count)
print("Epochs     :", EPOCHS)
print("Checkpoint :", SAVE_PATH)

print("=" * 80)

