import os
import json
import glob
import numpy as np
import torch
import torch.nn.functional as F
from tqdm.auto import tqdm

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

DATASET = "/content/drive/MyDrive/SwinIR_Data_Complete"

NOISY_DIR = os.path.join(DATASET, "train", "NoisyLR")
GT_DIR    = os.path.join(DATASET, "train", "GT")

SPLIT_FILE = os.path.join(
    PROJECT,
    "train_val_split.json"
)

# Existing correct SwinIR outputs
SWINIR_TEST_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir_correct"
)

# Existing ADR checkpoint
ADR_CHECKPOINT = os.path.join(
    PROJECT,
    "innovation_refinement_FINAL.pth"
)

if not os.path.exists(ADR_CHECKPOINT):
    ADR_CHECKPOINT = os.path.join(
        PROJECT,
        "innovation_refinement.pth"
    )

print("=" * 80)
print("SWINIR vs SWINIR + ADR VALIDATION")
print("=" * 80)

print("Noisy directory :", NOISY_DIR)
print("GT directory    :", GT_DIR)
print("SwinIR outputs  :", SWINIR_TEST_DIR)
print("ADR checkpoint  :", ADR_CHECKPOINT)

assert os.path.isdir(NOISY_DIR), "NoisyLR directory not found"
assert os.path.isdir(GT_DIR), "GT directory not found"
assert os.path.exists(SPLIT_FILE), "Split file not found"
assert os.path.exists(ADR_CHECKPOINT), "ADR checkpoint not found"


# ------------------------------------------------------------
# LOAD VALIDATION SPLIT
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = split["val"]

print("\nValidation samples:", len(val_ids))

assert len(val_ids) == 320


# ------------------------------------------------------------
# LOAD ADR CLASS
# ------------------------------------------------------------

# The class should already exist from your previous notebook.
assert "AdaptiveDetailRefinement" in globals(), \
    "AdaptiveDetailRefinement class is not currently loaded."

innovation_eval = AdaptiveDetailRefinement().to(device)

checkpoint = torch.load(
    ADR_CHECKPOINT,
    map_location=device,
    weights_only=False
)

if "model_state_dict" in checkpoint:
    state_dict = checkpoint["model_state_dict"]
else:
    state_dict = checkpoint

innovation_eval.load_state_dict(
    state_dict,
    strict=True
)

innovation_eval.eval()

print("\n✅ ADR loaded")
print("Parameters:",
      sum(p.numel() for p in innovation_eval.parameters()))


# ------------------------------------------------------------
# METRIC FUNCTIONS
# ------------------------------------------------------------

def calculate_psnr(pred, target):
    pred = np.clip(pred, 0.0, 1.0)
    target = np.clip(target, 0.0, 1.0)

    mse = np.mean(
        (pred - target) ** 2
    )

    if mse == 0:
        return float("inf")

    return 10.0 * np.log10(
        1.0 / mse
    )


def calculate_ssim(pred, target):

    # Lightweight SSIM implementation
    pred = np.clip(pred, 0.0, 1.0).astype(np.float32)
    target = np.clip(target, 0.0, 1.0).astype(np.float32)

    x = torch.from_numpy(pred)[None, None]
    y = torch.from_numpy(target)[None, None]

    # Gaussian-like average pooling
    mu_x = F.avg_pool2d(
        x, kernel_size=11,
        stride=1, padding=5
    )

    mu_y = F.avg_pool2d(
        y, kernel_size=11,
        stride=1, padding=5
    )

    mu_x_sq = mu_x * mu_x
    mu_y_sq = mu_y * mu_y
    mu_xy = mu_x * mu_y

    sigma_x = (
        F.avg_pool2d(
            x * x,
            kernel_size=11,
            stride=1,
            padding=5
        ) - mu_x_sq
    )

    sigma_y = (
        F.avg_pool2d(
            y * y,
            kernel_size=11,
            stride=1,
            padding=5
        ) - mu_y_sq
    )

    sigma_xy = (
        F.avg_pool2d(
            x * y,
            kernel_size=11,
            stride=1,
            padding=5
        ) - mu_xy
    )

    C1 = 0.01 ** 2
    C2 = 0.03 ** 2

    ssim_map = (
        (2 * mu_xy + C1) *
        (2 * sigma_xy + C2)
    ) / (
        (mu_x_sq + mu_y_sq + C1) *
        (sigma_x + sigma_y + C2)
    )

    return ssim_map.mean().item()


# ------------------------------------------------------------
# FIND SWINIR OUTPUTS
# ------------------------------------------------------------

# Accept several possible filename conventions.
available_outputs = {}

for f in glob.glob(
    os.path.join(SWINIR_TEST_DIR, "*.npy")
):
    base = os.path.basename(f)

    # Remove common suffixes.
    sample_id = base.replace(
        "_swinir.npy", ""
    ).replace(
        "_correct.npy", ""
    ).replace(
        ".npy", ""
    )

    sample_id = sample_id.zfill(6)

    available_outputs[sample_id] = f

print("\nSwinIR output files found:",
      len(available_outputs))


# ------------------------------------------------------------
# BENCHMARK
# ------------------------------------------------------------

swinir_psnr = []
swinir_ssim = []

adr_psnr = []
adr_ssim = []

missing = []

print("\n" + "=" * 80)
print("RUNNING 320 VALIDATION SAMPLES")
print("=" * 80)

with torch.no_grad():

    for sample_id in tqdm(
        val_ids,
        desc="Validation"
    ):

        sample_id = str(sample_id).zfill(6)

        gt_path = os.path.join(
            GT_DIR,
            sample_id + ".npy"
        )

        swinir_path = available_outputs.get(
            sample_id
        )

        if (
            not os.path.exists(gt_path)
            or swinir_path is None
        ):
            missing.append(sample_id)
            continue

        gt = np.load(
            gt_path
        ).astype(np.float32)

        swinir = np.load(
            swinir_path
        ).astype(np.float32)

        # IMPORTANT:
        # NO /255 HERE.
        # Dataset is already approximately 0–1.
        gt = np.clip(gt, 0.0, 1.0)
        swinir = np.clip(swinir, 0.0, 1.0)

        # ----------------------------------------------------
        # BASELINE SWINIR
        # ----------------------------------------------------

        swinir_psnr.append(
            calculate_psnr(
                swinir,
                gt
            )
        )

        swinir_ssim.append(
            calculate_ssim(
                swinir,
                gt
            )
        )

        # ----------------------------------------------------
        # SWINIR + ADR
        # ----------------------------------------------------

        inp = torch.from_numpy(
            swinir
        ).unsqueeze(0).unsqueeze(0).to(device)

        refined = innovation_eval(inp)

        refined = torch.clamp(
            refined,
            0.0,
            1.0
        )

        refined_np = (
            refined.squeeze()
            .detach()
            .cpu()
            .numpy()
            .astype(np.float32)
        )

        adr_psnr.append(
            calculate_psnr(
                refined_np,
                gt
            )
        )

        adr_ssim.append(
            calculate_ssim(
                refined_np,
                gt
            )
        )


# ------------------------------------------------------------
# RESULTS
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("FINAL VALIDATION RESULTS")
print("=" * 80)

print("Evaluated samples:", len(swinir_psnr))
print("Missing samples  :", len(missing))

if missing:
    print("Missing:", missing[:20])

mean_swinir_psnr = np.mean(swinir_psnr)
mean_swinir_ssim = np.mean(swinir_ssim)

mean_adr_psnr = np.mean(adr_psnr)
mean_adr_ssim = np.mean(adr_ssim)

print("\n---------------- SWINIR BASELINE ----------------")
print(f"PSNR : {mean_swinir_psnr:.4f} dB")
print(f"SSIM : {mean_swinir_ssim:.6f}")

print("\n------------- SWINIR + ADR INNOVATION ------------")
print(f"PSNR : {mean_adr_psnr:.4f} dB")
print(f"SSIM : {mean_adr_ssim:.6f}")

print("\n---------------- IMPROVEMENT ----------------")
