# WINNING MODEL — ZERO-GPU OUTPUT AUDIT
# ============================================================

import os
import glob
import numpy as np

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

SWINIR_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir"
)

ADR_DIR = os.path.join(
    PROJECT,
    "final_adaptive_results"
)

print("=" * 80)
print("EXISTING OUTPUT AUDIT — NO GPU")
print("=" * 80)

print("GT    :", GT_DIR)
print("SwinIR:", SWINIR_DIR)
print("ADR   :", ADR_DIR)

# ------------------------------------------------------------
# Build ID -> file mapping
# ------------------------------------------------------------

def get_files(directory):

    files = {}

    for path in glob.glob(
        os.path.join(directory, "*.npy")
    ):

        name = os.path.basename(path)

        # Extract first 6-digit ID
        digits = ""

        for c in name:
            if c.isdigit():
                digits += c
                if len(digits) == 6:
                    break
            else:
                if len(digits) < 6:
                    digits = ""

        if len(digits) == 6:
            files[digits] = path

    return files


gt = get_files(GT_DIR)
sw = get_files(SWINIR_DIR)
adr = get_files(ADR_DIR)

print("\nGT files    :", len(gt))
print("SwinIR files:", len(sw))
print("ADR files   :", len(adr))

common = sorted(
    set(gt) & set(sw) & set(adr)
)

print("\nCommon IDs:", len(common))

# ------------------------------------------------------------
# Metric functions
# ------------------------------------------------------------

def psnr(a, b):

    a = np.nan_to_num(
        a, nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    b = np.nan_to_num(
        b, nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    a = np.clip(a, 0, 1)
    b = np.clip(b, 0, 1)

    mse = np.mean(
        (a - b) ** 2
    )

    if mse <= 1e-12:
        return 100.0

    return 10 * np.log10(
        1.0 / mse
    )


# ------------------------------------------------------------
# Evaluate common samples
# ------------------------------------------------------------

sw_scores = []
adr_scores = []

for sid in common:

    try:

        g = np.load(
            gt[sid]
        ).astype(np.float32)

        s = np.load(
            sw[sid]
        ).astype(np.float32)

        a = np.load(
            adr[sid]
        ).astype(np.float32)

        if g.shape != s.shape:
            continue

        if g.shape != a.shape:
            continue

        sw_scores.append(
            psnr(s, g)
        )

        adr_scores.append(
            psnr(a, g)
        )

    except Exception:
        pass


print("\n" + "=" * 80)
print("RESULT")
print("=" * 80)

print(
    "Valid comparable samples:",
    len(sw_scores)
)

if sw_scores:

    sw_mean = np.mean(sw_scores)
    adr_mean = np.mean(adr_scores)

    print(
        f"\nSwinIR PSNR : {sw_mean:.4f} dB"
    )

    print(
        f"ADR PSNR    : {adr_mean:.4f} dB"
    )

    print(
        f"Improvement : {adr_mean - sw_mean:+.4f} dB"
    )

    better = np.sum(
        np.array(adr_scores)
        >
        np.array(sw_scores)
    )

    print(
        f"\nADR better on: "
        f"{better}/{len(sw_scores)} samples"
    )

else:

    print(
        "\nNo safely comparable samples found."
    )

print("=" * 80)

print("model exists:", "model" in globals())

if "model" in globals():
    print("Model device:", next(model.parameters()).device)
    print("Training mode:", model.training)

