# CONTROLLED 20-IMAGE VALIDATION
# SwinIR vs SwinIR + ADR
# ============================================================

import os
import json
import numpy as np
import torch
from tqdm.auto import tqdm

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

NOISY_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"
GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

SPLIT_FILE = os.path.join(
    PROJECT, "train_val_split.json"
)

ADR_CHECKPOINT = os.path.join(
    PROJECT, "innovation_refinement_FINAL.pth"
)

device = torch.device("cuda")

# ------------------------------------------------------------
# Load exact validation split
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [str(x).zfill(6) for x in split["val"]]

# Only 20 samples -> saves GPU time
test_ids = val_ids[:20]

print("=" * 80)
print("CONTROLLED 20-IMAGE VALIDATION")
print("=" * 80)
print("Samples:", len(test_ids))
print("IDs:", test_ids)

# ------------------------------------------------------------
# Load ADR
# ------------------------------------------------------------

# Reuse existing ADR object if available
if "innovation" in globals():
    adr = innovation
elif "adr" in globals():
    adr = adr
else:
    raise RuntimeError(
        "ADR module is not loaded in this Colab session."
    )

adr = adr.to(device)
adr.eval()

# Load checkpoint if required
if os.path.exists(ADR_CHECKPOINT):

    ckpt = torch.load(
        ADR_CHECKPOINT,
        map_location=device,
        weights_only=False
    )

    if isinstance(ckpt, dict):

        if "model_state_dict" in ckpt:
            state = ckpt["model_state_dict"]

        elif "state_dict" in ckpt:
            state = ckpt["state_dict"]

        else:
            state = ckpt

    else:
        state = ckpt

    # Remove DataParallel prefix if present
    state = {
        k.replace("module.", "", 1): v
        for k, v in state.items()
    }

    adr.load_state_dict(
        state,
        strict=True
    )

print("ADR loaded successfully")
print("ADR parameters:",
      sum(p.numel() for p in adr.parameters()))

# ------------------------------------------------------------
# Metric functions
# ------------------------------------------------------------

def calc_psnr(pred, gt):

    pred = np.nan_to_num(
        pred,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    pred = np.clip(pred, 0.0, 1.0)

    gt = np.nan_to_num(
        gt,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    gt = np.clip(gt, 0.0, 1.0)

    mse = np.mean(
        (pred - gt) ** 2
    )

    if mse <= 1e-12:
        return 100.0

    return 10.0 * np.log10(
        1.0 / mse
    )


# ------------------------------------------------------------
# Run controlled experiment
# ------------------------------------------------------------

swinir_scores = []
adr_scores = []

results = []

with torch.no_grad():

    for sid in tqdm(
        test_ids,
        desc="20-image validation"
    ):

        input_path = os.path.join(
            NOISY_DIR,
            sid + ".npy"
        )

        gt_path = os.path.join(
            GT_DIR,
            sid + ".npy"
        )

        noisy = np.load(
            input_path
        ).astype(np.float32)

        gt = np.load(
            gt_path
        ).astype(np.float32)

        # --------------------------------------------
        # Ensure H,W
        # --------------------------------------------

        noisy = np.squeeze(noisy)
        gt = np.squeeze(gt)

        # --------------------------------------------
        # RAW SCALE — NO /255
        # --------------------------------------------

        x = torch.from_numpy(
            noisy
        ).unsqueeze(0).unsqueeze(0).to(
            device,
            dtype=torch.float32
        )

        # --------------------------------------------
        # SwinIR
        # --------------------------------------------

        swin = model(x)

        if isinstance(swin, (tuple, list)):
            swin = swin[0]

        # --------------------------------------------
        # ADR
        # --------------------------------------------

        refined = adr(swin)

        # --------------------------------------------
        # Convert
        # --------------------------------------------

        swin_np = (
            swin.detach()
            .float()
            .cpu()
            .numpy()
        )

        adr_np = (
            refined.detach()
            .float()
            .cpu()
            .numpy()
        )

        swin_np = np.squeeze(swin_np)
        adr_np = np.squeeze(adr_np)

        # --------------------------------------------
        # Safety clipping
        # --------------------------------------------

        swin_np = np.nan_to_num(
            swin_np,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        adr_np = np.nan_to_num(
            adr_np,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        swin_np = np.clip(
            swin_np, 0.0, 1.0
        ).astype(np.float32)

        adr_np = np.clip(
            adr_np, 0.0, 1.0
        ).astype(np.float32)

        # --------------------------------------------
        # Shape verification
        # --------------------------------------------

        if swin_np.shape != gt.shape:
            print(
                f"\nWARNING {sid}: "
                f"SwinIR {swin_np.shape} "
                f"GT {gt.shape}"
            )
            continue

        if adr_np.shape != gt.shape:
            print(
                f"\nWARNING {sid}: "
                f"ADR {adr_np.shape} "
                f"GT {gt.shape}"
            )
            continue

        # --------------------------------------------
        # Metrics
        # --------------------------------------------

        p_swin = calc_psnr(
            swin_np, gt
        )

        p_adr = calc_psnr(
            adr_np, gt
        )

        swinir_scores.append(p_swin)
        adr_scores.append(p_adr)

        results.append(
            (
                sid,
                p_swin,
                p_adr
            )
        )

# ------------------------------------------------------------
# FINAL RESULT
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("20-IMAGE CONTROLLED VALIDATION RESULT")
print("=" * 80)

print(
    "Valid samples:",
    len(swinir_scores)
)

if len(swinir_scores) > 0:

    swin_mean = np.mean(
        swinir_scores
    )

    adr_mean = np.mean(
        adr_scores
    )

    improvement = (
        adr_mean - swin_mean
    )

    adr_better = np.sum(
        np.array(adr_scores)
        >
        np.array(swinir_scores)
    )

    print(
        f"\nSwinIR PSNR      : {swin_mean:.4f} dB"
    )

    print(
        f"SwinIR + ADR PSNR: {adr_mean:.4f} dB"
    )

    print(
        f"Improvement      : {improvement:+.4f} dB"
    )

    print(
        f"ADR better       : "
        f"{adr_better}/{len(swinir_scores)}"
    )

    print("\nPer-image results:")

    for sid, ps, pa in results:
        print(
            f"{sid}: "
            f"SwinIR={ps:.3f} | "
            f"ADR={pa:.3f} | "
            f"Δ={pa-ps:+.3f}"
        )

print("\n" + "=" * 80)
print("CONTROLLED VALIDATION COMPLETE")
print("=" * 80)

# ============================================================
# STEP — SSIM + FINAL 20-IMAGE QUALITY EVALUATION
# ============================================================

import os
import json
import numpy as np
import torch
from skimage.metrics import structural_similarity

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

NOISY_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/NoisyLR"
GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

SPLIT_FILE = os.path.join(PROJECT, "train_val_split.json")

OUT_DIR = os.path.join(
    PROJECT,
    "final_20_validation_results"
)

os.makedirs(OUT_DIR, exist_ok=True)

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

ids = [str(x).zfill(6) for x in split["val"][:20]]

print("=" * 80)
print("FINAL 20-IMAGE SSIM EVALUATION")
print("=" * 80)

# ------------------------------------------------------------
# Make sure model + ADR are ready
# ------------------------------------------------------------

model.eval()
adr.eval()

device = torch.device("cuda")

sw_psnr = []
adr_psnr = []

sw_ssim = []
adr_ssim = []

with torch.no_grad():

    for sid in ids:

        noisy_path = os.path.join(
            NOISY_DIR, sid + ".npy"
        )

        gt_path = os.path.join(
            GT_DIR, sid + ".npy"
        )

        noisy = np.squeeze(
            np.load(noisy_path).astype(np.float32)
        )

        gt = np.squeeze(
            np.load(gt_path).astype(np.float32)
        )

        x = torch.from_numpy(
            noisy
        ).unsqueeze(0).unsqueeze(0).to(
            device
        )

        # SwinIR
        swin = model(x)

        if isinstance(swin, (tuple, list)):
            swin = swin[0]

        # ADR
        refined = adr(swin)

        swin_np = np.squeeze(
            swin.detach().cpu().numpy()
        )

        adr_np = np.squeeze(
            refined.detach().cpu().numpy()
        )

        # Safety
        swin_np = np.nan_to_num(
            swin_np, nan=0.0,
            posinf=1.0, neginf=0.0
        )

        adr_np = np.nan_to_num(
            adr_np, nan=0.0,
            posinf=1.0, neginf=0.0
        )

        swin_np = np.clip(
            swin_np, 0, 1
        ).astype(np.float32)

        adr_np = np.clip(
            adr_np, 0, 1
        ).astype(np.float32)

        gt = np.clip(
            gt, 0, 1
        ).astype(np.float32)

        # -------------------------
        # PSNR
        # -------------------------

        mse_s = np.mean((swin_np - gt) ** 2)
        mse_a = np.mean((adr_np - gt) ** 2)

        p_s = 10 * np.log10(
            1.0 / max(mse_s, 1e-12)
        )

        p_a = 10 * np.log10(
            1.0 / max(mse_a, 1e-12)
        )

        # -------------------------
        # SSIM
        # -------------------------

        s_s = structural_similarity(
            gt,
            swin_np,
            data_range=1.0
        )

        s_a = structural_similarity(
            gt,
            adr_np,
            data_range=1.0
        )

        sw_psnr.append(p_s)
        adr_psnr.append(p_a)

        sw_ssim.append(s_s)
        adr_ssim.append(s_a)

        # Save for later visualization
        np.save(
            os.path.join(
                OUT_DIR,
                sid + "_swinir.npy"
            ),
            swin_np
        )

        np.save(
            os.path.join(
                OUT_DIR,
                sid + "_adr.npy"
            ),
            adr_np
        )

print("\n" + "=" * 80)
print("FINAL QUALITY RESULT")
print("=" * 80)

print(
    f"SwinIR PSNR : {np.mean(sw_psnr):.4f} dB"
)

print(
    f"ADR PSNR    : {np.mean(adr_psnr):.4f} dB"
)

print(
    f"PSNR gain   : "
    f"{np.mean(adr_psnr)-np.mean(sw_psnr):+.4f} dB"
)

print()

print(
    f"SwinIR SSIM : {np.mean(sw_ssim):.6f}"
)

print(
    f"ADR SSIM    : {np.mean(adr_ssim):.6f}"
)

print(
    f"SSIM gain   : "
    f"{np.mean(adr_ssim)-np.mean(sw_ssim):+.6f}"
)

print("\nSaved results:", OUT_DIR)

print("=" * 80)

