import os
import glob
import numpy as np

RESULT_DIR = "/content/drive/MyDrive/SwinIR_Project/final_20_validation_results"

files = sorted(
    glob.glob(
        os.path.join(
            RESULT_DIR,
            "*_swinir.npy"
        )
    )
)

print("=" * 80)
print("ADR EFFECT DIAGNOSTIC")
print("=" * 80)

diff_means = []
diff_stds = []
diff_max = []

for f in files:

    sid = os.path.basename(f).split("_")[0]

    adr_file = os.path.join(
        RESULT_DIR,
        sid + "_adr.npy"
    )

    if not os.path.exists(adr_file):
        continue

    swin = np.load(f).astype(np.float32)
    adr = np.load(adr_file).astype(np.float32)

    diff = adr - swin

    diff_means.append(
        np.mean(np.abs(diff))
    )

    diff_stds.append(
        np.std(diff)
    )

    diff_max.append(
        np.max(np.abs(diff))
    )

print("Images analysed:", len(diff_means))

print(
    "\nMean absolute refinement:",
    np.mean(diff_means)
)

print(
    "Mean refinement std:",
    np.mean(diff_stds)
)

print(
    "Maximum refinement:",
    np.max(diff_max)
)

print(
    "Largest per-image mean change:",
    np.max(diff_means)
)

print("=" * 80)

# ============================================================
# FIND OPTIMAL ADR STRENGTH
# ZERO TRAINING / ZERO GPU
# ============================================================

import os
import glob
import numpy as np
from skimage.metrics import structural_similarity

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

RESULT_DIR = os.path.join(
    PROJECT,
    "final_20_validation_results"
)

GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

# Test different refinement strengths
alphas = [
    0.0,
    0.25,
    0.50,
    0.75,
    1.0,
    1.25
]

print("=" * 80)
print("OPTIMIZING ADR STRENGTH — NO TRAINING")
print("=" * 80)

# ------------------------------------------------------------
# Collect samples
# ------------------------------------------------------------

swin_files = sorted(
    glob.glob(
        os.path.join(
            RESULT_DIR,
            "*_swinir.npy"
        )
    )
)

dataset = []

for swin_file in swin_files:

    sid = os.path.basename(
        swin_file
    ).split("_")[0]

    adr_file = os.path.join(
        RESULT_DIR,
        sid + "_adr.npy"
    )

    gt_file = os.path.join(
        GT_DIR,
        sid + ".npy"
    )

    if not (
        os.path.exists(adr_file)
        and os.path.exists(gt_file)
    ):
        continue

    swin = np.load(
        swin_file
    ).astype(np.float32)

    adr = np.load(
        adr_file
    ).astype(np.float32)

    gt = np.load(
        gt_file
    ).astype(np.float32)

    swin = np.squeeze(swin)
    adr = np.squeeze(adr)
    gt = np.squeeze(gt)

    if swin.shape != gt.shape:
        continue

    dataset.append(
        (sid, swin, adr, gt)
    )

print("Samples:", len(dataset))

# ------------------------------------------------------------
# Evaluate each alpha
# ------------------------------------------------------------

results = []

for alpha in alphas:

    psnr_values = []
    ssim_values = []

    for sid, swin, adr, gt in dataset:

        # ADR correction
        correction = adr - swin

        # Gated refinement
        output = swin + alpha * correction

        output = np.nan_to_num(
            output,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        output = np.clip(
            output,
            0.0,
            1.0
        )

        mse = np.mean(
            (output - gt) ** 2
        )

        psnr = 10 * np.log10(
            1.0 / max(mse, 1e-12)
        )

        ssim = structural_similarity(
            gt,
            output,
            data_range=1.0
        )

        psnr_values.append(psnr)
        ssim_values.append(ssim)

    results.append(
        (
            alpha,
            np.mean(psnr_values),
            np.mean(ssim_values)
        )
    )

# ------------------------------------------------------------
# Display
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("ADR STRENGTH RESULTS")
print("=" * 80)

print(
    f"{'Alpha':>8} "
    f"{'PSNR':>12} "
    f"{'SSIM':>12}"
)

for alpha, p, s in results:

    print(
        f"{alpha:>8.2f} "
        f"{p:>12.4f} "
        f"{s:>12.6f}"
    )

# ------------------------------------------------------------
# Find best
# ------------------------------------------------------------

best_psnr = max(
    results,
    key=lambda x: x[1]
)

best_ssim = max(
    results,
    key=lambda x: x[2]
)

print("\n" + "=" * 80)

print(
    f"BEST PSNR alpha : {best_psnr[0]}"
)

print(
    f"BEST PSNR        : {best_psnr[1]:.4f} dB"
)

print(
    f"BEST SSIM alpha  : {best_ssim[0]}"
)

print(
    f"BEST SSIM        : {best_ssim[1]:.6f}"
)

print("=" * 80)

