import os
import glob
import numpy as np
from scipy.ndimage import gaussian_filter
from skimage.metrics import structural_similarity

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

RESULT_DIR = os.path.join(
    PROJECT,
    "final_20_validation_results"
)

GT_DIR = (
    "/content/drive/MyDrive/"
    "SwinIR_Data_Complete/train/GT"
)

ALPHA = 0.25

files = sorted(
    glob.glob(
        os.path.join(
            RESULT_DIR,
            "*_swinir.npy"
        )
    )
)

print("=" * 80)
print("STRUCTURE-AWARE ADR GATING")
print("NO GPU / NO TRAINING")
print("=" * 80)

dataset = []

for f in files:

    sid = os.path.basename(f).split("_")[0]

    adr_file = os.path.join(
        RESULT_DIR,
        sid + "_adr.npy"
    )

    gt_file = os.path.join(
        GT_DIR,
        sid + ".npy"
    )

    if not (
        os.path.exists(adr_file)
        and os.path.exists(gt_file)
    ):
        continue

    swin = np.load(f).astype(np.float32)
    adr = np.load(adr_file).astype(np.float32)
    gt = np.load(gt_file).astype(np.float32)

    swin = np.squeeze(swin)
    adr = np.squeeze(adr)
    gt = np.squeeze(gt)

    if swin.shape != gt.shape:
        continue

    dataset.append(
        (sid, swin, adr, gt)
    )

print("Samples:", len(dataset))


def evaluate(output, gt):

    output = np.nan_to_num(
        output,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    output = np.clip(
        output,
        0.0,
        1.0
    )

    mse = np.mean(
        (output - gt) ** 2
    )

    psnr = 10 * np.log10(
        1.0 / max(mse, 1e-12)
    )

    ssim = structural_similarity(
        gt,
        output,
        data_range=1.0
    )

    return psnr, ssim


# ------------------------------------------------------------
# Different gate strengths
# ------------------------------------------------------------

gate_strengths = [
    0.25,
    0.50,
    0.75,
    1.00
]

results = []

for gate_strength in gate_strengths:

    psnr_values = []
    ssim_values = []

    for sid, swin, adr, gt in dataset:

        correction = adr - swin

        # Local detail strength
        smooth = gaussian_filter(
            swin,
            sigma=1.0
        )

        detail = np.abs(
            swin - smooth
        )

        # Normalize detail map
        dmin = detail.min()
        dmax = detail.max()

        if dmax > dmin:

            detail_norm = (
                detail - dmin
            ) / (
                dmax - dmin + 1e-8
            )

        else:

            detail_norm = np.zeros_like(
                detail
            )

        # Adaptive gate
        gate = (
            1.0
            + gate_strength * detail_norm
        )

        # Keep gate bounded
        gate = np.clip(
            gate,
            0.5,
            1.0 + gate_strength
        )

        output = (
            swin
            + ALPHA * gate * correction
        )

        p, s = evaluate(
            output,
            gt
        )

        psnr_values.append(p)
        ssim_values.append(s)

    results.append(
        (
            gate_strength,
            np.mean(psnr_values),
            np.mean(ssim_values)
        )
    )


print("\n" + "=" * 80)
print("STRUCTURE-AWARE GATING RESULTS")
print("=" * 80)

print(
    f"{'Gate':>10}"
    f"{'PSNR':>14}"
    f"{'SSIM':>14}"
)

for g, p, s in results:

    print(
        f"{g:>10.2f}"
        f"{p:>14.4f}"
        f"{s:>14.6f}"
    )

best_balanced = max(
    results,
    key=lambda x: (
        x[1] - 28.2839
    ) + (
        x[2] - 0.771952
    ) * 100
)

print("\n" + "=" * 80)
print(
    "BEST BALANCED CANDIDATE:",
    best_balanced
)
print("=" * 80)

