# ============================================================
# FINAL 400-IMAGE SWINIR vs ADR vs SA-ADR
# CPU ONLY — NO TRAINING — USE EXISTING OUTPUTS
# ============================================================

import os
import glob
import numpy as np
from scipy.ndimage import gaussian_filter
from skimage.metrics import structural_similarity

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SWIN_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir"
)

ADR_DIR = os.path.join(
    PROJECT,
    "final_adaptive_results"
)

GT_DIR = (
    "/content/drive/MyDrive/"
    "SwinIR_Data_Complete/train/GT"
)

SAADR_DIR = os.path.join(
    PROJECT,
    "final_saadr_results"
)

os.makedirs(SAADR_DIR, exist_ok=True)

# Final candidate selected from the 20-image experiment
ALPHA = 0.25
GATE_STRENGTH = 1.0

print("=" * 80)
print("FINAL 400-IMAGE BENCHMARK")
print("SWINIR vs ADR vs STRUCTURE-AWARE ADR")
print("=" * 80)

swin_files = sorted(
    glob.glob(
        os.path.join(SWIN_DIR, "*_swinir.npy")
    )
)

print("SwinIR files:", len(swin_files))

results = []
missing = []

for i, swin_file in enumerate(swin_files):

    filename = os.path.basename(swin_file)

    # 000123_swinir.npy -> 000123
    sid = filename.replace(
        "_swinir.npy",
        ""
    )

    adr_file = os.path.join(
        ADR_DIR,
        sid + "_final.npy"
    )

    gt_file = os.path.join(
        GT_DIR,
        sid + ".npy"
    )

    if not os.path.exists(adr_file):
        missing.append(
            (sid, "ADR")
        )
        continue

    if not os.path.exists(gt_file):
        missing.append(
            (sid, "GT")
        )
        continue

    # --------------------------------------------------------
    # Load
    # --------------------------------------------------------

    swin = np.squeeze(
        np.load(swin_file)
    ).astype(np.float32)

    adr = np.squeeze(
        np.load(adr_file)
    ).astype(np.float32)

    gt = np.squeeze(
        np.load(gt_file)
    ).astype(np.float32)

    # --------------------------------------------------------
    # Shape check
    # --------------------------------------------------------

    if (
        swin.shape != gt.shape
        or adr.shape != gt.shape
    ):
        missing.append(
            (
                sid,
                f"shape mismatch "
                f"Swin={swin.shape}, "
                f"ADR={adr.shape}, "
                f"GT={gt.shape}"
            )
        )
        continue

    # --------------------------------------------------------
    # ADR correction
    # --------------------------------------------------------

    correction = adr - swin

    # --------------------------------------------------------
    # Structure/detail map
    # --------------------------------------------------------

    smooth = gaussian_filter(
        swin,
        sigma=1.0
    )

    detail = np.abs(
        swin - smooth
    )

    dmin = detail.min()
    dmax = detail.max()

    if dmax > dmin:

        detail_norm = (
            detail - dmin
        ) / (
            dmax - dmin + 1e-8
        )

    else:

        detail_norm = np.zeros_like(
            detail
        )

    # --------------------------------------------------------
    # Adaptive gate
    # --------------------------------------------------------

    gate = (
        1.0
        + GATE_STRENGTH * detail_norm
    )

    gate = np.clip(
        gate,
        0.5,
        1.0 + GATE_STRENGTH
    )

    # --------------------------------------------------------
    # SA-ADR output
    # --------------------------------------------------------

    saadr = (
        swin
        + ALPHA * gate * correction
    )

    saadr = np.nan_to_num(
        saadr,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    saadr = np.clip(
        saadr,
        0.0,
        1.0
    ).astype(np.float32)

    # --------------------------------------------------------
    # Save SA-ADR
    # --------------------------------------------------------

    np.save(
        os.path.join(
            SAADR_DIR,
            sid + "_saadr.npy"
        ),
        saadr
    )

    # --------------------------------------------------------
    # PSNR
    # --------------------------------------------------------

    def calculate_psnr(pred, target):

        mse = np.mean(
            (pred - target) ** 2
        )

        return 10.0 * np.log10(
            1.0 / max(mse, 1e-12)
        )

    psnr_swin = calculate_psnr(
        swin,
        gt
    )

    psnr_adr = calculate_psnr(
        adr,
        gt
    )

    psnr_saadr = calculate_psnr(
        saadr,
        gt
    )

    # --------------------------------------------------------
    # SSIM
    # --------------------------------------------------------

    ssim_swin = structural_similarity(
        gt,
        swin,
        data_range=1.0
    )

    ssim_adr = structural_similarity(
        gt,
        adr,
        data_range=1.0
    )

    ssim_saadr = structural_similarity(
        gt,
        saadr,
        data_range=1.0
    )

    results.append(
        (
            sid,
            psnr_swin,
            psnr_adr,
            psnr_saadr,
            ssim_swin,
            ssim_adr,
            ssim_saadr
        )
    )

    if (i + 1) % 50 == 0:
        print(
            f"Processed: {i + 1}/{len(swin_files)}"
        )


# ============================================================
# FINAL SUMMARY
# ============================================================

print("\n" + "=" * 80)
print("FINAL 400-IMAGE RESULTS")
print("=" * 80)

print(
    "Evaluated:",
    len(results)
)

print(
    "Missing:",
    len(missing)
)

if missing:
    print("\nFirst missing entries:")
    for item in missing[:20]:
        print(item)


if len(results) > 0:

    arr = np.asarray(
        [r[1:] for r in results],
        dtype=np.float64
    )

    # --------------------------------------------------------
    # PSNR
    # --------------------------------------------------------

    swin_psnr = arr[:, 0].mean()
    adr_psnr = arr[:, 1].mean()
    saadr_psnr = arr[:, 2].mean()

    # --------------------------------------------------------
    # SSIM
    # --------------------------------------------------------

    swin_ssim = arr[:, 3].mean()
    adr_ssim = arr[:, 4].mean()
    saadr_ssim = arr[:, 5].mean()

    print("\n" + "-" * 80)
    print("PSNR")
    print("-" * 80)

    print(
        f"SwinIR  : {swin_psnr:.4f} dB"
    )

    print(
        f"ADR     : {adr_psnr:.4f} dB"
    )

    print(
        f"SA-ADR  : {saadr_psnr:.4f} dB"
    )

    print("\n" + "-" * 80)
    print("SSIM")
    print("-" * 80)

    print(
        f"SwinIR  : {swin_ssim:.6f}"
    )

    print(
        f"ADR     : {adr_ssim:.6f}"
    )

    print(
        f"SA-ADR  : {saadr_ssim:.6f}"
    )

    print("\n" + "-" * 80)
    print("IMPROVEMENT OVER SWINIR")
    print("-" * 80)

    print(
        f"ADR PSNR improvement   : "
        f"{adr_psnr - swin_psnr:+.4f} dB"
    )

    print(
        f"SA-ADR PSNR improvement: "
        f"{saadr_psnr - swin_psnr:+.4f} dB"
    )

    print(
        f"ADR SSIM improvement   : "
        f"{adr_ssim - swin_ssim:+.6f}"
    )

    print(
        f"SA-ADR SSIM improvement: "
        f"{saadr_ssim - swin_ssim:+.6f}"
    )

    # --------------------------------------------------------
    # Win counts
    # --------------------------------------------------------

    adr_psnr_wins = np.sum(
        arr[:, 1] > arr[:, 0]
    )

    saadr_psnr_wins = np.sum(
        arr[:, 2] > arr[:, 0]
    )

    adr_ssim_wins = np.sum(
        arr[:, 4] > arr[:, 3]
    )

    saadr_ssim_wins = np.sum(
        arr[:, 5] > arr[:, 3]
    )

    print("\n" + "-" * 80)
    print("PER-IMAGE WINS")
    print("-" * 80)

    print(
        f"ADR PSNR better : "
        f"{adr_psnr_wins}/{len(results)}"
    )

    print(
        f"SA-ADR PSNR better : "
        f"{saadr_psnr_wins}/{len(results)}"
    )

    print(
        f"ADR SSIM better : "
        f"{adr_ssim_wins}/{len(results)}"
    )

    print(
        f"SA-ADR SSIM better : "
        f"{saadr_ssim_wins}/{len(results)}"
    )

print("\nSA-ADR outputs saved at:")
print(SAADR_DIR)

print("=" * 80)
print("400-IMAGE BENCHMARK COMPLETE")
print("=" * 80)

