import os
import json

SEARCH_ROOT = "/content/drive/MyDrive"

targets = [
    "results_epoch20_swinir",
    "final_saadr_results",
    "ADR",
    "SA-ADR",
    "400-IMAGE",
    "benchmark"
]

print("=" * 80)
print("SEARCHING ALL NOTEBOOKS FOR BENCHMARK GENERATION CODE")
print("=" * 80)

found = 0

for root, dirs, files in os.walk(SEARCH_ROOT):

    dirs[:] = [
        d for d in dirs
        if d not in [".git", "__pycache__"]
    ]

    for filename in files:

        if not filename.endswith(".ipynb"):
            continue

        path = os.path.join(root, filename)

        try:
            with open(path, "r", encoding="utf-8") as f:
                nb = json.load(f)
        except Exception:
            continue

        for cell_no, cell in enumerate(nb.get("cells", [])):

            source = "".join(cell.get("source", []))

            matched = [
                t for t in targets
                if t.lower() in source.lower()
            ]

            if matched:

                found += 1

                print("\n" + "=" * 80)
                print("MATCH FOUND")
                print("=" * 80)

                print("Notebook :", path)
                print("Cell     :", cell_no)
                print("Keywords :", matched)

                print("\n--- CELL CONTENT ---\n")
                print(source[:15000])

print("\n" + "=" * 80)
print("SEARCH COMPLETE")
print("=" * 80)
print("Matching cells:", found)

