import os
import json

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_FILE = os.path.join(PROJECT, "train_val_split.json")

SWINIR_DIR = os.path.join(PROJECT, "results_epoch20_swinir")
SAADR_DIR  = os.path.join(PROJECT, "final_saadr_results")

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [str(x).zfill(6) for x in split["val"]]

swinir_files = {
    f[:6]
    for f in os.listdir(SWINIR_DIR)
    if f.endswith("_swinir.npy")
}

