print("SAADR outputs  :", len(saadr_files))

valid_swinir = sorted(set(val_ids) & swinir_files)
valid_saadr  = sorted(set(val_ids) & saadr_files)

missing_swinir = sorted(set(val_ids) - swinir_files)
missing_saadr  = sorted(set(val_ids) - saadr_files)

print()
print("Validation + SwinIR :", len(valid_swinir))
print("Validation + SAADR  :", len(valid_saadr))

