import os
import json
import numpy as np
import torch
from tqdm.auto import tqdm

# ============================================================
# PATHS
# ============================================================

BASE = "/content/drive/MyDrive/SwinIR_Data_Complete/train"

GT_DIR = os.path.join(BASE, "GT")
NOISY_DIR = os.path.join(BASE, "NoisyLR")

CHECKPOINT = "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth"

OUTPUT_DIR = "/content/drive/MyDrive/SwinIR_Project/results_epoch20_swinir"

SPLIT_FILE = "/content/drive/MyDrive/SwinIR_Project/train_val_split.json"

os.makedirs(OUTPUT_DIR, exist_ok=True)

# ============================================================
# LOAD VALIDATION IDS
# ============================================================

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = []

for x in split["val"]:
    x = str(x)

    # Handle possible .npy extension
    if x.endswith(".npy"):
        x = x[:-4]

    # Handle possible paths
    x = os.path.basename(x)
    if x.endswith(".npy"):
        x = x[:-4]

    val_ids.append(x)

val_ids = list(dict.fromkeys(val_ids))

print("="*70)
print("FINAL VALIDATION GENERATION")
print("="*70)

print("Validation IDs:", len(val_ids))
print("GT directory  :", GT_DIR)
print("Noisy directory:", NOISY_DIR)
print("Checkpoint    :", CHECKPOINT)
print("Output        :", OUTPUT_DIR)

# ============================================================
# CHECK DATASET
# ============================================================

gt_ids = {
    os.path.splitext(os.path.basename(x))[0]
    for x in os.listdir(GT_DIR)
    if x.endswith(".npy") and not x.startswith("._")
}

noisy_ids = {
    os.path.splitext(os.path.basename(x))[0]
    for x in os.listdir(NOISY_DIR)
    if x.endswith(".npy") and not x.startswith("._")
}

print("\nGT IDs     :", len(gt_ids))
print("NoisyLR IDs:", len(noisy_ids))

missing_input = [
    x for x in val_ids
    if x not in noisy_ids
]

print("Missing validation inputs:", len(missing_input))

if missing_input:
    print("First missing:", missing_input[:20])
    raise RuntimeError("Some validation NoisyLR files are missing.")

# ============================================================
# EXISTING OUTPUTS
# ============================================================

existing_ids = {
    os.path.splitext(os.path.basename(x))[0]
    for x in os.listdir(OUTPUT_DIR)
    if x.endswith(".npy")
}

missing_ids = [
    x for x in val_ids
    if x not in existing_ids
]

print("\nExisting validation outputs:",
      len(set(val_ids) & existing_ids))

print("Missing validation outputs :", len(missing_ids))

# ============================================================
# GENERATION
# ============================================================

if len(missing_ids) == 0:
    print("\n✅ ALL 320 VALIDATION OUTPUTS ALREADY EXIST.")
else:

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    print("\nDevice:", device)

    # --------------------------------------------------------
    # IMPORTANT:
    # Use the EXACT model architecture that successfully
    # loaded Epoch-20 earlier.
    # --------------------------------------------------------

    # model should already exist from your successful loading cell.
    # Check that it is available.

    if "model" not in globals():
        raise RuntimeError(
            "❌ 'model' is not available. "
            "Run the previous SUCCESSFUL Epoch-20 model-loading cell first."
        )

    model = model.to(device)
    model.eval()

    print("Model ready.")
    print("Generating:", len(missing_ids))

    generated = 0
    failed = []

    with torch.no_grad():

        for image_id in tqdm(
            missing_ids,
            desc="Generating validation outputs"
        ):

            input_path = os.path.join(
                NOISY_DIR,
                image_id + ".npy"
            )

            output_path = os.path.join(
                OUTPUT_DIR,
                image_id + "_swinir.npy"
            )

            try:

                arr = np.load(input_path).astype(np.float32)

                # ------------------------------------------------
                # Convert input to tensor
                # ------------------------------------------------

                if arr.ndim == 2:

                    tensor = torch.from_numpy(arr).unsqueeze(0).unsqueeze(0)

                elif arr.ndim == 3:

                    # Handle CHW or HWC
                    if arr.shape[0] == 1:
                        tensor = torch.from_numpy(arr).unsqueeze(0)

                    elif arr.shape[-1] == 1:
                        tensor = torch.from_numpy(
                            arr.transpose(2, 0, 1)
                        ).unsqueeze(0)

                    else:
                        raise ValueError(
                            f"Unexpected shape {arr.shape}"
                        )

                else:
                    raise ValueError(
                        f"Unexpected input ndim: {arr.ndim}"
                    )

                tensor = tensor.to(device)

                # ------------------------------------------------
                # Normalize if necessary
                # ------------------------------------------------

                if tensor.max() > 1.0:
                    tensor = tensor / 255.0

                # ------------------------------------------------
                # Inference
                # ------------------------------------------------

                output = model(tensor)

                output = output.detach().cpu().numpy()

                # Remove batch/channel dimensions
                output = np.squeeze(output)

                # Save
                np.save(output_path, output)

                generated += 1

            except Exception as e:

                failed.append((image_id, str(e)))

    print("\n" + "="*70)
    print("VALIDATION GENERATION FINISHED")
    print("="*70)

    print("Generated:", generated)
    print("Failed   :", len(failed))

    if failed:
        print("\nFirst failures:")
        for item in failed[:20]:
            print(item)

# ============================================================
# FINAL CHECK
# ============================================================

final_outputs = {
    os.path.splitext(os.path.basename(x))[0]
    .replace("_swinir", "")
    for x in os.listdir(OUTPUT_DIR)
    if x.endswith(".npy")
}

matched = set(val_ids) & final_outputs

print("\n" + "="*70)
print("FINAL VALIDATION OUTPUT CHECK")
print("="*70)

print("Validation IDs :", len(val_ids))
print("SwinIR outputs :", len(final_outputs))
print("Matched        :", len(matched))
print("Still missing  :", len(set(val_ids) - final_outputs))

if len(matched) == len(val_ids):
    print("\n🎉 SUCCESS — ALL 320 VALIDATION SWINIR OUTPUTS EXIST!")
else:
    print("\n⚠️ Still missing:")
    print(sorted(set(val_ids) - final_outputs)[:50])

