# ============================================================
# FINAL BENCHMARK DATA PREPARATION
# ============================================================

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_FILE = os.path.join(PROJECT, "train_val_split.json")

GT_DIR = "/content/drive/MyDrive/SwinIR_Data_Complete/train/GT"

SWINIR_DIR = os.path.join(
    PROJECT, "results_epoch20_swinir"
)

SAADR_DIR = os.path.join(
    PROJECT, "final_saadr_results"
)

print("=" * 70)
print("FINAL BENCHMARK DATA PREPARATION")
print("=" * 70)

# ------------------------------------------------------------
# Load validation IDs
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [str(x).replace(".npy", "") for x in split["val"]]

print("Validation IDs:", len(val_ids))

# ------------------------------------------------------------
# Normalize IDs to 6 digits
# ------------------------------------------------------------

val_ids = [x.zfill(6) for x in val_ids]

# ------------------------------------------------------------
# Find matching files
# ------------------------------------------------------------

def find_file(directory, sample_id, suffix):
    candidates = [
        os.path.join(directory, f"{sample_id}{suffix}.npy"),
        os.path.join(directory, f"{sample_id}.npy"),
    ]

    for p in candidates:
        if os.path.exists(p):
            return p

    return None


benchmark = []

missing_gt = []
missing_swinir = []
missing_saadr = []

for sample_id in val_ids:

    gt = find_file(GT_DIR, sample_id, "")

    swinir = find_file(SWINIR_DIR, sample_id, "_swinir")

    saadr = find_file(SAADR_DIR, sample_id, "_saadr")

    if gt is None:
        missing_gt.append(sample_id)

    if swinir is None:
        missing_swinir.append(sample_id)

    if saadr is None:
        missing_saadr.append(sample_id)

    if gt and swinir and saadr:
        benchmark.append({
            "id": sample_id,
            "gt": gt,
            "swinir": swinir,
            "saadr": saadr
        })

print()
print("=" * 70)
print("BENCHMARK MATCHING RESULT")
print("=" * 70)

print("Validation samples :", len(val_ids))
print("Complete triplets   :", len(benchmark))
print("Missing GT          :", len(missing_gt))
print("Missing SwinIR      :", len(missing_swinir))
print("Missing SA-ADR      :", len(missing_saadr))

if missing_gt:
    print("\nMissing GT:")
    print(missing_gt[:30])

if missing_swinir:
    print("\nMissing SwinIR:")
    print(missing_swinir[:30])

if missing_saadr:
    print("\nMissing SA-ADR:")
    print(missing_saadr[:30])

# Save benchmark manifest
manifest_path = os.path.join(
    PROJECT, "final_benchmark_manifest.json"
)

with open(manifest_path, "w") as f:
    json.dump(benchmark, f, indent=2)

print()
print("Manifest saved:")
print(manifest_path)

if len(benchmark) == 320:
    print()
    print("🎉 PERFECT — 320/320 BENCHMARK TRIPLETS READY!")
else:
    print()
    print("⚠️ Benchmark is incomplete.")

