def summarize_ids(ids):

    nums = sorted(
        int(x)
        for x in ids
        if str(x).isdigit()
    )

    if not nums:
        return "No numeric IDs"

    return {
        "count": len(nums),
        "min": nums[0],
        "max": nums[-1],
        "first_20": nums[:20],
        "last_20": nums[-20:]
    }

