# FIX — GENERATE ADR FOR EXACT 320 VALIDATION IMAGES
# NO SWINIR TRAINING
# NO ADR TRAINING
# USE EXISTING ADR CHECKPOINT
# ============================================================

import os
import json
import glob
import numpy as np
import torch
from tqdm.auto import tqdm

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_FILE = os.path.join(
    PROJECT,
    "train_val_split.json"
)

SWINIR_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir"
)

ADR_CHECKPOINT = os.path.join(
    PROJECT,
    "innovation_refinement_FINAL.pth"
)

# New folder specifically for the correct validation ADR outputs
ADR_VAL_DIR = os.path.join(
    PROJECT,
    "final_adaptive_validation_results"
)

os.makedirs(ADR_VAL_DIR, exist_ok=True)

print("=" * 80)
print("GENERATING ADR FOR EXACT 320 VALIDATION IMAGES")
print("=" * 80)

# ------------------------------------------------------------
# DEVICE
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("Device:", device)

# ------------------------------------------------------------
# CHECK FILES
# ------------------------------------------------------------

assert os.path.exists(SPLIT_FILE), \
    "Validation split not found"

assert os.path.exists(ADR_CHECKPOINT), \
    f"ADR checkpoint not found: {ADR_CHECKPOINT}"

assert os.path.isdir(SWINIR_DIR), \
    "SwinIR output directory not found"

print("ADR checkpoint:", ADR_CHECKPOINT)
print("SwinIR directory:", SWINIR_DIR)
print("Output directory:", ADR_VAL_DIR)

# ------------------------------------------------------------
# LOAD VALIDATION IDs
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [
    str(x).replace(".npy", "").zfill(6)
    for x in split["val"]
]

print("\nValidation IDs:", len(val_ids))

assert len(val_ids) == 320, \
    f"Expected 320 validation IDs, got {len(val_ids)}"

# ------------------------------------------------------------
# CHECK ADR CLASS
# ------------------------------------------------------------

print("\nChecking AdaptiveDetailRefinement class...")

if "AdaptiveDetailRefinement" not in globals():

    raise RuntimeError(
        "\nAdaptiveDetailRefinement class is NOT loaded.\n"
        "Do not continue yet.\n"
        "We need to load the class definition from the notebook."
    )

print("✅ AdaptiveDetailRefinement class found")

# ------------------------------------------------------------
# CREATE ADR MODEL
# ------------------------------------------------------------

adr_model = AdaptiveDetailRefinement().to(device)

parameter_count = sum(
    p.numel()
    for p in adr_model.parameters()
)

print("ADR parameters:", parameter_count)

# Expected architecture from your previous code
assert parameter_count == 2626, \
    f"Unexpected ADR parameter count: {parameter_count}"

# ------------------------------------------------------------
# LOAD CHECKPOINT
# ------------------------------------------------------------

checkpoint = torch.load(
    ADR_CHECKPOINT,
    map_location=device,
    weights_only=False
)

if isinstance(checkpoint, dict):

    if "model_state_dict" in checkpoint:
        state_dict = checkpoint["model_state_dict"]

    elif "state_dict" in checkpoint:
        state_dict = checkpoint["state_dict"]

    else:
        state_dict = checkpoint

else:
    state_dict = checkpoint

# Remove DataParallel prefix if present
state_dict = {
    k.replace("module.", "", 1): v
    for k, v in state_dict.items()
}

adr_model.load_state_dict(
    state_dict,
    strict=True
)

adr_model.eval()

print("✅ ADR checkpoint loaded successfully")

# ------------------------------------------------------------
# BUILD SWINIR OUTPUT INDEX
# ------------------------------------------------------------

swinir_files = glob.glob(
    os.path.join(
        SWINIR_DIR,
        "*_swinir.npy"
    )
)

swinir_map = {}

for f in swinir_files:

    filename = os.path.basename(f)

    sid = filename.replace(
        "_swinir.npy",
        ""
    )

    sid = sid.zfill(6)

    swinir_map[sid] = f

print("\nTotal SwinIR outputs:", len(swinir_map))

# ------------------------------------------------------------
# VALIDATION MATCHING
# ------------------------------------------------------------

available_val = [
    sid
    for sid in val_ids
    if sid in swinir_map
]

missing_swinir = [
    sid
    for sid in val_ids
    if sid not in swinir_map
]

print("Validation SwinIR matches:", len(available_val))
print("Missing SwinIR:", len(missing_swinir))

assert len(available_val) == 320, \
    f"Expected 320 SwinIR validation outputs, got {len(available_val)}"

# ------------------------------------------------------------
# CHECK EXISTING ADR
# ------------------------------------------------------------

existing_adr = set()

for f in glob.glob(
    os.path.join(
        ADR_VAL_DIR,
        "*_adr.npy"
    )
):

    sid = os.path.basename(f).replace(
        "_adr.npy",
        ""
    )

    existing_adr.add(
        sid.zfill(6)
    )

print("\nExisting validation ADR outputs:",
      len(existing_adr))

# ------------------------------------------------------------
# GENERATE ONLY MISSING ADR
# ------------------------------------------------------------

to_generate = [
    sid
    for sid in val_ids
    if sid not in existing_adr
]

print("ADR outputs to generate:",
      len(to_generate))

print("\nFirst 20:")
print(to_generate[:20])

# ------------------------------------------------------------
# APPLY ADR
# ------------------------------------------------------------

successful = 0
failed = 0

with torch.no_grad():

    for sid in tqdm(
        to_generate,
        desc="Generating validation ADR"
    ):

        try:

            swinir_path = swinir_map[sid]

            # Load existing SwinIR output
            swinir = np.load(
                swinir_path
            ).astype(np.float32)

            swinir = np.squeeze(swinir)

            # Protect numerical range
            swinir = np.nan_to_num(
                swinir,
                nan=0.0,
                posinf=1.0,
                neginf=0.0
            )

            swinir = np.clip(
                swinir,
                0.0,
                1.0
            )

            # H,W -> 1,1,H,W
            x = torch.from_numpy(
                swinir
            ).unsqueeze(0).unsqueeze(0)

            x = x.to(
                device,
                dtype=torch.float32
            )

            # ADR
            refined = adr_model(x)

            refined = torch.clamp(
                refined,
                0.0,
                1.0
            )

            refined = (
                refined[0, 0]
                .detach()
                .cpu()
                .numpy()
                .astype(np.float32)
            )

            # Save
            output_path = os.path.join(
                ADR_VAL_DIR,
                sid + "_adr.npy"
            )

            np.save(
                output_path,
                refined
            )

            successful += 1

        except Exception as e:

            failed += 1

            print(
                f"\n❌ Failed {sid}: {e}"
            )

print("\n" + "=" * 80)
print("ADR VALIDATION GENERATION COMPLETE")
print("=" * 80)

print("Successful:", successful)
print("Failed:", failed)

# ------------------------------------------------------------
# FINAL COUNT
# ------------------------------------------------------------

final_adr_files = glob.glob(
    os.path.join(
        ADR_VAL_DIR,
        "*_adr.npy"
    )
)

print("\nADR validation files:",
      len(final_adr_files))

print("Saved at:")
print(ADR_VAL_DIR)

print("=" * 80)

