# STEP NEXT — GENERATE SA-ADR FOR EXACT 320 VALIDATION IMAGES
# ============================================================

import os
import json
import numpy as np
from scipy.ndimage import gaussian_filter
from tqdm.auto import tqdm

# ------------------------------------------------------------
# PATHS
# ------------------------------------------------------------

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_FILE = os.path.join(
    PROJECT,
    "train_val_split.json"
)

SWINIR_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir"
)

ADR_DIR = os.path.join(
    PROJECT,
    "final_adaptive_validation_results"
)

SAADR_DIR = os.path.join(
    PROJECT,
    "final_saadr_validation_results"
)

os.makedirs(SAADR_DIR, exist_ok=True)

print("=" * 80)
print("GENERATING SA-ADR FOR EXACT 320 VALIDATION IMAGES")
print("=" * 80)

# ------------------------------------------------------------
# LOAD VALIDATION IDs
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [
    str(x).replace(".npy", "").zfill(6)
    for x in split["val"]
]

print("Validation IDs:", len(val_ids))

assert len(val_ids) == 320

# ------------------------------------------------------------
# SA-ADR PARAMETERS
# ------------------------------------------------------------

ALPHA = 0.25
GATE_STRENGTH = 1.0

print("\nSA-ADR parameters:")
print("ALPHA         :", ALPHA)
print("GATE_STRENGTH :", GATE_STRENGTH)

# ------------------------------------------------------------
# CHECK INPUT FILES
# ------------------------------------------------------------

missing_swinir = []
missing_adr = []

for sid in val_ids:

    swin_path = os.path.join(
        SWINIR_DIR,
        sid + "_swinir.npy"
    )

    adr_path = os.path.join(
        ADR_DIR,
        sid + "_adr.npy"
    )

    # Accept alternate ADR naming if needed
    if not os.path.exists(adr_path):

        alternate = os.path.join(
            ADR_DIR,
            sid + "_final.npy"
        )

        if os.path.exists(alternate):
            adr_path = alternate

    if not os.path.exists(swin_path):
        missing_swinir.append(sid)

    if not os.path.exists(adr_path):
        missing_adr.append(sid)

print("\nMissing SwinIR:", len(missing_swinir))
print("Missing ADR   :", len(missing_adr))

assert len(missing_swinir) == 0
assert len(missing_adr) == 0

print("✅ All 320 SwinIR + ADR inputs available")

# ------------------------------------------------------------
# GENERATE SA-ADR
# ------------------------------------------------------------

successful = 0
failed = 0

for sid in tqdm(
    val_ids,
    desc="Generating SA-ADR"
):

    try:

        swin_path = os.path.join(
            SWINIR_DIR,
            sid + "_swinir.npy"
        )

        adr_path = os.path.join(
            ADR_DIR,
            sid + "_adr.npy"
        )

        if not os.path.exists(adr_path):

            adr_path = os.path.join(
                ADR_DIR,
                sid + "_final.npy"
            )

        # ----------------------------------------------------
        # LOAD
        # ----------------------------------------------------

        swin = np.load(
            swin_path
        ).astype(np.float32)

        adr = np.load(
            adr_path
        ).astype(np.float32)

        swin = np.squeeze(swin)
        adr = np.squeeze(adr)

        # ----------------------------------------------------
        # VALIDATE SHAPE
        # ----------------------------------------------------

        if swin.shape != adr.shape:

            raise ValueError(
                f"Shape mismatch: "
                f"SwinIR={swin.shape}, "
                f"ADR={adr.shape}"
            )

        # ----------------------------------------------------
        # RANGE
        # ----------------------------------------------------

        swin = np.nan_to_num(
            swin,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        adr = np.nan_to_num(
            adr,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        swin = np.clip(
            swin,
            0.0,
            1.0
        )

        adr = np.clip(
            adr,
            0.0,
            1.0
        )

        # ----------------------------------------------------
        # ADR CORRECTION
        # ----------------------------------------------------

        correction = adr - swin

        # ----------------------------------------------------
        # STRUCTURE / DETAIL MAP
        # ----------------------------------------------------

        smooth = gaussian_filter(
            swin,
            sigma=1.0
        )

        detail = np.abs(
            swin - smooth
        )

        dmin = detail.min()
        dmax = detail.max()

        if dmax > dmin:

            detail_norm = (
                detail - dmin
            ) / (
                dmax - dmin + 1e-8
            )

        else:

            detail_norm = np.zeros_like(
                detail
            )

        # ----------------------------------------------------
        # ADAPTIVE STRUCTURE GATE
        # ----------------------------------------------------

        gate = (
            1.0
            + GATE_STRENGTH * detail_norm
        )

        gate = np.clip(
            gate,
            0.5,
            1.0 + GATE_STRENGTH
        )

        # ----------------------------------------------------
        # SA-ADR
        # ----------------------------------------------------

        saadr = (
            swin
            + ALPHA
            * gate
            * correction
        )

        saadr = np.nan_to_num(
            saadr,
            nan=0.0,
            posinf=1.0,
            neginf=0.0
        )

        saadr = np.clip(
            saadr,
            0.0,
            1.0
        ).astype(np.float32)

        # ----------------------------------------------------
        # SAVE
        # ----------------------------------------------------

        np.save(
            os.path.join(
                SAADR_DIR,
                sid + "_saadr.npy"
            ),
            saadr
        )

        successful += 1

    except Exception as e:

        failed += 1

        print(
            f"\n❌ Failed {sid}: {e}"
        )

print("\n" + "=" * 80)
print("SA-ADR GENERATION COMPLETE")
print("=" * 80)

print("Successful:", successful)
print("Failed    :", failed)

files = [
    f for f in os.listdir(SAADR_DIR)
    if f.endswith("_saadr.npy")
]

print("SA-ADR files:", len(files))

print("\nSaved at:")
print(SAADR_DIR)

assert successful == 320
assert failed == 0
assert len(files) == 320

print("\n🎉 PERFECT — 320/320 SA-ADR OUTPUTS GENERATED")
print("=" * 80)

