import os
import json
import numpy as np
from skimage.metrics import structural_similarity
from tqdm.auto import tqdm

PROJECT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_FILE = os.path.join(
    PROJECT, "train_val_split.json"
)

GT_DIR = (
    "/content/drive/MyDrive/"
    "SwinIR_Data_Complete/train/GT"
)

SWINIR_DIR = os.path.join(
    PROJECT,
    "results_epoch20_swinir"
)

ADR_DIR = os.path.join(
    PROJECT,
    "final_adaptive_validation_results"
)

SAADR_DIR = os.path.join(
    PROJECT,
    "final_saadr_validation_results"
)

OUTPUT_JSON = os.path.join(
    PROJECT,
    "final_320_swinir_adr_saadr_benchmark.json"
)

print("=" * 80)
print("FINAL 320-IMAGE BENCHMARK")
print("SWINIR vs SWINIR + ADR vs SA-ADR")
print("=" * 80)

# ------------------------------------------------------------
# LOAD VALIDATION IDS
# ------------------------------------------------------------

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

val_ids = [
    str(x).replace(".npy", "").zfill(6)
    for x in split["val"]
]

print("Validation IDs:", len(val_ids))

assert len(val_ids) == 320

# ------------------------------------------------------------
# METRICS
# ------------------------------------------------------------

def calculate_psnr(pred, gt):

    pred = np.nan_to_num(
        pred,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    gt = np.nan_to_num(
        gt,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    pred = np.clip(pred, 0.0, 1.0)
    gt = np.clip(gt, 0.0, 1.0)

    mse = np.mean(
        (pred - gt) ** 2
    )

    return 10.0 * np.log10(
        1.0 / max(mse, 1e-12)
    )


def calculate_ssim(pred, gt):

    pred = np.nan_to_num(
        pred,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    gt = np.nan_to_num(
        gt,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    pred = np.clip(
        pred,
        0.0,
        1.0
    ).astype(np.float32)

    gt = np.clip(
        gt,
        0.0,
        1.0
    ).astype(np.float32)

    return structural_similarity(
        gt,
        pred,
        data_range=1.0
    )

# ------------------------------------------------------------
# CHECK ALL FILES
# ------------------------------------------------------------

missing = []

for sid in val_ids:

    paths = [
        os.path.join(
            GT_DIR,
            sid + ".npy"
        ),

        os.path.join(
            SWINIR_DIR,
            sid + "_swinir.npy"
        ),

        os.path.join(
            ADR_DIR,
            sid + "_adr.npy"
        ),

        os.path.join(
            SAADR_DIR,
            sid + "_saadr.npy"
        )
    ]

    for p in paths:

        if not os.path.exists(p):

            missing.append(
                (sid, p)
            )

print("\nMissing files:", len(missing))

if missing:
    print("\nFirst missing:")
    for x in missing[:20]:
        print(x)

assert len(missing) == 0

print("✅ All 320 × 4 files available")

# ------------------------------------------------------------
# ARRAYS
# ------------------------------------------------------------

swin_psnr = []
adr_psnr = []
saadr_psnr = []

swin_ssim = []
adr_ssim = []
saadr_ssim = []

results = []

# ------------------------------------------------------------
# BENCHMARK
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("PROCESSING 320 VALIDATION IMAGES")
print("=" * 80)

for sid in tqdm(
    val_ids,
    desc="Final benchmark"
):

    gt = np.squeeze(
        np.load(
            os.path.join(
                GT_DIR,
                sid + ".npy"
            )
        )
    ).astype(np.float32)

    swin = np.squeeze(
        np.load(
            os.path.join(
                SWINIR_DIR,
                sid + "_swinir.npy"
            )
        )
    ).astype(np.float32)

    adr = np.squeeze(
        np.load(
            os.path.join(
                ADR_DIR,
                sid + "_adr.npy"
            )
        )
    ).astype(np.float32)

    saadr = np.squeeze(
        np.load(
            os.path.join(
                SAADR_DIR,
                sid + "_saadr.npy"
            )
        )
    ).astype(np.float32)

    # --------------------------------------------------------
    # SHAPE CHECK
    # --------------------------------------------------------

    if not (
        gt.shape
        == swin.shape
        == adr.shape
        == saadr.shape
    ):

        print(
            f"\n⚠️ Shape mismatch: {sid}"
        )

        print(
            "GT   :", gt.shape
        )

        print(
            "Swin :", swin.shape
        )

        print(
            "ADR  :", adr.shape
        )

        print(
            "SAADR:", saadr.shape
        )

        continue

    # --------------------------------------------------------
    # RANGE
    # --------------------------------------------------------

    gt = np.clip(
        gt,
        0.0,
        1.0
    )

    swin = np.clip(
        swin,
        0.0,
        1.0
    )

    adr = np.clip(
        adr,
        0.0,
        1.0
    )

    saadr = np.clip(
        saadr,
        0.0,
        1.0
    )

    # --------------------------------------------------------
    # PSNR
    # --------------------------------------------------------

    ps = calculate_psnr(
        swin,
        gt
    )

    pa = calculate_psnr(
        adr,
        gt
    )

    psa = calculate_psnr(
        saadr,
        gt
    )

    # --------------------------------------------------------
    # SSIM
    # --------------------------------------------------------

    ss = calculate_ssim(
        swin,
        gt
    )

    sa = calculate_ssim(
        adr,
        gt
    )

    ssa = calculate_ssim(
        saadr,
        gt
    )

    # --------------------------------------------------------
    # STORE
    # --------------------------------------------------------

    swin_psnr.append(ps)
    adr_psnr.append(pa)
    saadr_psnr.append(psa)

    swin_ssim.append(ss)
    adr_ssim.append(sa)
    saadr_ssim.append(ssa)

    results.append({
        "id": sid,

        "swinir_psnr": float(ps),
        "adr_psnr": float(pa),
        "saadr_psnr": float(psa),

        "swinir_ssim": float(ss),
        "adr_ssim": float(sa),
        "saadr_ssim": float(ssa),

        "adr_psnr_delta":
            float(pa - ps),

        "saadr_psnr_delta":
            float(psa - ps),

        "saadr_vs_adr_psnr":
            float(psa - pa),

        "adr_ssim_delta":
            float(sa - ss),

        "saadr_ssim_delta":
            float(ssa - ss),

        "saadr_vs_adr_ssim":
            float(ssa - sa)
    })

# ------------------------------------------------------------
# CONVERT
# ------------------------------------------------------------

swin_psnr = np.asarray(
    swin_psnr
)

adr_psnr = np.asarray(
    adr_psnr
)

saadr_psnr = np.asarray(
    saadr_psnr
)

swin_ssim = np.asarray(
    swin_ssim
)

adr_ssim = np.asarray(
    adr_ssim
)

saadr_ssim = np.asarray(
    saadr_ssim
)

print("\n" + "=" * 80)
print("FINAL RESULTS")
print("=" * 80)

print(
    "Evaluated:",
    len(results)
)

assert len(results) == 320

# ------------------------------------------------------------
# MEANS
# ------------------------------------------------------------

mean_swin_psnr = swin_psnr.mean()
mean_adr_psnr = adr_psnr.mean()
mean_saadr_psnr = saadr_psnr.mean()

mean_swin_ssim = swin_ssim.mean()
mean_adr_ssim = adr_ssim.mean()
mean_saadr_ssim = saadr_ssim.mean()

# ------------------------------------------------------------
