def psnr(pred, gt):

    pred = np.clip(
        pred,
        0.0,
        1.0
    )

    gt = np.clip(
        gt,
        0.0,
        1.0
    )

    mse = np.mean(
        (pred - gt) ** 2
    )

    return 10.0 * np.log10(
        1.0 / max(mse, 1e-12)
    )


def ssim(pred, gt):

    pred = np.clip(
        pred,
        0.0,
        1.0
    ).astype(np.float32)

    gt = np.clip(
        gt,
        0.0,
        1.0
    ).astype(np.float32)

    return structural_similarity(
        gt,
        pred,
        data_range=1.0
    )

