# ============================================================
# FAST ROBUSTNESS METRIC DEBUG
# ============================================================

import numpy as np

print("=" * 80)
print("TESTING PSNR CALCULATION")
print("=" * 80)

# Use the currently loaded valid arrays
print("GT shape    :", gt.shape)
print("SwinIR shape:", swinir.shape)
print("ADR shape   :", adr.shape)

def safe_psnr(pred, target):

    pred = np.asarray(pred, dtype=np.float32)
    target = np.asarray(target, dtype=np.float32)

    # Remove accidental dimensions
    pred = np.squeeze(pred)
    target = np.squeeze(target)

    # Shape check
    if pred.shape != target.shape:
        raise ValueError(
            f"Shape mismatch: pred={pred.shape}, "
            f"target={target.shape}"
        )

    # Remove numerical problems
    pred = np.nan_to_num(
        pred,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    target = np.nan_to_num(
        target,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    # Correct image range
    pred = np.clip(pred, 0.0, 1.0)
    target = np.clip(target, 0.0, 1.0)

    mse = np.mean(
        (pred - target) ** 2,
        dtype=np.float64
    )

    if not np.isfinite(mse):
        return np.nan

    if mse <= 1e-12:
        return 100.0

    return 10.0 * np.log10(
        1.0 / mse
    )


p1 = safe_psnr(swinir, gt)
p2 = safe_psnr(adr, gt)

print()
print("SwinIR PSNR :", p1)
print("ADR PSNR    :", p2)

print()

if np.isfinite(p1) and np.isfinite(p2):

    print("✅ PSNR FUNCTION WORKS")

    print(
        f"Delta       : {p2-p1:+.4f} dB"
    )

else:

    print("❌ PSNR STILL INVALID")

print("=" * 80)

