# ------------------------------------------------------------
# FUNCTION FOR RESULT COLLECTION
# ------------------------------------------------------------

def summarize(name, swin_scores, adr_scores):

    swin_scores = np.asarray(
        swin_scores,
        dtype=np.float64
    )

    adr_scores = np.asarray(
        adr_scores,
        dtype=np.float64
    )

    valid = (
        np.isfinite(swin_scores)
        &
        np.isfinite(adr_scores)
    )

    swin_scores = swin_scores[valid]
    adr_scores = adr_scores[valid]

    if len(swin_scores) == 0:

        return {
            "samples": 0,
            "swinir_psnr": None,
            "adr_psnr": None,
            "delta": None,
            "wins": 0
        }

    swin_mean = float(
        np.mean(swin_scores)
    )

    adr_mean = float(
        np.mean(adr_scores)
    )

    delta = adr_mean - swin_mean

    wins = int(
        np.sum(
            adr_scores > swin_scores
        )
    )

    return {
        "samples": int(len(swin_scores)),
        "swinir_psnr": swin_mean,
        "adr_psnr": adr_mean,
        "delta": float(delta),
        "wins": wins
    }


# ------------------------------------------------------------
# IMPORTANT:
# IF THE PREVIOUS ROBUSTNESS CELL CREATED A RESULTS DICT,
# EXTRACT IT AUTOMATICALLY.
# ------------------------------------------------------------

possible_names = [
    "robustness_results",
    "all_results",
    "benchmark_results",
    "results"
]

for variable_name in possible_names:

    if variable_name not in globals():
        continue

    obj = globals()[variable_name]

    if isinstance(obj, dict):

        for key, value in obj.items():

            if isinstance(value, dict):

                lower_key = str(key).lower()

                if (
                    "gaussian" in lower_key
                    or "speckle" in lower_key
                ):

                    final_results[str(key)] = value


# ------------------------------------------------------------
# PRINT ANY RESULTS FOUND
# ------------------------------------------------------------

print("\n" + "=" * 80)
print("ROBUSTNESS RESULT SUMMARY")
print("=" * 80)

if final_results:

    for name, value in final_results.items():

        print(
            f"\n{name}:"
        )

