print("\n[1] TEST RESULTS DIRECTORY")
print("-" * 75)

print("Path:", TEST_DIR)
print("Exists:", TEST_DIR.exists())

if not TEST_DIR.exists():
    raise FileNotFoundError("test_results directory not found")

files = sorted([
    f for f in TEST_DIR.rglob("*")
    if f.is_file()
])

print("Total files:", len(files))

# ------------------------------------------------------------
# 2. FILE TYPES
# ------------------------------------------------------------

print("\n[2] FILE TYPES")
print("-" * 75)

extensions = {}

for f in files:
    ext = f.suffix.lower() or "[none]"
    extensions[ext] = extensions.get(ext, 0) + 1

for ext, count in sorted(extensions.items()):
    print(f"{ext:<15} : {count}")

# ------------------------------------------------------------
# 3. SHOW FIRST 20 FILES
# ------------------------------------------------------------

print("\n[3] SAMPLE FILE NAMES")
