# 4. LOAD SAMPLE FILES
# ------------------------------------------------------------

print("\n[4] SAMPLE FILE CONTENT / SHAPE")
print("-" * 75)

for f in files[:10]:

    print("\nFile:", f.name)

    try:

        if f.suffix.lower() == ".npy":

            arr = np.load(f)

            print("  Type :", type(arr).__name__)
            print("  Shape:", arr.shape)
            print("  Dtype:", arr.dtype)
            print(
                "  Min  :",
                float(np.min(arr))
            )
            print(
                "  Max  :",
                float(np.max(arr))
            )
            print(
                "  Mean :",
                float(np.mean(arr))
            )

        elif f.suffix.lower() == ".json":

            with open(
                f,
                "r",
                encoding="utf-8"
            ) as fp:

                data = json.load(fp)

            print(
                "  JSON type:",
                type(data).__name__
            )

            if isinstance(data, dict):
                print(
                    "  Keys:",
                    list(data.keys())[:20]
                )

        else:

            print(
                "  Unsupported sample type:",
                f.suffix
            )

    except Exception as e:

        print("  ❌ Error:", repr(e))

