print("\n[2] SwinIR_Project status")
print("Exists:", PROJECT.exists())

if PROJECT.exists():
    print("Project contents:")
    for p in sorted(PROJECT.iterdir(), key=lambda p: p.name.lower()):
        if p.is_dir():
            print("  [DIR] ", p.name)
        else:
            size_mb = p.stat().st_size / (1024 * 1024)
            print(f"  [FILE] {p.name} ({size_mb:.2f} MB)")

# ------------------------------------------------------------
