# ------------------------------------------------------------
print("\n[3] Searching for GT / NoisyLR folders")

gt_dirs = []
noisylr_dirs = []

for root, dirs, files in os.walk(MYDRIVE):
    # Skip temporary/system-like directories if encountered
    dirs[:] = [
        d for d in dirs
        if not d.startswith(".")
        and d not in ["__pycache__"]
    ]

    root_path = Path(root)

    for d in dirs:
        name_lower = d.lower()

        if name_lower == "gt":
            gt_dirs.append(root_path / d)

        if name_lower == "noisylr":
            noisylr_dirs.append(root_path / d)

print("\nGT folders found:", len(gt_dirs))
for p in gt_dirs:
    print("  ", p)

print("\nNoisyLR folders found:", len(noisylr_dirs))
for p in noisylr_dirs:
    print("  ", p)

# ------------------------------------------------------------
# 4. Count files inside candidate GT / NoisyLR folders
# ------------------------------------------------------------
print("\n[4] Candidate dataset folder file counts")

def count_files(folder):
    try:
        return sum(1 for x in folder.rglob("*") if x.is_file())
    except Exception as e:
        return f"ERROR: {e}"

for p in gt_dirs:
    print(f"GT      : {p}")
    print(f"  files : {count_files(p)}")

for p in noisylr_dirs:
    print(f"NoisyLR : {p}")
    print(f"  files : {count_files(p)}")

# ------------------------------------------------------------
# 5. Search for likely dataset archives
# ------------------------------------------------------------
print("\n[5] Searching for possible dataset archives")

archive_exts = {
    ".zip", ".tar", ".gz", ".tgz", ".7z", ".rar"
}

archives = []

for root, dirs, files in os.walk(MYDRIVE):
    dirs[:] = [
        d for d in dirs
        if not d.startswith(".")
        and d not in ["__pycache__"]
    ]

    for f in files:
        path = Path(root) / f

        if path.suffix.lower() in archive_exts:
            size_mb = path.stat().st_size / (1024 * 1024)
            archives.append((path, size_mb))

for path, size_mb in sorted(archives, key=lambda x: str(x[0]).lower()):
    print(f"  {path}  ({size_mb:.2f} MB)")

print("Total archives found:", len(archives))

