# STEP 10 — INSPECT TRAIN.ZIP WITHOUT EXTRACTING
# SAFE: read-only inspection. No extraction, deletion, modification, training, or validation.

from pathlib import Path
import zipfile
from collections import Counter

zip_path = Path("/content/drive/MyDrive/dataset/train.zip")

print("=" * 70)
print("STEP 10 — TRAIN.ZIP CONTENT INSPECTION")
print("=" * 70)

print("\nArchive:")
print(zip_path)
print("Exists:", zip_path.exists())

if not zip_path.exists():
    print("\nERROR: train.zip was not found.")
else:
    size_mb = zip_path.stat().st_size / (1024 * 1024)
    print(f"Size: {size_mb:.2f} MB")

    with zipfile.ZipFile(zip_path, "r") as z:
        names = z.namelist()

        print("\nTotal archive entries:", len(names))

        # --------------------------------------------------------
        # Look for GT / NoisyLR paths
        # --------------------------------------------------------
        gt_entries = []
        noisylr_entries = []

        for name in names:
            n = name.replace("\\", "/").lower()

            if "/gt/" in n or n.startswith("gt/"):
                gt_entries.append(name)

            if "/noisylr/" in n or n.startswith("noisylr/"):
                noisylr_entries.append(name)

        print("\nGT entries:", len(gt_entries))
        print("NoisyLR entries:", len(noisylr_entries))

        # --------------------------------------------------------
        # Show representative paths
        # --------------------------------------------------------
        print("\nFirst 15 GT entries:")
        for x in gt_entries[:15]:
            print("  ", x)

        print("\nFirst 15 NoisyLR entries:")
        for x in noisylr_entries[:15]:
            print("  ", x)

        # --------------------------------------------------------
        # Check likely image files
        # --------------------------------------------------------
        image_exts = {
            ".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff", ".npy"
        }

        gt_images = [
            x for x in gt_entries
            if Path(x).suffix.lower() in image_exts
        ]

        noisylr_images = [
            x for x in noisylr_entries
            if Path(x).suffix.lower() in image_exts
        ]

        print("\nGT image/data files:", len(gt_images))
        print("NoisyLR image/data files:", len(noisylr_images))

        # --------------------------------------------------------
        # Inspect top-level directory structure
        # --------------------------------------------------------
        top_dirs = Counter()

        for name in names:
            parts = name.replace("\\", "/").split("/")
            if len(parts) >= 2:
                top_dirs[parts[0]] += 1

        print("\nTop-level archive structure:")
        for k, v in top_dirs.most_common(20):
            print(f"  {k}/ -> {v} entries")

        # --------------------------------------------------------
        # Search for train/GT and train/NoisyLR explicitly
        # --------------------------------------------------------
        print("\nExplicit path checks:")

        patterns = [
            "train/gt/",
            "train/noisylr/",
            "gt/",
            "noisylr/"
        ]

        for pattern in patterns:
            matches = [
                x for x in names
                if x.replace("\\", "/").lower().startswith(pattern)
            ]
            print(f"  {pattern:18s} -> {len(matches)} entries")

        # --------------------------------------------------------
        # Final decision
        # --------------------------------------------------------
        print("\n" + "=" * 70)
        print("DIAGNOSTIC RESULT")
        print("=" * 70)

        if len(gt_images) > 0 and len(noisylr_images) > 0:
            print("GT + NoisyLR data EXISTS inside train.zip.")
            print("NEXT: inspect pairing and locate the 320 validation samples.")
        elif len(gt_entries) > 0 or len(noisylr_entries) > 0:
            print("Partial GT/NoisyLR structure found.")
            print("NEXT: inspect the archive structure before proceeding.")
        else:
            print("No GT/NoisyLR directories detected in train.zip.")
            print("NEXT: robustness should likely be skipped.")

# STEP 11 — VERIFY EXISTING TRAIN/VAL SPLIT AGAINST TRAIN.ZIP
# SAFE: read-only inspection only.

import json
import zipfile
from pathlib import Path

PROJECT = Path("/content/drive/MyDrive/SwinIR_Project")
ZIP_PATH = Path("/content/drive/MyDrive/dataset/train.zip")
SPLIT_PATH = PROJECT / "train_val_split.json"

print("=" * 70)
print("STEP 11 — VERIFY EXISTING SPLIT")
print("=" * 70)

# ------------------------------------------------------------
# 1. Load existing split
# ------------------------------------------------------------
with open(SPLIT_PATH, "r") as f:
    split = json.load(f)

train_list = split.get("train", [])
val_list = split.get("val", [])

print("\nExisting split:")
print("  Train entries:", len(train_list))
print("  Val entries  :", len(val_list))
print("  Total        :", len(train_list) + len(val_list))

# ------------------------------------------------------------
# 2. Normalize split names
# ------------------------------------------------------------
def normalize_name(x):
    x = str(x).replace("\\", "/")
    return Path(x).stem

train_ids = {normalize_name(x) for x in train_list}
val_ids = {normalize_name(x) for x in val_list}

print("\nUnique IDs:")
print("  Train:", len(train_ids))
print("  Val  :", len(val_ids))
print("  Total:", len(train_ids | val_ids))

overlap = train_ids & val_ids
print("\nTrain/Val overlap:", len(overlap))

# ------------------------------------------------------------
# 3. Read ZIP names only
# ------------------------------------------------------------
with zipfile.ZipFile(ZIP_PATH, "r") as z:
    names = z.namelist()

gt_ids = set()
noisylr_ids = set()

for name in names:
    n = name.replace("\\", "/")

    if n.startswith("train/GT/") and n.endswith(".npy"):
        gt_ids.add(Path(n).stem)

    elif n.startswith("train/NoisyLR/") and n.endswith(".npy"):
        noisylr_ids.add(Path(n).stem)

print("\nZIP dataset:")
print("  GT IDs     :", len(gt_ids))
print("  NoisyLR IDs:", len(noisylr_ids))
print("  GT == NoisyLR:", gt_ids == noisylr_ids)

# ------------------------------------------------------------
# 4. Check split IDs against dataset
# ------------------------------------------------------------
train_missing_gt = train_ids - gt_ids
val_missing_gt = val_ids - gt_ids

train_missing_lr = train_ids - noisylr_ids
val_missing_lr = val_ids - noisylr_ids

print("\nMissing from ZIP:")
print("  Train IDs missing GT     :", len(train_missing_gt))
print("  Train IDs missing NoisyLR:", len(train_missing_lr))
print("  Val IDs missing GT       :", len(val_missing_gt))
print("  Val IDs missing NoisyLR  :", len(val_missing_lr))

# ------------------------------------------------------------
# 5. Check for unused dataset IDs
# ------------------------------------------------------------
split_ids = train_ids | val_ids

unused_ids = gt_ids - split_ids

print("\nDataset IDs not present in existing split:", len(unused_ids))

# ------------------------------------------------------------
# 6. Show examples if anything is wrong
# ------------------------------------------------------------
if overlap:
    print("\nExample Train/Val overlap:")
    print(list(sorted(overlap))[:10])

if val_missing_gt:
    print("\nExample validation IDs missing GT:")
    print(list(sorted(val_missing_gt))[:10])

if val_missing_lr:
    print("\nExample validation IDs missing NoisyLR:")
    print(list(sorted(val_missing_lr))[:10])

if unused_ids:
    print("\nExample unused dataset IDs:")
    print(list(sorted(unused_ids))[:10])

# ------------------------------------------------------------
# 7. Final decision
# ------------------------------------------------------------
print("\n" + "=" * 70)
print("RESULT")
print("=" * 70)

if (
    len(train_list) == 2880
    and len(val_list) == 320
    and not overlap
    and not train_missing_gt
    and not train_missing_lr
    and not val_missing_gt
    and not val_missing_lr
    and gt_ids == noisylr_ids
):
    print("PASS — Existing 2880/320 split is compatible with train.zip.")
    print("NEXT — We can use the existing 320 validation pairs for robustness.")
else:
    print("CHECK REQUIRED — Split and archive need further inspection.")

