def find_zip_file(folder, sample_id):

    candidates = [
        f"train/{folder}/{sample_id}.npy",
        f"train/{folder.lower()}/{sample_id}.npy",
        f"train/{folder.capitalize()}/{sample_id}.npy",
    ]

    for p in candidates:
        if p in names:
            return p

    # fallback: case-insensitive search
    target = f"/{sample_id}.npy".lower()

    for p in names:
        if p.lower().endswith(target):
            if f"/{folder.lower()}/" in p.lower():
                return p

    return None


pairs = []

for sid in val_ids:

    gt_path = find_zip_file("GT", sid)
    lr_path = find_zip_file("NoisyLR", sid)

