ZIP_PATH = "/content/drive/MyDrive/dataset/train.zip"
JSON_PATH = "/content/drive/MyDrive/SwinIR_Project/final_320_robustness_epoch20.json"

OUT_DIR = "/content/drive/MyDrive/SwinIR_Project/FINAL_HACKATHON_EVIDENCE/visual_robustness"

os.makedirs(OUT_DIR, exist_ok=True)

# ------------------------------------------------
# LOAD RESULTS
# ------------------------------------------------
with open(JSON_PATH, "r") as f:
    data = json.load(f)

results = data["results"]

print("Total results:", len(results))

# ------------------------------------------------
# SELECT REPRESENTATIVE SAMPLES
# ------------------------------------------------

# Best PSNR
best = sorted(results, key=lambda x: x["psnr"], reverse=True)[:2]

# Median-like samples
median_idx = np.argsort(
    [abs(x["psnr"] - data["psnr_median"]) for x in results]
)[:2]

median_samples = [results[i] for i in median_idx]

# Worst PSNR
worst = sorted(results, key=lambda x: x["psnr"])[:1]

selected = best + median_samples + worst

# Remove duplicate IDs
unique = {}
for x in selected:
    unique[x["id"]] = x

selected = list(unique.values())

print("\nSelected samples:")
for x in selected:
    print(
        x["id"],
        "PSNR =", round(x["psnr"], 3),
        "SSIM =", round(x["ssim"], 3)
    )

# ------------------------------------------------
# ZIP
# ------------------------------------------------
zf = zipfile.ZipFile(ZIP_PATH, "r")
names = set(zf.namelist())

def get_path(folder, sid):

    candidates = [
        f"train/{folder}/{sid}.npy",
        f"train/{folder.lower()}/{sid}.npy"
    ]

    for p in candidates:
        if p in names:
            return p

    for p in names:
        if p.lower().endswith(f"/{sid}.npy"):
            if f"/{folder.lower()}/" in p.lower():
                return p

    return None


def normalize_img(x):

    x = np.squeeze(np.asarray(x)).astype(np.float32)

    x = np.nan_to_num(
        x,
        nan=0.0,
        posinf=0.0,
        neginf=0.0
    )

    if x.max() > 1.5:
        if x.max() <= 255:
            x = x / 255.0
        elif x.max() <= 65535:
            x = x / 65535.0

    return np.clip(x, 0, 1)


# ------------------------------------------------
# MODEL MUST ALREADY EXIST FROM STEP 19
# ------------------------------------------------
model.eval()

device = next(model.parameters()).device

# ------------------------------------------------
# GENERATE VISUALS
# ------------------------------------------------

for sample in selected:

    sid = sample["id"]

    gt_path = get_path("GT", sid)
    lr_path = get_path("NoisyLR", sid)

    if gt_path is None or lr_path is None:
        print("Skipping:", sid)
        continue

    gt = np.load(zf.open(gt_path))
    lr = np.load(zf.open(lr_path))

    lr_img = normalize_img(lr)
    gt_img = normalize_img(gt)

    inp = torch.from_numpy(lr_img).float()
    inp = inp.unsqueeze(0).unsqueeze(0).to(device)

    with torch.no_grad():
        pred = model(inp)

    pred_img = pred.squeeze().detach().cpu().numpy()
    pred_img = np.clip(pred_img, 0, 1)

    # ------------------------------------------------
    # PLOT
    # ------------------------------------------------

    fig, axes = plt.subplots(1, 3, figsize=(12, 4))

    axes[0].imshow(lr_img, cmap="gray")
    axes[0].set_title("NoisyLR")
    axes[0].axis("off")

    axes[1].imshow(pred_img, cmap="gray")
    axes[1].set_title(
        f"SwinIR\nPSNR={sample['psnr']:.2f} dB"
    )
    axes[1].axis("off")

    axes[2].imshow(gt_img, cmap="gray")
    axes[2].set_title(
        f"GT\nSSIM={sample['ssim']:.3f}"
    )
    axes[2].axis("off")

    plt.suptitle(
        f"Sample {sid} — Epoch 20 SwinIR"
    )

    plt.tight_layout()

    save_path = os.path.join(
        OUT_DIR,
        f"sample_{sid}_visual.png"
    )

    plt.savefig(
        save_path,
        dpi=200,
        bbox_inches="tight"
    )

    plt.close()

    print("Saved:", save_path)

zf.close()

