# STEP 22 — FINAL BENCHMARK COMPARISON
# ================================================================

import os
import json
import numpy as np
from pathlib import Path

PROJECT = "/content/drive/MyDrive/SwinIR_Project"
EVIDENCE = os.path.join(PROJECT, "FINAL_HACKATHON_EVIDENCE")

ROBUSTNESS_JSON = os.path.join(
    PROJECT, "final_320_robustness_epoch20.json"
)

BENCHMARK_JSON = os.path.join(
    PROJECT, "final_320_swinir_adr_saadr_benchmark.json"
)

FINAL_JSON = os.path.join(
    EVIDENCE, "STEP22_FINAL_BENCHMARK.json"
)

os.makedirs(EVIDENCE, exist_ok=True)

print("=" * 70)
print("STEP 22 — FINAL BENCHMARK COMPARISON")
print("=" * 70)

# ------------------------------------------------
# 1. Load robustness results
# ------------------------------------------------

print("\n[1] Loading epoch-20 robustness results...")

with open(ROBUSTNESS_JSON, "r") as f:
    robustness = json.load(f)

print("Loaded:", ROBUSTNESS_JSON)

# ------------------------------------------------
# 2. Extract PSNR / SSIM values safely
# ------------------------------------------------

def find_records(obj):
    """Recursively find lists containing sample-level results."""
    records = []

    if isinstance(obj, list):
        if len(obj) > 0 and all(isinstance(x, dict) for x in obj):
            # likely result list
            records.append(obj)

        for x in obj:
            records.extend(find_records(x))

    elif isinstance(obj, dict):
        for v in obj.values():
            records.extend(find_records(v))

    return records


record_lists = find_records(robustness)

results = None

for lst in record_lists:
    psnr_ok = sum(
        isinstance(x.get("PSNR"), (int, float)) or
        isinstance(x.get("psnr"), (int, float))
        for x in lst
    )

    ssim_ok = sum(
        isinstance(x.get("SSIM"), (int, float)) or
        isinstance(x.get("ssim"), (int, float))
        for x in lst
    )

    if psnr_ok >= 300 and ssim_ok >= 300:
        results = lst
        break

# fallback: check common keys
if results is None:
    for key in ["results", "samples", "metrics", "records"]:
        if isinstance(robustness.get(key), list):
            results = robustness[key]
            break

if results is None:
    raise RuntimeError(
        "Could not locate 320 sample-level PSNR/SSIM results in JSON."
    )

print("Sample records found:", len(results))

# ------------------------------------------------
# 3. Extract metrics
# ------------------------------------------------

psnr = []
ssim = []
ids = []

for r in results:
    p = r.get("PSNR", r.get("psnr"))
    s = r.get("SSIM", r.get("ssim"))

    if p is not None and s is not None:
        psnr.append(float(p))
        ssim.append(float(s))

        sample_id = (
            r.get("id")
            or r.get("ID")
            or r.get("sample_id")
            or r.get("filename")
            or "unknown"
        )
        ids.append(str(sample_id))

psnr = np.array(psnr, dtype=np.float64)
ssim = np.array(ssim, dtype=np.float64)

print("Valid metric records:", len(psnr))

# ------------------------------------------------
# 4. Calculate final statistics
# ------------------------------------------------

epoch20_stats = {
    "samples": int(len(psnr)),

    "psnr": {
        "mean": float(np.mean(psnr)),
        "std": float(np.std(psnr)),
        "median": float(np.median(psnr)),
        "min": float(np.min(psnr)),
        "max": float(np.max(psnr)),
    },

    "ssim": {
        "mean": float(np.mean(ssim)),
        "std": float(np.std(ssim)),
        "median": float(np.median(ssim)),
        "min": float(np.min(ssim)),
        "max": float(np.max(ssim)),
    }
}

print("\n[2] EPOCH-20 SWINIR")
print("-" * 50)

print(f"Samples : {epoch20_stats['samples']}")

print("\nPSNR")
print(f"Mean   : {epoch20_stats['psnr']['mean']:.4f}")
print(f"Std    : {epoch20_stats['psnr']['std']:.4f}")
print(f"Median : {epoch20_stats['psnr']['median']:.4f}")
print(f"Min    : {epoch20_stats['psnr']['min']:.4f}")
print(f"Max    : {epoch20_stats['psnr']['max']:.4f}")

print("\nSSIM")
print(f"Mean   : {epoch20_stats['ssim']['mean']:.4f}")
print(f"Std    : {epoch20_stats['ssim']['std']:.4f}")
print(f"Median : {epoch20_stats['ssim']['median']:.4f}")
print(f"Min    : {epoch20_stats['ssim']['min']:.4f}")
print(f"Max    : {epoch20_stats['ssim']['max']:.4f}")

# ------------------------------------------------
# 5. Load existing benchmark if available
# ------------------------------------------------

baseline = None

if os.path.exists(BENCHMARK_JSON):

    print("\n[3] Existing benchmark found:")
    print(BENCHMARK_JSON)

    with open(BENCHMARK_JSON, "r") as f:
        benchmark = json.load(f)

    # Print top-level structure so we don't guess baseline values
    print("\nBenchmark top-level keys:")
    if isinstance(benchmark, dict):
        print(list(benchmark.keys()))

    # Search recursively for metric dictionaries
    def search_metric_dicts(obj, path="root"):
        found = []

        if isinstance(obj, dict):
            keys_lower = {str(k).lower() for k in obj.keys()}

            if (
                "psnr" in keys_lower
                or "ssim" in keys_lower
                or "mean_psnr" in keys_lower
                or "mean_ssim" in keys_lower
            ):
                found.append((path, obj))

            for k, v in obj.items():
                found.extend(
                    search_metric_dicts(v, f"{path}.{k}")
                )

        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                found.extend(
                    search_metric_dicts(v, f"{path}[{i}]")
                )

        return found

    metric_dicts = search_metric_dicts(benchmark)

    print("\nMetric-containing sections found:", len(metric_dicts))

    for path, d in metric_dicts[:20]:
        print("\nPATH:", path)
        print(d)

else:
    print("\n[3] Existing benchmark JSON not found.")
    print("We will preserve the epoch-20 results without inventing baseline values.")

# ------------------------------------------------
# 6. Robustness distribution
# ------------------------------------------------

print("\n[4] ROBUSTNESS DISTRIBUTION")
print("-" * 50)

psnr_thresholds = [10, 15, 20, 25, 30]

for t in psnr_thresholds:
    count = int(np.sum(psnr >= t))
    pct = 100.0 * count / len(psnr)
    print(
        f"PSNR >= {t:2d} dB : "
        f"{count:3d}/{len(psnr)} ({pct:.2f}%)"
    )

ssim_thresholds = [0.5, 0.7, 0.8, 0.9, 0.95]

for t in ssim_thresholds:
    count = int(np.sum(ssim >= t))
    pct = 100.0 * count / len(ssim)
    print(
        f"SSIM >= {t:.2f} : "
        f"{count:3d}/{len(ssim)} ({pct:.2f}%)"
    )

# ------------------------------------------------
# 7. Identify best / worst samples
# ------------------------------------------------

best_psnr_idx = int(np.argmax(psnr))
worst_psnr_idx = int(np.argmin(psnr))

best_ssim_idx = int(np.argmax(ssim))
worst_ssim_idx = int(np.argmin(ssim))

print("\n[5] EXTREME CASES")
print("-" * 50)

print(
    f"Best PSNR  : {ids[best_psnr_idx]} "
    f"= {psnr[best_psnr_idx]:.4f} dB"
)

print(
    f"Worst PSNR : {ids[worst_psnr_idx]} "
    f"= {psnr[worst_psnr_idx]:.4f} dB"
)

print(
    f"Best SSIM  : {ids[best_ssim_idx]} "
    f"= {ssim[best_ssim_idx]:.4f}"
)

print(
    f"Worst SSIM : {ids[worst_ssim_idx]} "
    f"= {ssim[worst_ssim_idx]:.4f}"
)

# ------------------------------------------------
# 8. Save final evidence
# ------------------------------------------------

final_evidence = {
    "step": 22,
    "description": "Final SwinIR benchmark comparison",
    "checkpoint": {
        "epoch": 20,
        "path": "/content/drive/MyDrive/SwinIR_Project/swinir_epoch_20.pth"
    },
    "validation": {
        "samples": int(len(psnr)),
        "failed": 0
    },
    "epoch20": epoch20_stats,

    "distribution": {
        "psnr_ge_10": int(np.sum(psnr >= 10)),
        "psnr_ge_15": int(np.sum(psnr >= 15)),
        "psnr_ge_20": int(np.sum(psnr >= 20)),
        "psnr_ge_25": int(np.sum(psnr >= 25)),
        "psnr_ge_30": int(np.sum(psnr >= 30)),

        "ssim_ge_050": int(np.sum(ssim >= 0.50)),
        "ssim_ge_070": int(np.sum(ssim >= 0.70)),
        "ssim_ge_080": int(np.sum(ssim >= 0.80)),
        "ssim_ge_090": int(np.sum(ssim >= 0.90)),
        "ssim_ge_095": int(np.sum(ssim >= 0.95)),
    },

    "extremes": {
        "best_psnr": {
            "id": ids[best_psnr_idx],
            "value": float(psnr[best_psnr_idx])
        },
        "worst_psnr": {
            "id": ids[worst_psnr_idx],
            "value": float(psnr[worst_psnr_idx])
        },
        "best_ssim": {
            "id": ids[best_ssim_idx],
            "value": float(ssim[best_ssim_idx])
        },
        "worst_ssim": {
            "id": ids[worst_ssim_idx],
            "value": float(ssim[worst_ssim_idx])
        }
    },

    "visual_evidence_folder":
        os.path.join(EVIDENCE, "visual_robustness"),

    "source_robustness_json":
        ROBUSTNESS_JSON
}

with open(FINAL_JSON, "w") as f:
    json.dump(final_evidence, f, indent=2)

print("\n" + "=" * 70)
print("STEP 22 COMPLETE")
print("=" * 70)

print("Final evidence saved:")
print(FINAL_JSON)

print("\nNext:")
print("STEP 23 — Generate final tables + plots + hackathon evidence summary")

