# ------------------------------------------------
# 1. LOAD ROBUSTNESS RESULTS
# ------------------------------------------------

with open(ROBUSTNESS_JSON, "r") as f:
    robustness = json.load(f)

# Locate sample results
results = None

def find_result_list(obj):
    global results

    if results is not None:
        return

    if isinstance(obj, list):
        if len(obj) >= 300 and all(isinstance(x, dict) for x in obj):
            psnr_count = sum(
                ("PSNR" in x or "psnr" in x)
                for x in obj
            )
            ssim_count = sum(
                ("SSIM" in x or "ssim" in x)
                for x in obj
            )

            if psnr_count >= 300 and ssim_count >= 300:
                results = obj
                return

        for x in obj:
            find_result_list(x)

    elif isinstance(obj, dict):
        for v in obj.values():
            find_result_list(v)

find_result_list(robustness)

if results is None:
    raise RuntimeError("Could not find sample-level results.")

psnr = np.array([
    float(x.get("PSNR", x.get("psnr")))
    for x in results
])

ssim = np.array([
    float(x.get("SSIM", x.get("ssim")))
    for x in results
])

