os.makedirs(EVIDENCE, exist_ok=True)

OUTPUT_JSON = os.path.join(
    EVIDENCE,
    "STEP26_BASELINE_PROFILE.json"
)

# ------------------------------------------------
# 1. Device
# ------------------------------------------------

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("\n[1] DEVICE")
print("-" * 50)
print("Device:", device)

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))
    print(
        "GPU memory:",
        round(
            torch.cuda.get_device_properties(0).total_memory / (1024**3),
            2
        ),
        "GB"
    )

# ------------------------------------------------
# 2. Checkpoint size
# ------------------------------------------------

print("\n[2] CHECKPOINT SIZE")
print("-" * 50)

checkpoint_size_mb = os.path.getsize(CHECKPOINT) / (1024 ** 2)

print("Checkpoint:", CHECKPOINT)
print(f"Checkpoint size: {checkpoint_size_mb:.3f} MB")

# ------------------------------------------------
# 3. Build EXACT model
# ------------------------------------------------

print("\n[3] BUILDING EXACT SWINIR")
print("-" * 50)

# This must match your STEP 18C constructor
model = SwinIR(
    img_size=64,
    patch_size=1,
    in_chans=1,
    embed_dim=96,
    depths=[6, 6, 6, 6],
    num_heads=[6, 6, 6, 6],
    window_size=15,
    mlp_ratio=4.0,
    upscale=2
)

model = model.to(device)
model.eval()

print("Model created successfully.")

# ------------------------------------------------
# 4. Load checkpoint safely
# ------------------------------------------------

print("\n[4] LOADING EPOCH-20 CHECKPOINT")
print("-" * 50)

ckpt = torch.load(
    CHECKPOINT,
    map_location="cpu"
)

if isinstance(ckpt, dict) and "params" in ckpt:
    state_dict = ckpt["params"]
elif isinstance(ckpt, dict) and "state_dict" in ckpt:
    state_dict = ckpt["state_dict"]
else:
    state_dict = ckpt

# Remove possible DataParallel prefix
clean_state = {}

for k, v in state_dict.items():
    if k.startswith("module."):
        k = k[7:]
    clean_state[k] = v

state_dict = clean_state

load_result = model.load_state_dict(
    state_dict,
    strict=False
)

missing = list(load_result.missing_keys)
unexpected = list(load_result.unexpected_keys)

print("Checkpoint keys :", len(state_dict))
print("Model keys      :", len(model.state_dict()))
print("Missing keys    :", len(missing))
print("Unexpected keys :", len(unexpected))

if missing:
    print("\nWARNING — Missing keys:")
    for k in missing[:20]:
        print(" ", k)

if unexpected:
    print("\nWARNING — Unexpected keys:")
    for k in unexpected[:20]:
        print(" ", k)

if len(missing) == 0:
    print("✓ No missing model weights")

# ------------------------------------------------
# 5. Parameter count
# ------------------------------------------------

print("\n[5] MODEL SIZE / PARAMETERS")
print("-" * 50)

total_params = sum(
    p.numel()
    for p in model.parameters()
)

trainable_params = sum(
    p.numel()
    for p in model.parameters()
    if p.requires_grad
)

non_trainable_params = total_params - trainable_params

fp32_model_mb = (
    total_params * 4 / (1024 ** 2)
)

print(f"Total parameters     : {total_params:,}")
print(f"Trainable parameters : {trainable_params:,}")
print(f"Non-trainable        : {non_trainable_params:,}")
print(f"Approx FP32 size     : {fp32_model_mb:.3f} MB")

