# ------------------------------------------------
# 7. Dummy inference benchmark
# ------------------------------------------------

print("\n[7] INFERENCE LATENCY BENCHMARK")
print("-" * 50)

# Use 128x128 input -> 256x256 output
dummy = torch.randn(
    1,
    1,
    128,
    128,
    device=device
)

# Warm-up
print("Warm-up...")

with torch.no_grad():

    for _ in range(20):

        _ = model(dummy)

if device.type == "cuda":
    torch.cuda.synchronize()

# Reset CUDA peak memory
if device.type == "cuda":
    torch.cuda.reset_peak_memory_stats()

# Timed inference
num_runs = 100

times = []

with torch.no_grad():

    for _ in range(num_runs):

        if device.type == "cuda":
            torch.cuda.synchronize()

        start = time.perf_counter()

        _ = model(dummy)

        if device.type == "cuda":
            torch.cuda.synchronize()

        end = time.perf_counter()

        times.append(
            end - start
        )

times = np.array(times)

mean_time_ms = times.mean() * 1000
median_time_ms = np.median(times) * 1000
std_time_ms = times.std() * 1000
min_time_ms = times.min() * 1000
max_time_ms = times.max() * 1000

fps = 1000.0 / mean_time_ms

print(f"Runs               : {num_runs}")
print(f"Mean latency       : {mean_time_ms:.3f} ms/image")
print(f"Median latency     : {median_time_ms:.3f} ms/image")
print(f"Std latency        : {std_time_ms:.3f} ms")
print(f"Min latency        : {min_time_ms:.3f} ms")
print(f"Max latency        : {max_time_ms:.3f} ms")
print(f"Throughput         : {fps:.2f} images/sec")

