# ------------------------------------------------
# 5. Detect likely GT / INPUT keywords
# ------------------------------------------------

gt_keywords = [
    "gt", "groundtruth", "ground_truth",
    "clean", "target", "hr", "highres", "high_res"
]

input_keywords = [
    "input", "noisy", "noise",
    "lr", "lowres", "low_res",
    "degraded", "degradation"
]

print("\nKEYWORD ANALYSIS")
