gt_files = []
input_files = []

for f in npy_files:

    name = os.path.basename(f).lower()

    if any(k in name for k in gt_keywords):
        gt_files.append(f)

    if any(k in name for k in input_keywords):
        input_files.append(f)

print("Possible GT files    :", len(gt_files))
print("Possible INPUT files :", len(input_files))

print("\nGT examples:")
for f in gt_files[:20]:
    print(" ", f)

print("\nINPUT examples:")
for f in input_files[:20]:
    print(" ", f)

# ------------------------------------------------
# 6. Search parent folder names too
# ------------------------------------------------

print("\nFOLDER KEYWORD ANALYSIS")
print("-" * 70)

for d, count in dirs.most_common():

    dl = d.lower()

    tags = []

    if any(k in dl for k in gt_keywords):
        tags.append("GT-like")

    if any(k in dl for k in input_keywords):
        tags.append("INPUT-like")

    if tags:
        print(count, tags, "->", d)

