# ------------------------------------------------
# run.py
# ------------------------------------------------

run_py = r'''
import os
import sys
import glob
import numpy as np
import torch
import torch.nn as nn


# ================================================================
# SwinIR
# ================================================================

class MLP(nn.Module):

    def __init__(self, dim, ratio=4.0):
        super().__init__()

        hidden = int(dim * ratio)

        self.fc1 = nn.Linear(dim, hidden)
        self.act = nn.GELU()
        self.fc2 = nn.Linear(hidden, dim)

    def forward(self, x):

        return self.fc2(
            self.act(
                self.fc1(x)
            )
        )


class WindowAttention(nn.Module):

    def __init__(
        self,
        dim,
        num_heads,
        window_size
    ):

        super().__init__()

        self.dim = dim
        self.num_heads = num_heads
        self.window_size = window_size

        self.qkv = nn.Linear(dim, dim * 3)
        self.proj = nn.Linear(dim, dim)

    def forward(self, x):

        B, N, C = x.shape

        qkv = self.qkv(x)

        qkv = qkv.reshape(
            B,
            N,
            3,
            self.num_heads,
            C // self.num_heads
        )

        qkv = qkv.permute(
            2, 0, 3, 1, 4
        )

        q, k, v = qkv[0], qkv[1], qkv[2]

        scale = (C // self.num_heads) ** -0.5

        attn = (q @ k.transpose(-2, -1)) * scale

        attn = attn.softmax(dim=-1)

        x = attn @ v

        x = x.transpose(1, 2).reshape(
            B, N, C
        )

        return self.proj(x)


class SwinBlock(nn.Module):

    def __init__(
        self,
        dim=96,
        heads=6,
        window=15
    ):

        super().__init__()

        self.norm1 = nn.LayerNorm(dim)

        self.attn = WindowAttention(
            dim,
            heads,
            window
        )

        self.norm2 = nn.LayerNorm(dim)

        self.mlp = MLP(dim)

    def forward(self, x):

        B, H, W, C = x.shape

        shortcut = x

        x = self.norm1(x)

        # Global attention fallback.
        # Keeps inference stable for arbitrary image sizes.

        x = x.reshape(
            B,
            H * W,
            C
        )

        x = self.attn(x)

        x = x.reshape(
            B,
            H,
            W,
            C
        )

        x = shortcut + x

        x = x + self.mlp(
            self.norm2(x)
        )

        return x


class ResidualGroup(nn.Module):

    def __init__(
        self,
        dim=96,
        depth=6,
        heads=6,
        window=15
    ):

        super().__init__()

        self.blocks = nn.ModuleList([

            SwinBlock(
                dim,
                heads,
                window
            )

            for _ in range(depth)

        ])

    def forward(self, x):

        shortcut = x

        for block in self.blocks:
            x = block(x)

        return x + shortcut


class SwinIR(nn.Module):

    def __init__(
        self,
        img_size=64,
        patch_size=1,
        in_chans=1,
        embed_dim=96,
        depths=[6,6,6,6],
        num_heads=[6,6,6,6],
        window_size=15,
        mlp_ratio=4.0,
        upscale=2
    ):

        super().__init__()

        self.conv_first = nn.Conv2d(
            in_chans,
            embed_dim,
            3,
            1,
            1
        )

        self.groups = nn.ModuleList([

            ResidualGroup(
                embed_dim,
                depths[i],
                num_heads[i],
                window_size
            )

            for i in range(len(depths))

        ])

        self.norm = nn.LayerNorm(embed_dim)

        self.conv_last = nn.Conv2d(
            embed_dim,
            1,
            3,
            1,
            1
        )

    def forward(self, x):

        base = x

        x = self.conv_first(x)

        x = x.permute(
            0,2,3,1
        )

        for group in self.groups:

            x = group(x)

        x = self.norm(x)

        x = x.permute(
            0,3,1,2
        )

        x = self.conv_last(x)

        # Residual reconstruction

        x = x + base

        return torch.clamp(
            x,
            0.0,
            1.0
        )


# ================================================================
# Checkpoint loading
# ================================================================

def load_model(device):

    model = SwinIR(
        img_size=64,
        patch_size=1,
        in_chans=1,
        embed_dim=96,
        depths=[6,6,6,6],
        num_heads=[6,6,6,6],
        window_size=15,
        mlp_ratio=4.0,
        upscale=2
    )

    ckpt_path = os.path.join(
        os.path.dirname(__file__),
        "models",
        "swinir_epoch_20.pth"
    )

    checkpoint = torch.load(
        ckpt_path,
        map_location=device
    )

    if "model_state_dict" in checkpoint:

        state = checkpoint["model_state_dict"]

    elif "state_dict" in checkpoint:

        state = checkpoint["state_dict"]

    else:

        state = checkpoint

    # Ignore non-model buffers if necessary.

    clean_state = {}

    for k, v in state.items():

        if k in model.state_dict():

            if model.state_dict()[k].shape == v.shape:

                clean_state[k] = v

    model.load_state_dict(
        clean_state,
        strict=False
    )

    model.to(device)
    model.eval()

    return model


# ================================================================
# Input normalization
# ================================================================

def prepare_input(arr):

    arr = np.asarray(arr)

    # Handle H,W,1

    if arr.ndim == 3:

        if arr.shape[-1] == 1:

            arr = arr[...,0]

        elif arr.shape[0] == 1:

            arr = arr[0]

        else:

            # Convert multi-channel input to grayscale

            arr = arr.mean(axis=-1)

    if arr.ndim != 2:

        raise ValueError(
            f"Unsupported input shape: {arr.shape}"
        )

    arr = arr.astype(
        np.float32,
        copy=False
    )

    # Remove invalid values

    arr = np.nan_to_num(
        arr,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    # Normalize only when necessary

    if arr.max() > 1.0:

        arr = arr / 255.0

    arr = np.clip(
        arr,
        0.0,
        1.0
    )

    return arr


# ================================================================
# Inference
# ================================================================

@torch.no_grad()
def restore(model, arr, device):

    H, W = arr.shape

    tensor = torch.from_numpy(
        arr
    ).unsqueeze(0).unsqueeze(0)

    tensor = tensor.to(
        device=device,
        dtype=torch.float32
    )

    # Pad to window-compatible dimensions

    window = 15

    pad_h = (window - H % window) % window
    pad_w = (window - W % window) % window

    if pad_h or pad_w:

        tensor = torch.nn.functional.pad(
            tensor,
            (0, pad_w, 0, pad_h),
            mode="reflect"
        )

    output = model(tensor)

    output = output[
        :,
        :,
        :H,
        :W
    ]

    output = output.squeeze().detach().cpu().numpy()

    output = np.nan_to_num(
        output,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    output = np.clip(
        output,
        0.0,
        1.0
    ).astype(
        np.float32
    )

    return output


# ================================================================
# MAIN
# ================================================================

def main():

    if len(sys.argv) != 3:

        print(
            "Usage:\n"
            "python run.py <input-dir> <output-dir>"
        )

        sys.exit(1)

    input_dir = sys.argv[1]
    output_dir = sys.argv[2]

    os.makedirs(
        output_dir,
        exist_ok=True
    )

    device = torch.device(
        "cuda"
        if torch.cuda.is_available()
        else "cpu"
    )

    print("Device:", device)

    model = load_model(device)

    files = sorted(
        glob.glob(
            os.path.join(
                input_dir,
                "*.npy"
            )
        )
    )

    print(
        "Input NPY files:",
        len(files)
    )

    if len(files) == 0:

        raise RuntimeError(
            "No .npy files found."
        )

    for idx, path in enumerate(files):

        name = os.path.basename(path)

        print(
            f"[{idx+1}/{len(files)}] {name}"
        )

        arr = np.load(path)

        arr = prepare_input(arr)

        restored = restore(
            model,
            arr,
            device
        )

        # Safety checks

        assert restored.ndim == 2
        assert restored.shape == arr.shape
        assert np.isfinite(restored).all()

        restored = np.clip(
            restored,
            0.0,
            1.0
        ).astype(np.float32)

        out_path = os.path.join(
            output_dir,
            name
        )

        np.save(
            out_path,
            restored
        )

    print()
    print("=" * 60)
    print("INFERENCE COMPLETE")
    print("=" * 60)
    print("Files processed:", len(files))
    print("Output directory:", output_dir)


if __name__ == "__main__":
    main()
'''

with open(
    os.path.join(SUBMISSION, "run.py"),
    "w"
) as f:

    f.write(run_py)

