# ================================================================
# STEP 34 — GPU MEMORY / INPUT SIZE COMPATIBILITY TEST
# ================================================================

import os
import sys
import subprocess
import numpy as np

SUBMISSION_DIR = "/content/drive/MyDrive/SwinIR_Project/submission"
RUN_PATH = os.path.join(SUBMISSION_DIR, "run.py")

BASE_DIR = os.path.join(SUBMISSION_DIR, "_step34_memory_test")
os.makedirs(BASE_DIR, exist_ok=True)

sizes = [32, 48, 64, 80, 96, 112]

print("=" * 70)
print("STEP 34 — GPU MEMORY / INPUT SIZE COMPATIBILITY TEST")
print("=" * 70)

results = []

for size in sizes:

    input_dir = os.path.join(BASE_DIR, f"input_{size}")
    output_dir = os.path.join(BASE_DIR, f"output_{size}")

    os.makedirs(input_dir, exist_ok=True)
    os.makedirs(output_dir, exist_ok=True)

    # ------------------------------------------------
    # Create normalized grayscale input
    # ------------------------------------------------

    y, x = np.mgrid[0:size, 0:size]

    arr = (
        0.5
        + 0.2 * np.sin(x / 5.0)
        + 0.2 * np.cos(y / 7.0)
        + 0.1 * np.sin((x + y) / 9.0)
    )

    arr -= arr.min()
    arr /= arr.max()
    arr = arr.astype(np.float32)

    np.save(
        os.path.join(input_dir, "test.npy"),
        arr
    )

    print(f"\n{'=' * 70}")
    print(f"TEST SIZE: {size} x {size}")
    print("=" * 70)

    cmd = [
        sys.executable,
        RUN_PATH,
        input_dir,
        output_dir
    ]

    try:

        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=300
        )

        output_path = os.path.join(
            output_dir,
            "test.npy"
        )

        success = (
            result.returncode == 0
            and os.path.exists(output_path)
        )

        if success:

            out = np.load(output_path)

            valid = (
                out.shape == arr.shape
                and np.isfinite(out).all()
                and out.min() >= 0
                and out.max() <= 1
            )

            status = "PASS" if valid else "INVALID OUTPUT"

        else:

            status = "FAIL"

        print("Return code:", result.returncode)
        print("Status:", status)

        if result.stdout:
            print("\nSTDOUT:")
            print(result.stdout[-1500:])

        if result.stderr:
            print("\nERROR:")
            print(result.stderr[-2000:])

        results.append(
            (size, status)
        )

    except subprocess.TimeoutExpired:

        print("Status: TIMEOUT")
        results.append(
            (size, "TIMEOUT")
        )

    except Exception as e:

        print("Status: ERROR")
        print(repr(e))

        results.append(
            (size, "ERROR")
        )

print("\n" + "=" * 70)
print("STEP 34 SUMMARY")
print("=" * 70)

for size, status in results:
    print(f"{size:4d} x {size:<4d} -> {status}")

print("=" * 70)

