# ================================================================
# STEP 37 — PATCH RESTORE() WITH MEMORY-SAFE TILED INFERENCE
# ================================================================

import os
import re
import shutil

RUN_PATH = "/content/drive/MyDrive/SwinIR_Project/submission/run.py"
BACKUP_PATH = RUN_PATH + ".before_tiling_backup"

print("=" * 70)
print("STEP 37 — MEMORY-SAFE TILED INFERENCE PATCH")
print("=" * 70)

# ------------------------------------------------
# 1. Backup original run.py
# ------------------------------------------------

if not os.path.exists(BACKUP_PATH):
    shutil.copy2(RUN_PATH, BACKUP_PATH)
    print("✓ Original run.py backed up")
    print(" ", BACKUP_PATH)
else:
    print("✓ Backup already exists")
    print(" ", BACKUP_PATH)

# ------------------------------------------------
# 2. Read run.py
# ------------------------------------------------

with open(RUN_PATH, "r", encoding="utf-8") as f:
    code = f.read()

# ------------------------------------------------
# 3. Locate restore()
# ------------------------------------------------

start_marker = "@torch.no_grad()\ndef restore(model, arr, device):"
start = code.find(start_marker)

if start == -1:
    raise RuntimeError("Could not locate restore() function.")

end_marker = "\n\n# ================================================================\n# MAIN"
end = code.find(end_marker, start)

if end == -1:
    raise RuntimeError("Could not locate end of restore() function.")

old_restore = code[start:end]

# ------------------------------------------------
# 4. New tiled restore()
# ------------------------------------------------

new_restore = r'''@torch.no_grad()
def restore(model, arr, device):

    H, W = arr.shape

    # ------------------------------------------------------------
    # Memory-safe tiled inference
    #
    # The model uses global attention internally, so full 256x256
    # inference requires excessive GPU memory.  We therefore run
    # overlapping tiles and blend them back into the original size.
    #
    # 96x96 was verified to fit the available GPU memory.
    # ------------------------------------------------------------

    tile_size = 96
    overlap = 24
    stride = tile_size - overlap

    # For small inputs, keep the original single-pass behavior.
    if H <= tile_size and W <= tile_size:

        tensor = torch.from_numpy(
            arr
        ).unsqueeze(0).unsqueeze(0)

        tensor = tensor.to(
            device=device,
            dtype=torch.float32
        )

        window = 15

        pad_h = (window - H % window) % window
        pad_w = (window - W % window) % window

        if pad_h or pad_w:

            tensor = torch.nn.functional.pad(
                tensor,
                (0, pad_w, 0, pad_h),
                mode="reflect"
            )

        output = model(tensor)

        output = output[
            :,
            :,
            :H,
            :W
        ]

        output = output.squeeze().detach().cpu().numpy()

    else:

        # --------------------------------------------------------
        # Determine tile start positions.
        # Always include the final tile so the entire image
        # is covered, even when dimensions are not divisible
        # by the stride.
        # --------------------------------------------------------

        def positions(length):
            if length <= tile_size:
                return [0]

            starts = list(
                range(
                    0,
                    length - tile_size + 1,
                    stride
                )
            )

            final_start = length - tile_size

            if starts[-1] != final_start:
                starts.append(final_start)

            return starts

        ys = positions(H)
        xs = positions(W)

        # CPU accumulation buffers avoid holding the complete
        # output plus all tile outputs on the GPU.
        output_sum = np.zeros(
            (H, W),
            dtype=np.float32
        )

        weight_sum = np.zeros(
            (H, W),
            dtype=np.float32
        )

        # --------------------------------------------------------
        # Smooth blending weights.
        #
        # This reduces visible seams between overlapping tiles.
        # A small positive floor prevents zero-weight pixels.
        # --------------------------------------------------------

        yy = np.linspace(
            0.0,
            1.0,
            tile_size,
            dtype=np.float32
        )

        xx = np.linspace(
            0.0,
            1.0,
            tile_size,
            dtype=np.float32
        )

        wy = 1.0 - np.abs(
            2.0 * yy - 1.0
        )

        wx = 1.0 - np.abs(
            2.0 * xx - 1.0
        )

        blend = (
            np.outer(wy, wx)
            + 0.05
        ).astype(np.float32)

        total_tiles = len(ys) * len(xs)
        tile_index = 0

        for y0 in ys:

            for x0 in xs:

                tile_index += 1

                y1 = min(
                    y0 + tile_size,
                    H
                )

                x1 = min(
                    x0 + tile_size,
                    W
                )

                tile_h = y1 - y0
                tile_w = x1 - x0

                tile = arr[
                    y0:y1,
                    x0:x1
                ]

                # ------------------------------------------------
                # Pad edge tiles to tile_size.
                # ------------------------------------------------

                pad_h = tile_size - tile_h
                pad_w = tile_size - tile_w

                if pad_h or pad_w:

                    if tile_h > 1 and tile_w > 1:

                        tile_tensor = torch.from_numpy(
                            tile
                        ).unsqueeze(0).unsqueeze(0)

                        tile_tensor = torch.nn.functional.pad(
                            tile_tensor,
                            (0, pad_w, 0, pad_h),
                            mode="reflect"
                        )

                    else:

                        tile_tensor = torch.from_numpy(
                            np.pad(
                                tile,
                                (
                                    (0, pad_h),
                                    (0, pad_w)
                                ),
                                mode="edge"
                            )
                        ).unsqueeze(0).unsqueeze(0)

                else:

                    tile_tensor = torch.from_numpy(
                        tile
                    ).unsqueeze(0).unsqueeze(0)

                tile_tensor = tile_tensor.to(
                    device=device,
                    dtype=torch.float32
                )

                # ------------------------------------------------
                # Model inference on one manageable tile.
                # ------------------------------------------------

                tile_output = model(
                    tile_tensor
                )

                tile_output = tile_output[
                    :,
                    :,
                    :tile_h,
                    :tile_w
                ]

                tile_output = (
                    tile_output
                    .squeeze()
                    .detach()
                    .cpu()
                    .numpy()
                    .astype(np.float32)
                )

                # ------------------------------------------------
                # Accumulate weighted output on CPU.
                # ------------------------------------------------

                local_weight = blend[
                    :tile_h,
                    :tile_w
                ]

                output_sum[
                    y0:y1,
                    x0:x1
                ] += (
                    tile_output * local_weight
                )

                weight_sum[
                    y0:y1,
                    x0:x1
                ] += local_weight

                # Explicitly release GPU tile tensors.
                del tile_tensor
                del tile_output

                if device.type == "cuda":
                    torch.cuda.empty_cache()

        # --------------------------------------------------------
        # Normalize overlap accumulation.
        # --------------------------------------------------------

        output = output_sum / np.maximum(
            weight_sum,
            1e-8
        )

    # ------------------------------------------------------------
    # Final safety / output normalization
    # ------------------------------------------------------------

    output = np.nan_to_num(
        output,
        nan=0.0,
        posinf=1.0,
        neginf=0.0
    )

    output = np.clip(
        output,
        0.0,
        1.0
    ).astype(
        np.float32
    )

    return output
'''

# ------------------------------------------------
# 5. Replace restore()
# ------------------------------------------------

code_new = (
    code[:start]
    + new_restore
    + code[end:]
)

with open(RUN_PATH, "w", encoding="utf-8") as f:
    f.write(code_new)

print("✓ restore() replaced with tiled implementation")

# ------------------------------------------------
# 6. Syntax validation
# ------------------------------------------------

try:
    compile(
        code_new,
        RUN_PATH,
        "exec"
    )

    print("✓ run.py syntax check passed")

except Exception as e:
    print("✗ Syntax check failed")
    print(repr(e))

    # Restore backup automatically
    shutil.copy2(
        BACKUP_PATH,
        RUN_PATH
    )

    raise

# ------------------------------------------------
# 7. Verify patch
# ------------------------------------------------

with open(RUN_PATH, "r", encoding="utf-8") as f:
    verify_code = f.read()

checks = [
    ("tile_size = 96", "96-pixel tile"),
    ("overlap = 24", "24-pixel overlap"),
    ("output_sum", "CPU output accumulation"),
    ("weight_sum", "overlap weighting"),
    ("torch.cuda.empty_cache()", "GPU memory cleanup")
]

print("\nPATCH VERIFICATION")
print("-" * 70)

all_found = True

for text, description in checks:

    found = text in verify_code

    print(
        ("✓" if found else "✗"),
        description
    )

    if not found:
        all_found = False

print("\n" + "=" * 70)

if all_found:
    print("✓ STEP 37 COMPLETE")
    print("✓ Tiled inference patch installed")
    print("✓ Original run.py backed up")
    print("✓ Syntax validation passed")
else:
    print("✗ STEP 37 VERIFICATION FAILED")

print("=" * 70)

