import os
import json

ROOT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_PATH = os.path.join(
    ROOT,
    "train_val_split.json"
)

print("=" * 70)
print("STEP 42 — DATASET SPLIT ANALYSIS")
print("=" * 70)

# ------------------------------------------------
# Load JSON
# ------------------------------------------------

if not os.path.exists(SPLIT_PATH):
    raise FileNotFoundError(
        SPLIT_PATH
    )

with open(
    SPLIT_PATH,
    "r",
    encoding="utf-8"
) as f:

    data = json.load(f)

print("\nJSON TYPE")
print("-" * 70)

print(type(data))

# ------------------------------------------------
# Inspect structure
# ------------------------------------------------

print("\nTOP-LEVEL STRUCTURE")
print("-" * 70)

if isinstance(data, dict):

    print("Keys:")

    for key in data.keys():

        value = data[key]

        if isinstance(value, list):
            description = f"list[{len(value)}]"

        elif isinstance(value, dict):
            description = f"dict[{len(value)}]"

        else:
            description = type(value).__name__

        print(
            f"  {key}: {description}"
        )

else:

    print(
        "Length:",
        len(data)
    )

# ------------------------------------------------
# Recursive sample printer
# ------------------------------------------------

def inspect_object(obj, indent=0, max_items=5):

    prefix = " " * indent

    if isinstance(obj, dict):

        for i, (key, value) in enumerate(obj.items()):

            if i >= max_items:
                print(
                    prefix + "..."
                )
                break

            print(
                prefix
                + str(key)
                + ":"
            )

            inspect_object(
                value,
                indent + 2,
                max_items
            )

    elif isinstance(obj, list):

        print(
            prefix
            + f"list length={len(obj)}"
        )

        for item in obj[:max_items]:

            print(
                prefix
                + "  - "
                + repr(item)
            )

    else:

        print(
            prefix
            + repr(obj)
        )

print("\nJSON SAMPLE")
print("-" * 70)

inspect_object(
    data,
    indent=0,
    max_items=10
)

# ------------------------------------------------
# Search every string for paths
# ------------------------------------------------

print("\nPATH / FILE REFERENCES")
print("-" * 70)

def collect_strings(obj):

    results = []

    if isinstance(obj, dict):

        for value in obj.values():
            results.extend(
                collect_strings(value)
            )

    elif isinstance(obj, list):

        for value in obj:
            results.extend(
                collect_strings(value)
            )

    elif isinstance(obj, str):

        results.append(obj)

    return results

strings = collect_strings(data)

unique_strings = list(
    dict.fromkeys(strings)
)

for s in unique_strings[:100]:

    print(s)

print("\nTOTAL STRINGS:", len(unique_strings))

# ------------------------------------------------
# Check whether referenced files exist
# ------------------------------------------------

print("\nREFERENCE EXISTENCE CHECK")
print("-" * 70)

checked = 0
exists = 0

for s in unique_strings:

    if not isinstance(s, str):
        continue

    candidates = [
        s,
        os.path.join(ROOT, s)
    ]

    for candidate in candidates:

        if os.path.exists(candidate):

            print(
                "✓",
                candidate
            )

            exists += 1
            checked += 1
            break

    else:

        # Only show path-like strings
        if (
            "/" in s
            or "\\" in s
            or "." in os.path.basename(s)
        ):

            print(
                "✗",
                s
            )

            checked += 1

print(
    "\nChecked:",
    checked,
    "Existing:",
    exists
)

print("\n" + "=" * 70)
print("STEP 42 COMPLETE")
print("=" * 70)

