# STEP 43 — LOCATE ORIGINAL DATASET FILES USING SAMPLE IDS
# ================================================================

import os
import glob
import json

ROOT = "/content/drive/MyDrive/SwinIR_Project"

SPLIT_PATH = os.path.join(
    ROOT,
    "train_val_split.json"
)

print("=" * 70)
print("STEP 43 — LOCATING ORIGINAL DATASET FILES")
print("=" * 70)

# ------------------------------------------------
# Load split IDs
# ------------------------------------------------

with open(
    SPLIT_PATH,
    "r",
    encoding="utf-8"
) as f:

    split = json.load(f)

train_ids = set(split["train"])
val_ids = set(split["val"])

all_ids = train_ids | val_ids

print("\nDATASET IDS")
print("-" * 70)
print("Train:", len(train_ids))
print("Val  :", len(val_ids))
print("Total:", len(all_ids))

# ------------------------------------------------
# Search all files under project
# ------------------------------------------------

all_files = []

for root, dirs, files in os.walk(ROOT):

    # Ignore submission temporary test directories
    if "/submission/_step" in root:
        continue

    for filename in files:

        all_files.append(
            os.path.join(root, filename)
        )

print("\nTOTAL PROJECT FILES")
print("-" * 70)
print(len(all_files))

# ------------------------------------------------
# Match IDs against filenames
# ------------------------------------------------

matches = {}

for path in all_files:

    filename = os.path.basename(path)

    stem = os.path.splitext(filename)[0]

    # Exact ID match
    if stem in all_ids:

        matches.setdefault(
            stem,
            []
        ).append(path)

    # ID followed by suffix
    for sample_id in all_ids:

        if (
            filename.startswith(sample_id + "_")
            or filename.startswith(sample_id + ".")
        ):

            matches.setdefault(
                sample_id,
                []
            ).append(path)

# Remove duplicates
for sample_id in matches:

    matches[sample_id] = sorted(
        set(matches[sample_id])
    )

# ------------------------------------------------
# Summary
# ------------------------------------------------

matched_ids = set(matches.keys())

print("\nMATCH SUMMARY")
print("-" * 70)
print("IDs with files :", len(matched_ids))
print("IDs without    :", len(all_ids - matched_ids))

# ------------------------------------------------
# Show examples
# ------------------------------------------------

print("\nMATCHED EXAMPLES")
print("-" * 70)

for sample_id in sorted(
    matched_ids
)[:100]:

    print(
        sample_id,
        "->"
    )

    for path in matches[sample_id]:
        print(
            "   ",
            path
        )

# ------------------------------------------------
# Group matches by directory
# ------------------------------------------------

print("\nMATCHED DIRECTORIES")
print("-" * 70)

directory_counts = {}

for sample_id, paths in matches.items():

    for path in paths:

        directory = os.path.dirname(path)

        directory_counts[directory] = (
            directory_counts.get(directory, 0)
            + 1
        )

for directory, count in sorted(
    directory_counts.items(),
    key=lambda x: -x[1]
):

    print(
        f"{count:5d} -> {directory}"
    )

# ------------------------------------------------
# Check final_test_visuals specifically
# ------------------------------------------------

VISUAL_DIR = os.path.join(
    ROOT,
    "final_test_visuals"
)

print("\nFINAL TEST VISUALS")
print("-" * 70)

visual_files = []

if os.path.exists(VISUAL_DIR):

    for root, dirs, files in os.walk(
        VISUAL_DIR
    ):

        for filename in files:

            visual_files.append(
                os.path.join(
                    root,
                    filename
                )
            )

print(
    "Total files:",
    len(visual_files)
)

for path in sorted(
    visual_files
)[:50]:

    print(
        os.path.basename(path)
    )

print("\n" + "=" * 70)
print("STEP 43 COMPLETE")
print("=" * 70)

