import os
import re
from PIL import Image
import numpy as np

ROOT = "/content/drive/MyDrive/SwinIR_Project"

PLOT_DIR = os.path.join(
    ROOT,
    "FINAL_HACKATHON_EVIDENCE",
    "final_plots"
)

print("=" * 70)
print("STEP 45 — EXISTING METRIC EVIDENCE")
print("=" * 70)

# ------------------------------------------------
# Inspect plot files
# ------------------------------------------------

for filename in [
    "epoch20_psnr_distribution.png",
    "epoch20_ssim_distribution.png"
]:

    path = os.path.join(
        PLOT_DIR,
        filename
    )

    print("\nFILE:", path)

    if not os.path.exists(path):
        print("✗ NOT FOUND")
        continue

    img = Image.open(path)

    print("✓ Exists")
    print("Size:", img.size)
    print("Mode:", img.mode)

# ------------------------------------------------
# Search entire project for metric text/data files
# ------------------------------------------------

print("\n" + "=" * 70)
print("SEARCHING FOR SAVED METRICS")
print("=" * 70)

metric_keywords = [
    "psnr",
    "ssim",
    "metric",
    "evaluation",
    "eval",
    "score",
    "result"
]

matches = []

for root, dirs, files in os.walk(ROOT):

    if "/submission/_step" in root:
        continue

    for filename in files:

        lower = filename.lower()

        if any(
            keyword in lower
            for keyword in metric_keywords
        ):

            matches.append(
                os.path.join(
                    root,
                    filename
                )
            )

for path in sorted(set(matches)):

    print(path)

# ------------------------------------------------
# Search text-readable files for PSNR / SSIM
# ------------------------------------------------

print("\n" + "=" * 70)
print("SEARCHING TEXT FILES FOR METRIC VALUES")
print("=" * 70)

text_extensions = [
    ".txt",
    ".csv",
    ".json",
    ".log",
    ".md"
]

patterns = [
    r"PSNR[^0-9]*([0-9]+(?:\.[0-9]+)?)",
    r"SSIM[^0-9]*([0-9]+(?:\.[0-9]+)?)",
    r"psnr[^0-9]*([0-9]+(?:\.[0-9]+)?)",
    r"ssim[^0-9]*([0-9]+(?:\.[0-9]+)?)"
]

for root, dirs, files in os.walk(ROOT):

    if "/submission/_step" in root:
        continue

    for filename in files:

        if not filename.lower().endswith(
            tuple(text_extensions)
        ):
            continue

        path = os.path.join(
            root,
            filename
        )

        try:

            with open(
                path,
                "r",
                encoding="utf-8",
                errors="ignore"
            ) as f:

                text = f.read()

        except:
            continue

        found = []

        for pattern in patterns:

            results = re.findall(
                pattern,
                text,
                flags=re.IGNORECASE
            )

            found.extend(results)

        if found:

            print("\nFILE:", path)

            # Print only useful lines
            for line in text.splitlines():

                if (
                    "psnr" in line.lower()
                    or "ssim" in line.lower()
                ):

                    print(
                        " ",
                        line[:300]
                    )

print("\n" + "=" * 70)
print("STEP 45 COMPLETE")
print("=" * 70)

