print("-" * 70)

text_ext = (
    ".txt",
    ".csv",
    ".json",
    ".log",
    ".md"
)

found = False

for path in files:

    if not path.lower().endswith(text_ext):
        continue

    try:
        with open(
            path,
            "r",
            encoding="utf-8",
            errors="ignore"
        ) as f:
            text = f.read()

    except:
        continue

    lines = text.splitlines()

    useful = []

    for line in lines:

        low = line.lower()

        if (
            "psnr" in low
            or "ssim" in low
        ):
            useful.append(line.strip())

    if useful:

        found = True

        print("\nFILE:")
        print(path)

        for line in useful[:30]:
            print(" ", line)

# ------------------------------------------------
# Check plot files
# ------------------------------------------------

print("\nPLOT EVIDENCE")
print("-" * 70)

plot_dir = os.path.join(
    ROOT,
    "FINAL_HACKATHON_EVIDENCE",
    "final_plots"
)

for name in [
    "epoch20_psnr_distribution.png",
    "epoch20_ssim_distribution.png"
]:

    path = os.path.join(
        plot_dir,
        name
    )

    if os.path.exists(path):
        print("✓", name)
    else:
        print("✗", name)

print("\n" + "=" * 70)
print("STEP 45 COMPLETE")
print("=" * 70)

