# ================================================================
# STEP 47 — ACTUAL SUPER-RESOLUTION I/O VERIFICATION
# ================================================================

import os
import sys
import subprocess
import numpy as np
import shutil

PROJECT = "/content/drive/MyDrive/SwinIR_Project"
RUN_PY = os.path.join(PROJECT, "submission", "run.py")
BASE = os.path.join(PROJECT, "submission", "_step47_sr_test")

print("=" * 70)
print("STEP 47 — ACTUAL SUPER-RESOLUTION I/O VERIFICATION")
print("=" * 70)

if os.path.exists(BASE):
    shutil.rmtree(BASE)

os.makedirs(BASE)

sizes = [64, 128, 256]

results = []

for size in sizes:

    print("\n" + "=" * 70)
    print(f"TEST INPUT SIZE: {size} x {size}")
    print("=" * 70)

    input_dir = os.path.join(BASE, f"input_{size}")
    output_dir = os.path.join(BASE, f"output_{size}")

    os.makedirs(input_dir)
    os.makedirs(output_dir)

    # Deterministic test image
    rng = np.random.default_rng(42 + size)

    arr = rng.random(
        (size, size),
        dtype=np.float32
    )

    input_file = os.path.join(
        input_dir,
        "test.npy"
    )

    np.save(input_file, arr)

    print("Input:")
    print("  Shape :", arr.shape)
    print("  Dtype :", arr.dtype)
    print("  Min   :", float(arr.min()))
    print("  Max   :", float(arr.max()))

    cmd = [
        "/usr/bin/python3",
        RUN_PY,
        input_dir,
        output_dir
    ]

    print("\nExecuting...")

    proc = subprocess.run(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True
    )

    print("\nReturn code:", proc.returncode)

    print("\nSTDOUT")
    print("-" * 70)
    print(proc.stdout[-5000:])

    output_file = os.path.join(
        output_dir,
        "test.npy"
    )

    if not os.path.exists(output_file):

        print("\n✗ OUTPUT NOT FOUND")

        results.append({
            "input": size,
            "output": None,
            "scale_h": None,
            "scale_w": None,
            "status": "FAIL"
        })

        continue

    out = np.load(output_file)

    oh, ow = out.shape

    scale_h = oh / size
    scale_w = ow / size

    valid_dtype = out.dtype == np.float32
    finite = np.isfinite(out).all()
    valid_range = (
        float(out.min()) >= 0.0
        and float(out.max()) <= 1.0
    )

    print("\nOUTPUT")
    print("-" * 70)
    print("Shape :", out.shape)
    print("Dtype :", out.dtype)
    print("Min   :", float(out.min()))
    print("Max   :", float(out.max()))
    print("Mean  :", float(out.mean()))
    print("Finite:", finite)

    print("\nSCALE")
    print("-" * 70)
    print("Height scale:", scale_h)
    print("Width scale :", scale_w)

    print("\nVALIDATION")
    print("-" * 70)
    print("Output exists :", "PASS")
    print("Float32       :", "PASS" if valid_dtype else "FAIL")
    print("Finite        :", "PASS" if finite else "FAIL")
    print("Range [0,1]   :", "PASS" if valid_range else "FAIL")

    results.append({
        "input": size,
        "output": out.shape,
        "scale_h": scale_h,
        "scale_w": scale_w,
        "dtype": str(out.dtype),
        "finite": finite,
        "range": valid_range,
        "status": (
            "PASS"
            if valid_dtype and finite and valid_range
            else "FAIL"
        )
    })

# ------------------------------------------------
# FINAL SUMMARY
# ------------------------------------------------

print("\n" + "=" * 70)
print("STEP 47 SUMMARY")
print("=" * 70)

for r in results:

    print(
        f"{r['input']:4d} x {r['input']:<4d}"
        f" -> {str(r['output']):18s}"
        f" | scale H={r['scale_h']}"
        f" W={r['scale_w']}"
        f" | {r['status']}"
    )

print("\n" + "=" * 70)

valid_results = [
    r for r in results
    if r["status"] == "PASS"
]

print(
    f"Valid tests: {len(valid_results)} / {len(results)}"
)

print("=" * 70)

print("\n✓ STEP 47 COMPLETE")

