# STEP 48 — FIND ACTUAL TRAINING INPUT / GT RESOLUTION PAIRS
# ================================================================

import os
import json
import numpy as np
from pathlib import Path

PROJECT = Path("/content/drive/MyDrive/SwinIR_Project")

print("=" * 70)
print("STEP 48 — FINDING ACTUAL TRAINING INPUT / GT RESOLUTION PAIRS")
print("=" * 70)

# ------------------------------------------------
# 1. Load train/validation IDs
# ------------------------------------------------

split_file = PROJECT / "train_val_split.json"

with open(split_file, "r") as f:
    split = json.load(f)

train_ids = [str(x) for x in split["train"]]
val_ids   = [str(x) for x in split["val"]]

all_ids = train_ids + val_ids

print("\nDATASET SPLIT")
print("-" * 70)
print(f"Train IDs : {len(train_ids)}")
print(f"Val IDs   : {len(val_ids)}")
print(f"Total IDs : {len(all_ids)}")


# ------------------------------------------------
# 2. Search project for candidate data files
# ------------------------------------------------

print("\nSEARCHING PROJECT FILES")
print("-" * 70)

extensions = {
    ".npy",
    ".png",
    ".jpg",
    ".jpeg",
    ".bmp",
    ".tif",
    ".tiff"
}

files = []

for root, dirs, filenames in os.walk(PROJECT):

    # Ignore submission test outputs
    dirs[:] = [
        d for d in dirs
        if not (
            d.startswith("_step")
            or d == "__pycache__"
        )
    ]

    for name in filenames:
        p = Path(root) / name

        if p.suffix.lower() in extensions:
            files.append(p)

print(f"Candidate image/data files: {len(files)}")


# ------------------------------------------------
# 3. Build ID → files mapping
# ------------------------------------------------

id_map = {}

for p in files:

    stem = p.stem

    # Extract first numeric 6-digit ID
    import re

    m = re.match(r"^(\d{6})", stem)

    if m:
        sample_id = m.group(1)

        id_map.setdefault(sample_id, []).append(p)


# ------------------------------------------------
# 4. Find files belonging to dataset IDs
# ------------------------------------------------

matched = {}

for sample_id in all_ids:

    if sample_id in id_map:

        matched[sample_id] = id_map[sample_id]


print("\nDATASET FILE MATCHING")
print("-" * 70)
print(f"Dataset IDs       : {len(all_ids)}")
print(f"IDs with files     : {len(matched)}")
print(f"IDs without files  : {len(all_ids) - len(matched)}")


# ------------------------------------------------
# 5. Show matched examples
# ------------------------------------------------

print("\nMATCHED DATA EXAMPLES")
print("-" * 70)

shown = 0

for sample_id in sorted(matched):

    print(f"\nID: {sample_id}")

    for p in matched[sample_id]:

        print(f"  {p}")

    shown += 1

    if shown >= 30:
        break


# ------------------------------------------------
# 6. Inspect NPY candidates
# ------------------------------------------------

print("\nNPY RESOLUTION ANALYSIS")
print("-" * 70)

npy_files = []

for sample_id, paths in matched.items():

    for p in paths:

        if p.suffix.lower() == ".npy":

            npy_files.append((sample_id, p))


print(f"Matched NPY files: {len(npy_files)}")


for sample_id, p in npy_files[:30]:

    try:

        arr = np.load(p, mmap_mode="r")

        print(
            f"{sample_id} | "
            f"{p.name:35s} | "
            f"shape={arr.shape} | "
            f"dtype={arr.dtype}"
        )

    except Exception as e:

        print(
            f"{sample_id} | ERROR | {p} | {e}"
        )


# ------------------------------------------------
# 7. Inspect image dimensions
# ------------------------------------------------

print("\nIMAGE RESOLUTION ANALYSIS")
print("-" * 70)

try:
    from PIL import Image

    image_count = 0

    for sample_id, paths in sorted(matched.items()):

        for p in paths:

            if p.suffix.lower() not in {
                ".png", ".jpg", ".jpeg",
                ".bmp", ".tif", ".tiff"
            }:
                continue

            try:

                with Image.open(p) as im:

                    print(
                        f"{sample_id} | "
                        f"{p.name:40s} | "
                        f"size={im.size} | "
                        f"mode={im.mode}"
                    )

            except Exception as e:

                print(
                    f"{sample_id} | IMAGE ERROR | "
                    f"{p} | {e}"
                )

            image_count += 1

            if image_count >= 50:
                break

        if image_count >= 50:
            break

except ImportError:

    print("PIL not available")


# ------------------------------------------------
# 8. Search filenames for input / GT indicators
# ------------------------------------------------

print("\nINPUT / GT FILENAME ANALYSIS")
print("-" * 70)

keywords = [
    "input",
    "degraded",
    "low",
    "lr",
    "noisy",
    "blur",
    "gt",
    "ground",
    "target",
    "hr",
    "high",
    "clean",
    "sharp"
]

keyword_hits = []

for p in files:

    name = p.name.lower()

    hits = [
        k for k in keywords
        if k in name
    ]

    if hits:

        keyword_hits.append((p, hits))


print(f"Files with useful keywords: {len(keyword_hits)}")

for p, hits in keyword_hits[:100]:

    print(
        f"{p} "
        f"--> {', '.join(hits)}"
    )


# ------------------------------------------------
# 9. Search directories with many image/data files
# ------------------------------------------------

print("\nDATASET-LIKE DIRECTORIES")
print("-" * 70)

dir_counts = {}

for p in files:

    parent = str(p.parent)

    dir_counts[parent] = dir_counts.get(parent, 0) + 1

for directory, count in sorted(
    dir_counts.items(),
    key=lambda x: x[1],
    reverse=True
)[:30]:

    print(f"{count:5d} -> {directory}")


# ------------------------------------------------
# 10. FINAL INTERPRETATION
# ------------------------------------------------

print("\n" + "=" * 70)
print("STEP 48 COMPLETE")
print("=" * 70)

print("""
IMPORTANT:
Do NOT modify run.py yet.

We first need to identify:

    degraded/input resolution
                 ↓
             GT resolution
                 ↓
        actual SR scale

Expected examples:

    128x128 → 256x256 = 2x SR
    256x256 → 512x512 = 2x SR

OR, if the challenge dataset is different,
we will use the actual dimensions discovered above.
""")

