split_file = PROJECT / "train_val_split.json"

with open(split_file, "r") as f:
    split = json.load(f)

train_ids = set(str(x).zfill(6) for x in split["train"])
val_ids   = set(str(x).zfill(6) for x in split["val"])

all_ids = train_ids | val_ids

print("\nDATASET IDs")
