print("=" * 70)

# ------------------------------------------------
# 1. Find Python files
# ------------------------------------------------

py_files = []

for root, dirs, files in os.walk(ROOT):
    # Skip generated/test directories where possible
    for f in files:
        if f.endswith(".py"):
            py_files.append(os.path.join(root, f))

print("\nPYTHON FILES")
print("-" * 70)

for f in py_files:
    print(f)

# ------------------------------------------------
# 2. Search for resolution / SR related code
# ------------------------------------------------

patterns = [
    r"resize\s*\(",
    r"interpolate\s*\(",
    r"upscale",
    r"scale",
    r"scale_factor",
    r"upscale_factor",
    r"hr",
    r"lr",
    r"low.?res",
    r"high.?res",
    r"ground.?truth",
    r"\bgt\b",
    r"\btarget\b",
    r"\binput\b",
    r"crop",
    r"patch",
    r"256",
    r"128",
    r"64",
    r"512",
    r"1024",
]

compiled = [(p, re.compile(p, re.I)) for p in patterns]

print("\n" + "=" * 70)
print("RESOLUTION / DATA PIPELINE REFERENCES")
print("=" * 70)

matches = []

for path in py_files:

    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()
    except:
        continue

    for i, line in enumerate(lines, start=1):

        found = []

        for name, regex in compiled:
            if regex.search(line):
                found.append(name)

        if found:
            matches.append((path, i, found, line.rstrip()))

# ------------------------------------------------
# 3. Print useful matches
# ------------------------------------------------

for path, line_no, found, line in matches:

    print("\nFILE:", path)
