import os
import sys
import torch
import numpy as np

RUN_PY = "/content/drive/MyDrive/SwinIR_Project/submission/run.py"
MODEL_DIR = "/content/drive/MyDrive/SwinIR_Project/submission"

print("=" * 70)
print("STEP 53 — CHECKPOINT + REAL TENSOR SHAPE VERIFICATION")
print("=" * 70)

# ------------------------------------------------
# Load run.py as a module
# ------------------------------------------------

sys.path.insert(0, MODEL_DIR)

import run

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("\nDevice:", device)

# ------------------------------------------------
# Load model
# ------------------------------------------------

model = run.load_model(device)

print("\nModel loaded successfully.")

# ------------------------------------------------
# Check checkpoint tensor shapes directly
# ------------------------------------------------

ckpt_path = os.path.join(
    MODEL_DIR,
    "models",
    "swinir_epoch_20.pth"
)

print("\nCheckpoint:")
print(ckpt_path)

checkpoint = torch.load(
    ckpt_path,
    map_location="cpu"
)

if "model_state_dict" in checkpoint:
    state = checkpoint["model_state_dict"]
elif "state_dict" in checkpoint:
    state = checkpoint["state_dict"]
else:
    state = checkpoint

print("\nCheckpoint tensor shapes:")
print("-" * 70)

for key in state:
    if "conv" in key.lower():
        value = state[key]

        if torch.is_tensor(value):
            print(
                f"{key:45s} "
                f"shape={tuple(value.shape)}"
            )

# ------------------------------------------------
# Real forward-pass shape test
# ------------------------------------------------

print("\n" + "=" * 70)
print("REAL FORWARD-PASS SHAPE TEST")
print("=" * 70)

test_sizes = [
    (32, 32),
    (64, 64),
    (96, 96),
    (128, 128),
    (256, 256),
]

model.eval()

for H, W in test_sizes:

    print("\n" + "-" * 70)
    print(f"INPUT: {H} x {W}")

    x = torch.rand(
        1,
        1,
        H,
        W,
        dtype=torch.float32,
        device=device
    )

    with torch.no_grad():
        y = model(x)

    print("Input shape :", tuple(x.shape))
    print("Output shape:", tuple(y.shape))

    scale_h = y.shape[-2] / H
    scale_w = y.shape[-1] / W

    print(
        f"Scale H     : {scale_h:.2f}x"
    )

    print(
        f"Scale W     : {scale_w:.2f}x"
    )

# ------------------------------------------------
# Verify convolution spatial behavior
# ------------------------------------------------

print("\n" + "=" * 70)
print("CONVOLUTION CONFIGURATION")
print("=" * 70)

print(
    "conv_first:",
    model.conv_first
)

print(
    "conv_last :",
    model.conv_last
)

# ------------------------------------------------
# Final conclusion
# ------------------------------------------------

print("\n" + "=" * 70)
print("STEP 53 CONCLUSION")
print("=" * 70)

print("""
If every test shows:

    input H x W
        ↓
    output H x W

then the deployed checkpoint/model is definitively 1×
same-resolution restoration.

If output becomes:

    H x W → 2H x 2W

then the checkpoint/model contains hidden spatial scaling.

The checkpoint convolution shapes will also tell us whether
the trained model was architecturally designed for SR.
""")

print("=" * 70)
print("STEP 53 COMPLETE")
print("=" * 70)

