import os
import torch
import numpy as np

print("=" * 70)
print("STEP 54 — ORIGINAL CHECKPOINT ARCHITECTURE RECONSTRUCTION")
print("=" * 70)

CKPT_PATH = "/content/drive/MyDrive/SwinIR_Project/submission/models/swinir_epoch_20.pth"

print("\nCheckpoint:")
print(CKPT_PATH)

# ------------------------------------------------
# Load checkpoint
# ------------------------------------------------

checkpoint = torch.load(
    CKPT_PATH,
    map_location="cpu"
)

if isinstance(checkpoint, dict):
    if "model_state_dict" in checkpoint:
        state = checkpoint["model_state_dict"]
        state_source = "model_state_dict"
    elif "state_dict" in checkpoint:
        state = checkpoint["state_dict"]
        state_source = "state_dict"
    else:
        state = checkpoint
        state_source = "root dictionary"
else:
    raise RuntimeError("Unexpected checkpoint format.")

print("\nCheckpoint state source:")
print(state_source)

print("\n" + "=" * 70)
print("ALL CHECKPOINT PARAMETERS")
print("=" * 70)

for k, v in state.items():

    if torch.is_tensor(v):

        print(
            f"{k:<45} "
            f"shape={tuple(v.shape)} "
            f"dtype={v.dtype}"
        )

# ------------------------------------------------
# Search specifically for SR-related layers
# ------------------------------------------------

print("\n" + "=" * 70)
print("UPSAMPLING / RECONSTRUCTION RELATED PARAMETERS")
print("=" * 70)

keywords = [
    "upsample",
    "upsampling",
    "conv_before_upsample",
    "conv_after_body",
    "conv_last",
    "pixelshuffle",
    "shuffle",
    "tail"
]

found = []

for k, v in state.items():

    if not torch.is_tensor(v):
        continue

    kl = k.lower()

    if any(word in kl for word in keywords):

        found.append((k, tuple(v.shape)))

        print(
            f"{k:<45} "
            f"shape={tuple(v.shape)}"
        )

if not found:
    print("No SR-related layers found.")

# ------------------------------------------------
# Analyze output channel requirements
# ------------------------------------------------

print("\n" + "=" * 70)
print("CHANNEL / SCALE ANALYSIS")
print("=" * 70)

conv_before = None
conv_last = None

for k, v in state.items():

    if not torch.is_tensor(v):
        continue

    if "conv_before_upsample" in k.lower():
        conv_before = v

    if k.lower().endswith("conv_last.weight"):
        conv_last = v

if conv_before is not None:

    print("\nconv_before_upsample:")
    print("  Shape:", tuple(conv_before.shape))

    out_channels = conv_before.shape[0]
    in_channels = conv_before.shape[1]

    print("  Input channels :", in_channels)
    print("  Output channels:", out_channels)

    if out_channels == 64:
        print("  → 64 feature channels before reconstruction")

if conv_last is not None:

    print("\nconv_last:")
    print("  Shape:", tuple(conv_last.shape))

    out_channels = conv_last.shape[0]
    in_channels = conv_last.shape[1]

    print("  Input channels :", in_channels)
    print("  Output channels:", out_channels)

# ------------------------------------------------
# Look for explicit PixelShuffle-compatible layers
# ------------------------------------------------

print("\n" + "=" * 70)
print("PIXELSHUFFLE COMPATIBILITY CHECK")
print("=" * 70)

if conv_before is not None:

    c = conv_before.shape[0]

    print("Feature channels before possible PixelShuffle:", c)

    for scale in [2, 3, 4]:

        required = 64 * scale * scale

        print(
            f"Scale {scale}x -> "
            f"expected channels for 64 features: {required}"
        )

        if c == required:
            print("  MATCH")

# ------------------------------------------------
# Inspect checkpoint metadata
# ------------------------------------------------

print("\n" + "=" * 70)
print("CHECKPOINT METADATA")
print("=" * 70)

if isinstance(checkpoint, dict):

    for key in checkpoint.keys():

        if key not in [
            "model_state_dict",
            "state_dict"
        ]:

            value = checkpoint[key]

            if torch.is_tensor(value):
                print(
                    f"{key:<30} tensor shape={tuple(value.shape)}"
                )
            else:
                print(
                    f"{key:<30} type={type(value).__name__} "
                    f"value={value}"
                )

# ------------------------------------------------
# Final interpretation
# ------------------------------------------------

print("\n" + "=" * 70)
print("STEP 54 INTERPRETATION")
print("=" * 70)

print("""
The checkpoint contains:

    conv_before_upsample
    conv_after_body
    conv_last

but the current run.py contains:

    conv_first
    ResidualGroup
    conv_last

with NO actual upsampling layer.

Therefore:

    CHECKPOINT ARCHITECTURE != CURRENT run.py ARCHITECTURE

This is important.

DO NOT modify run.py yet.

Next we need to determine whether the checkpoint came from:

    A) original SwinIR 2x SR
    B) modified same-resolution restoration
    C) another custom training architecture

The parameter names and tensor dimensions will tell us which one.
""")

print("\n" + "=" * 70)
print("STEP 54 COMPLETE")
