# ================================================================
# STEP 57B — PATCH SWINIR ARCHITECTURE
# ================================================================

run_path = "/content/drive/MyDrive/SwinIR_Project/submission/run.py"

with open(run_path, "r") as f:
    lines = f.readlines()

# Find boundaries
start = None
end = None

for i, line in enumerate(lines):
    if line.startswith("class SwinIR(nn.Module):"):
        start = i

    if start is not None and i > start:
        if line.startswith("# ================================================================"):
            end = i
            break

print("Replacing lines:", start + 1, "to", end)

new_class = '''class SwinIR(nn.Module):

    def __init__(
        self,
        img_size=64,
        patch_size=1,
        in_chans=1,
        embed_dim=96,
        depths=[6,6,6,6],
        num_heads=[6,6,6,6],
        window_size=15,
        mlp_ratio=4.0,
        upscale=2
    ):

        super().__init__()

        self.upscale = upscale

        # ------------------------------------------------------------
        # Shallow feature extraction
        # ------------------------------------------------------------

        self.conv_first = nn.Conv2d(
            in_chans,
            embed_dim,
            3,
            1,
            1
        )

        # ------------------------------------------------------------
        # Swin Transformer body
        # ------------------------------------------------------------

        self.groups = nn.ModuleList([

            ResidualGroup(
                embed_dim,
                depths[i],
                num_heads[i],
                window_size
            )

            for i in range(len(depths))

        ])

        self.norm = nn.LayerNorm(embed_dim)

        # ------------------------------------------------------------
        # EXACT CHECKPOINT RECONSTRUCTION BRANCH
        # ------------------------------------------------------------

        self.conv_after_body = nn.Conv2d(
            embed_dim,
            embed_dim,
            3,
            1,
            1
        )

        self.conv_before_upsample = nn.Sequential(
            nn.Conv2d(
                embed_dim,
                64,
                3,
                1,
                1
            )
        )

        self.upsample = nn.Sequential(
            nn.Conv2d(
                64,
                64 * upscale * upscale,
                3,
                1,
                1
            ),
            nn.PixelShuffle(upscale)
        )

        self.conv_last = nn.Conv2d(
            64,
            1,
            3,
            1,
            1
        )

    def forward(self, x):

        # ------------------------------------------------------------
        # Shallow features
        # ------------------------------------------------------------

        x = self.conv_first(x)

        # ------------------------------------------------------------
        # Transformer body
        # ------------------------------------------------------------

        x = x.permute(
            0, 2, 3, 1
        )

        for group in self.groups:
            x = group(x)

        x = self.norm(x)

        x = x.permute(
            0, 3, 1, 2
        )

        # ------------------------------------------------------------
        # Body reconstruction
        # ------------------------------------------------------------

        res = self.conv_after_body(x)

        res = res + x

        # ------------------------------------------------------------
        # Exact checkpoint upsampling path
        # ------------------------------------------------------------

        x = self.conv_before_upsample(res)

        x = self.upsample(x)

        x = self.conv_last(x)

        return torch.clamp(
            x,
            0.0,
            1.0
        )


'''

lines = lines[:start] + [new_class] + lines[end:]

with open(run_path, "w") as f:
    f.writelines(lines)

