import os
import cv2
import numpy as np
import torch

model.eval()

# ------------------------------------------------------------
# Input image
# ------------------------------------------------------------
input_path = "/content/drive/MyDrive/2b09dea6-e595-49ca-be15-0c40289d99ab.png"

img = cv2.imread(input_path, cv2.IMREAD_GRAYSCALE)

if img is None:
    raise RuntimeError("Could not read input image.")

H, W = img.shape

print("\nINPUT")
print("-" * 70)
print("Input shape :", img.shape)

# ------------------------------------------------------------
# Tile settings
# ------------------------------------------------------------
TILE = 32
SCALE = 2

out_H = H * SCALE
out_W = W * SCALE

output = np.zeros((out_H, out_W), dtype=np.float32)

print("Tile size   :", TILE)
print("Scale       :", SCALE)
print("Output size :", (out_H, out_W))

# ------------------------------------------------------------
# Process tiles
# ------------------------------------------------------------
with torch.no_grad():

    for y in range(0, H, TILE):

        for x0 in range(0, W, TILE):

            y1 = min(y + TILE, H)
            x1 = min(x0 + TILE, W)

            tile = img[y:y1, x0:x1]

            # Pad tile to 32x32
            th, tw = tile.shape

            padded = np.zeros((TILE, TILE), dtype=np.uint8)
            padded[:th, :tw] = tile

            tile_f = padded.astype(np.float32) / 255.0

            inp = (
                torch.from_numpy(tile_f)
                .unsqueeze(0)
                .unsqueeze(0)
                .to(device)
            )

            pred = model(inp)

            pred = pred.squeeze().cpu().numpy()

            # Remove padding after 2x upscale
            pred = pred[:th * SCALE, :tw * SCALE]

            oy = y * SCALE
            ox = x0 * SCALE

            output[
                oy:oy + th * SCALE,
                ox:ox + tw * SCALE
            ] = pred

            del inp
            del pred

            if torch.cuda.is_available():
                torch.cuda.empty_cache()

# ------------------------------------------------------------
# Save output
# ------------------------------------------------------------
output = np.clip(output, 0.0, 1.0)
output_u8 = (output * 255.0).round().astype(np.uint8)

output_dir = "/content/drive/MyDrive/SwinIR_Project/final_test_visuals"
os.makedirs(output_dir, exist_ok=True)

base = os.path.splitext(os.path.basename(input_path))[0]

output_path = os.path.join(
    output_dir,
    base + "_SwinIR_2x.png"
)

cv2.imwrite(output_path, output_u8)

# ------------------------------------------------------------
# Verification
# ------------------------------------------------------------
print("\nRESULT")
print("-" * 70)
print("Output shape :", output_u8.shape)
print("Expected     :", (H * 2, W * 2))
print("Output min   :", output_u8.min())
print("Output max   :", output_u8.max())
print("Saved to     :", output_path)

print("\n" + "=" * 70)

if output_u8.shape == (H * 2, W * 2):
    print("✅ STEP 62B PASS")
    print("✅ FULL IMAGE PROCESSED TILE-BY-TILE")
    print("✅ EXACT 2X OUTPUT")
    print("✅ OUTPUT SAVED")
else:
    print("❌ STEP 62B FAILED")

print("=" * 70)

print("=" * 70)
print("STEP 63 — FINAL OUTPUT VALIDATION")
print("=" * 70)

