image_files = []

for folder in folders:
    if os.path.exists(folder):
        for ext in ["*.png", "*.jpg", "*.jpeg"]:
            image_files.extend(glob.glob(os.path.join(folder, ext)))

image_files = sorted(list(set(image_files)))[:5]

print("\nImages selected :", len(image_files))

if len(image_files) == 0:
    raise RuntimeError("No test images found.")

results = []

for idx, path in enumerate(image_files, 1):

    img = cv2.imread(path, cv2.IMREAD_GRAYSCALE)

    if img is None:
        print(f"[{idx}] SKIP — unreadable")
        continue

    H, W = img.shape

    TILE = 32
    SCALE = 2

    out = np.zeros((H * 2, W * 2), dtype=np.float32)

    with torch.no_grad():

        for y in range(0, H, TILE):
            for x0 in range(0, W, TILE):

                y1 = min(y + TILE, H)
                x1 = min(x0 + TILE, W)

                tile = img[y:y1, x0:x1]

                th, tw = tile.shape

                padded = np.zeros((TILE, TILE), dtype=np.uint8)
                padded[:th, :tw] = tile

                tensor = (
                    torch.from_numpy(
                        padded.astype(np.float32) / 255.0
                    )
                    .unsqueeze(0)
                    .unsqueeze(0)
                    .to(device)
                )

                pred = model(tensor)

                pred = pred.squeeze().cpu().numpy()

                out[
                    y * 2:y * 2 + th * 2,
                    x0 * 2:x0 * 2 + tw * 2
                ] = pred[:th * 2, :tw * 2]

                del tensor
                del pred

    out = np.clip(out, 0, 1)
    out_u8 = (out * 255).round().astype(np.uint8)

    expected = (H * 2, W * 2)

    shape_ok = out_u8.shape == expected
    finite_ok = np.isfinite(out).all()
    range_ok = 0 <= out_u8.min() <= out_u8.max() <= 255

    results.append(
        (os.path.basename(path), img.shape, out_u8.shape,
         shape_ok, finite_ok, range_ok)
    )

    print(
        f"[{idx}] {os.path.basename(path)} | "
        f"{img.shape} -> {out_u8.shape} | "
        f"PASS={shape_ok and finite_ok and range_ok}"
    )

    if torch.cuda.is_available():
        torch.cuda.empty_cache()

print("\n" + "=" * 70)

all_pass = all(
    r[3] and r[4] and r[5]
    for r in results
)

if all_pass:
    print("✅ STEP 65 PASS")
    print("✅ ALL SELECTED IMAGES PASSED")
    print("✅ 2X INFERENCE ROBUST")
else:
    print("❌ STEP 65 FAILED")

print("=" * 70)

