import os
import cv2
import numpy as np

from skimage.metrics import peak_signal_noise_ratio
from skimage.metrics import structural_similarity

eval_dir = "/content/drive/MyDrive/SwinIR_Project/denoising_evaluation"

gaussian_dir = os.path.join(eval_dir, "gaussian")
speckle_dir = os.path.join(eval_dir, "speckle")

input_files = [
    "/content/drive/MyDrive/SwinIR_Project/demo_results/000008_before_after.png",
    "/content/drive/MyDrive/SwinIR_Project/demo_results/001086_before_after.png",
    "/content/drive/MyDrive/SwinIR_Project/demo_results/001552_before_after.png",
    "/content/drive/MyDrive/SwinIR_Project/demo_results/001599_before_after.png",
    "/content/drive/MyDrive/SwinIR_Project/demo_results/001863_before_after.png",
]


def metrics(gt, pred):

    gt = gt.astype(np.float32) / 255.0
    pred = pred.astype(np.float32) / 255.0

    psnr = peak_signal_noise_ratio(
        gt,
        pred,
        data_range=1.0
    )

    ssim = structural_similarity(
        gt,
        pred,
        data_range=1.0
    )

    return psnr, ssim


gaussian_results = []
speckle_results = []


for idx, input_path in enumerate(input_files, 1):

    base = os.path.splitext(
        os.path.basename(input_path)
    )[0]

    clean = cv2.imread(
        input_path,
        cv2.IMREAD_GRAYSCALE
    )

    clean_2x = cv2.resize(
        clean,
        (
            clean.shape[1] * 2,
            clean.shape[0] * 2
        ),
        interpolation=cv2.INTER_CUBIC
    )

    # ========================================================
    # GAUSSIAN
    # ========================================================

    noisy_g = cv2.imread(
        os.path.join(
            gaussian_dir,
            base + "_NOISY.png"
        ),
        cv2.IMREAD_GRAYSCALE
    )

    restored_g = cv2.imread(
        os.path.join(
            gaussian_dir,
            base + "_RESTORED_2X.png"
        ),
        cv2.IMREAD_GRAYSCALE
    )

    # Baseline: noisy image resized to 2X
    noisy_g_2x = cv2.resize(
        noisy_g,
        (
            clean_2x.shape[1],
            clean_2x.shape[0]
        ),
        interpolation=cv2.INTER_CUBIC
    )

    base_g_psnr, base_g_ssim = metrics(
        clean_2x,
        noisy_g_2x
    )

    rest_g_psnr, rest_g_ssim = metrics(
        clean_2x,
        restored_g
    )

    delta_g_psnr = rest_g_psnr - base_g_psnr
    delta_g_ssim = rest_g_ssim - base_g_ssim

    gaussian_results.append(
        (
            base,
            base_g_psnr,
            rest_g_psnr,
            delta_g_psnr,
            base_g_ssim,
            rest_g_ssim,
            delta_g_ssim
        )
    )

    # ========================================================
    # SPECKLE
    # ========================================================

    noisy_s = cv2.imread(
        os.path.join(
            speckle_dir,
            base + "_NOISY.png"
        ),
        cv2.IMREAD_GRAYSCALE
    )

    restored_s = cv2.imread(
        os.path.join(
            speckle_dir,
            base + "_RESTORED_2X.png"
        ),
        cv2.IMREAD_GRAYSCALE
    )

    noisy_s_2x = cv2.resize(
        noisy_s,
        (
            clean_2x.shape[1],
            clean_2x.shape[0]
        ),
        interpolation=cv2.INTER_CUBIC
    )

    base_s_psnr, base_s_ssim = metrics(
        clean_2x,
        noisy_s_2x
    )

    rest_s_psnr, rest_s_ssim = metrics(
        clean_2x,
        restored_s
    )

    delta_s_psnr = rest_s_psnr - base_s_psnr
    delta_s_ssim = rest_s_ssim - base_s_ssim

    speckle_results.append(
        (
            base,
            base_s_psnr,
            rest_s_psnr,
            delta_s_psnr,
            base_s_ssim,
            rest_s_ssim,
            delta_s_ssim
        )
    )


# ============================================================
# PRINT GAUSSIAN
# ============================================================

print("\nGAUSSIAN BASELINE vs RESTORED")
print("-" * 70)

for r in gaussian_results:

    name, bp, rp, dp, bs, rs, ds = r

    print(
        f"{name:32s} "
        f"PSNR {bp:.2f} -> {rp:.2f} "
        f"(Δ {dp:+.2f}) | "
        f"SSIM {bs:.4f} -> {rs:.4f} "
        f"(Δ {ds:+.4f})"
    )


# ============================================================
# PRINT SPECKLE
# ============================================================

print("\nSPECKLE BASELINE vs RESTORED")
print("-" * 70)

for r in speckle_results:

    name, bp, rp, dp, bs, rs, ds = r

    print(
        f"{name:32s} "
        f"PSNR {bp:.2f} -> {rp:.2f} "
        f"(Δ {dp:+.2f}) | "
        f"SSIM {bs:.4f} -> {rs:.4f} "
        f"(Δ {ds:+.4f})"
    )


# ============================================================
# AVERAGES
# ============================================================

g_base_psnr = np.mean([r[1] for r in gaussian_results])
g_rest_psnr = np.mean([r[2] for r in gaussian_results])
g_delta_psnr = np.mean([r[3] for r in gaussian_results])

g_base_ssim = np.mean([r[4] for r in gaussian_results])
g_rest_ssim = np.mean([r[5] for r in gaussian_results])
g_delta_ssim = np.mean([r[6] for r in gaussian_results])


s_base_psnr = np.mean([r[1] for r in speckle_results])
s_rest_psnr = np.mean([r[2] for r in speckle_results])
s_delta_psnr = np.mean([r[3] for r in speckle_results])

s_base_ssim = np.mean([r[4] for r in speckle_results])
s_rest_ssim = np.mean([r[5] for r in speckle_results])
s_delta_ssim = np.mean([r[6] for r in speckle_results])


print("\n" + "=" * 70)
