lr_available = [x for x in val_ids if x in noisy_ids]

complete_pairs = [
    x for x in val_ids
    if x in gt_ids and x in noisy_ids
]

missing_gt = [x for x in val_ids if x not in gt_ids]
missing_lr = [x for x in val_ids if x not in noisy_ids]

# ------------------------------------------------------------
# Results
# ------------------------------------------------------------
