print("RESULT")
print("-" * 80)

print("Validation IDs          :", len(val_ids))
print("GT available            :", len(gt_available))
print("NoisyLR available       :", len(lr_available))
print("Complete paired samples :", len(complete_pairs))
print("Missing GT              :", len(missing_gt))
print("Missing NoisyLR         :", len(missing_lr))

# ------------------------------------------------------------
