keywords = [
    "AdaptiveDetailRefinement",
    "adaptive_detail",
    "ADR",
    "innovation_refinement"
]

# Search likely Python files only
search_roots = [
    PROJECT,
    Path("/content")
]

found_files = set()

for root in search_roots:

    if not root.exists():
        continue

    print(f"\nSearching: {root}")

    try:
        for path in root.rglob("*.py"):

            # Skip very large/system locations
            if any(part in path.parts for part in [
                ".cache",
                "site-packages",
                "dist-packages"
            ]):
                continue

            try:
                text = path.read_text(errors="ignore")
            except Exception:
                continue

            matches = []

            for i, line in enumerate(text.splitlines(), start=1):

                if any(k.lower() in line.lower() for k in keywords):
                    matches.append((i, line.strip()))

            if matches:

                found_files.add(path)

                print("\n" + "-" * 70)
                print("FILE:", path)
                print("-" * 70)

                for line_no, line in matches[:30]:
                    print(f"{line_no:5}: {line}")

    except Exception as e:
        print("Search warning:", e)

