import sys
import importlib.util
from pathlib import Path

import numpy as np
import torch

PROJECT = Path("/content/drive/MyDrive/SwinIR_Project")
RUN_FILE = PROJECT / "submission" / "run.py"
MODEL_FILE = PROJECT / "submission" / "models" / "swinir_epoch_20.pth"
ADR_FILE = PROJECT / "innovation_refinement_FINAL.pth"

print("=" * 80)
print("STEP 15 — EXACT MODEL COMPATIBILITY TEST")
print("=" * 80)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("\nDevice:", device)

# ------------------------------------------------------------
# Check model file
# ------------------------------------------------------------
print("\n" + "-" * 80)
print("SWINIR CHECKPOINT")
print("-" * 80)

print("Submission checkpoint:", MODEL_FILE)
print("Exists:", MODEL_FILE.exists())

if MODEL_FILE.exists():
    print(
        "Size:",
        f"{MODEL_FILE.stat().st_size / (1024*1024):.2f} MB"
    )

# ------------------------------------------------------------
# Import EXACT submission run.py
# ------------------------------------------------------------
print("\n" + "-" * 80)
print("LOADING EXACT submission/run.py")
print("-" * 80)

spec = importlib.util.spec_from_file_location(
    "submission_run",
    str(RUN_FILE)
)

submission_run = importlib.util.module_from_spec(spec)
spec.loader.exec_module(submission_run)

print("✅ submission/run.py imported")

# ------------------------------------------------------------
# Load exact SwinIR
# ------------------------------------------------------------
print("\nLoading Epoch-20 SwinIR...")

model = submission_run.load_model(device)

print("✅ SwinIR loaded")
print("Model class:", type(model).__name__)

# ------------------------------------------------------------
# Verify model parameter count
# ------------------------------------------------------------
parameter_count = sum(
    p.numel() for p in model.parameters()
)

print("Model parameters:", parameter_count)

# ------------------------------------------------------------
# Load one REAL validation sample directly from ZIP
# ------------------------------------------------------------
import json
import zipfile

SPLIT_FILE = PROJECT / "train_val_split.json"
ZIP_FILE = Path("/content/drive/MyDrive/dataset/train.zip")

with open(SPLIT_FILE, "r") as f:
    split = json.load(f)

sample_id = Path(str(split["val"][0])).stem

print("\nValidation sample:", sample_id)

with zipfile.ZipFile(ZIP_FILE, "r") as z:

    lr_path = f"train/NoisyLR/{sample_id}.npy"
    gt_path = f"train/GT/{sample_id}.npy"

    lr = np.load(z.open(lr_path))
    gt = np.load(z.open(gt_path))

print("Original LR shape:", lr.shape)
print("Original GT shape:", gt.shape)

# ------------------------------------------------------------
# Use EXACT submission preprocessing
# ------------------------------------------------------------
lr = submission_run.prepare_input(lr)

print("Prepared LR shape:", lr.shape)
print("Prepared LR min :", float(lr.min()))
print("Prepared LR max :", float(lr.max()))

# ------------------------------------------------------------
# Exact submission inference
# ------------------------------------------------------------
print("\nRunning exact Epoch-20 inference...")

with torch.no_grad():

    restored = submission_run.restore(
        model,
        lr,
        device
    )

print("✅ SwinIR inference successful")

print("\nSwinIR output")
print("Shape :", restored.shape)
print("Dtype :", restored.dtype)
print("Min   :", float(restored.min()))
print("Max   :", float(restored.max()))
print("Mean  :", float(restored.mean()))
print("Finite:", bool(np.isfinite(restored).all()))

# ------------------------------------------------------------
# Reconstruct EXACT ADR architecture from checkpoint shapes
# ------------------------------------------------------------
print("\n" + "-" * 80)
print("RECONSTRUCTING VERIFIED ADR ARCHITECTURE")
print("-" * 80)

class AdaptiveDetailRefinement(torch.nn.Module):

    def __init__(self):
        super().__init__()

        self.feature = torch.nn.Sequential(

            torch.nn.Conv2d(
                1, 16,
                kernel_size=3,
                padding=1
            ),

            torch.nn.ReLU(inplace=True),

            torch.nn.Conv2d(
                16, 16,
                kernel_size=3,
                padding=1
            ),

            torch.nn.ReLU(inplace=True),

            torch.nn.Conv2d(
                16, 1,
                kernel_size=3,
                padding=1
            )
        )

        self.alpha = torch.nn.Parameter(
            torch.tensor(1.0)
        )

    def forward(self, x):

        residual = self.feature(x)

        return torch.clamp(
            x + self.alpha * residual,
            0.0,
            1.0
        )

# ------------------------------------------------------------
# Load ADR checkpoint
# ------------------------------------------------------------
adr_checkpoint = torch.load(
    ADR_FILE,
    map_location=device,
    weights_only=False
)

adr = AdaptiveDetailRefinement().to(device)

adr.load_state_dict(
    adr_checkpoint["model_state_dict"],
    strict=True
)

adr.eval()

print("✅ ADR checkpoint loaded")
print("ADR parameters:", sum(
    p.numel() for p in adr.parameters()
))

print("Expected ADR parameters: 2626")

# ------------------------------------------------------------
# One ADR forward pass
# ------------------------------------------------------------
tensor = torch.from_numpy(
    restored
).float().unsqueeze(0).unsqueeze(0).to(device)

with torch.no_grad():
    refined = adr(tensor)

refined = (
    refined
    .squeeze()
    .detach()
    .cpu()
    .numpy()
    .astype(np.float32)
)

print("\nADR output")
print("Shape :", refined.shape)
print("Dtype :", refined.dtype)
print("Min   :", float(refined.min()))
print("Max   :", float(refined.max()))
print("Mean  :", float(refined.mean()))
print("Finite:", bool(np.isfinite(refined).all()))

# ------------------------------------------------------------
# Final compatibility checks
# ------------------------------------------------------------
print("\n" + "=" * 80)
print("STEP 15 RESULT")
print("=" * 80)

checks = {
    "SwinIR output is 256x256": restored.shape == (256, 256),
    "ADR output is 256x256": refined.shape == (256, 256),
    "SwinIR finite": np.isfinite(restored).all(),
    "ADR finite": np.isfinite(refined).all(),
    "SwinIR range valid": restored.min() >= 0 and restored.max() <= 1,
    "ADR range valid": refined.min() >= 0 and refined.max() <= 1,
    "ADR parameter count = 2626":
        sum(p.numel() for p in adr.parameters()) == 2626
}

for name, result in checks.items():
    print(
        f"{'✅' if result else '❌'} {name}"
    )

if all(checks.values()):
    print("\n🎯 EXACT SWINIR + ADR PIPELINE VERIFIED")
    print("➡️ Ready for robustness evaluation.")
else:
    print("\n⚠️ Compatibility check failed.")
    print("➡️ STOP. Do not run robustness yet.")

print("=" * 80)

